(10405213, 104052, 'P32-C5-L2-O13', null, 13, 'أن يوضّح الطالب أن الموجات الكهرومغناطيسية تنقل الطاقة والمعلومات، مع أمثلة من الميكروويف والأشعة تحت الحمراء والأشعة فوق البنفسجية', 'أن يوضّح الطالب أن الموجات الكهرومغناطيسية تنقل الطاقة والمعلومات، مع أمثلة من الميكروويف والأشعة تحت الحمراء والأشعة فوق البنفسجية', '[]'::jsonb, 'أن يوضّح الطالب أن الموجات الكهرومغناطيسية تنقل الطاقة والمعلومات، مع أمثلة من الميكروويف والأشعة تحت الحمراء والأشعة فوق البنفسجية', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الطاقة من الموجات","الميكروويف","الأشعة فوق البنفسجية"]'::jsonb, null, '[152,153,157]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص152 «الطاقة من الموجات»: الميكروويف وتحت الحمراء تسارع الإلكترونات في الجزيئات فتولد طاقة حرارية، والضوء ينقل الطاقة في الأفلام، والأشعة فوق البنفسجية تسبب تفاعلات كيميائية؛ ص153 السؤال 27؛ ص157 دليل المراجعة.', null, 'approved', '2026-11-24'::timestamptz),
(10405214, 104052, 'P32-C5-L2-O14', null, 14, 'أن يستقصي الطالب عمليًا قدرة مواد مختلفة على حجب موجات الراديو، ويستنتج صفات المواد الحاجبة', 'أن يستقصي الطالب عمليًا قدرة مواد مختلفة على حجب موجات الراديو، ويستنتج صفات المواد الحاجبة', '[]'::jsonb, 'أن يستقصي الطالب عمليًا قدرة مواد مختلفة على حجب موجات الراديو، ويستنتج صفات المواد الحاجبة', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات ومهارات', '["حجب الموجات الكهرومغناطيسية","موجات الراديو","المواد الموصلة"]'::jsonb, null, '[154,155]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص154–155 مختبر الفيزياء «حجب الموجات الكهرومغناطيسية»: سؤال التجربة والخطوات وجدول البيانات وأسئلة التحليل (أي المواد أكثر فاعلية، والعلاقة بين الطول الموجي واتساع فتحات المادة).', null, 'approved', '2026-11-24'::timestamptz),
(10406101, 104061, 'P32-C6-L1-O01', null, 1, 'أن يصف الطالب الطيف المنبعث من جسم ساخن.', 'أن يصف الطالب الطيف المنبعث من جسم ساخن.', '[]'::jsonb, 'أن يصف الطالب الطيف المنبعث من جسم ساخن.', 'الصياغة سليمة وقابلة للقياس ومطابقة لمصطلحات الكتاب', 'لا تغيير', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["طيف الانبعاث","الجسم المتوهج","درجة الحرارة"]'::jsonb, null, '[165,166]'::jsonb, 'مغطى', 'ص165 أهداف الدرس «تصف الطيف المنبعث من جسم ساخن»؛ ص166 «الإشعاع من الأجسام المتوهجة» وتعريف طيف الانبعاث والشكل 1-6 (أطياف الانبعاث عند 4000K و5800K و8000K) والعلاقة P ∝ T⁴؛ ص176 سؤال المراجعة 11؛ ص184 السؤالان 41 و42.', null, 'approved', '2026-11-24'::timestamptz),
(10406102, 104061, 'P32-C6-L1-O02', null, 2, 'أن يشرح الطالب نظرية بلانك.', 'أن يشرح الطالب فرضية بلانك في تكمية طاقة الذرات المهتزة (E = nhf) وكيف فسّرت طيف الجسم المتوهج', '[]'::jsonb, 'أن يشرح الطالب فرضية بلانك في تكمية طاقة الذرات المهتزة (E = nhf) وكيف فسّرت طيف الجسم المتوهج', '«نظرية بلانك» عامة؛ حُدّد مضمونها كما في الكتاب (الطاقة مكمّاة وتساوي nhf، والذرة تبعث إشعاعًا عند تغيّر طاقة اهتزازها) ليصبح الهدف قابلًا للقياس', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["فرضية بلانك","تكمية الطاقة","مكمّاة","ثابت بلانك","E = nhf"]'::jsonb, null, '[167,183,184]'::jsonb, 'مغطى', 'ص167 «طاقة الاهتزاز E = nhf» وتعريف «مكمّاة» وقيمة h = 6.626×10⁻³⁴ J/Hz؛ ص183 دليل مراجعة الفصل؛ ص184 السؤالان 31 و32 (تكمية الطاقة)، ص185 السؤال 46.', null, 'approved', '2026-11-24'::timestamptz),
(10406103, 104061, 'P32-C6-L1-O03', null, 3, 'أن يفسر الطالب التأثير الكهروضوئي.', 'أن يعرّف الطالب التأثير الكهروضوئي ويصف حدوثه في الخلية الكهروضوئية وشرط تردد العتبة', '[]'::jsonb, 'أن يعرّف الطالب التأثير الكهروضوئي ويصف حدوثه في الخلية الكهروضوئية وشرط تردد العتبة', 'حُدّد المقصود بالتفسير لتمييز الهدف عن O05 (تفسير أينشتاين)؛ ويُقاس بتعريف الظاهرة ووصف الخلية الكهروضوئية وشرط تردد العتبة كما في الكتاب', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["التأثير الكهروضوئي","الخلية الكهروضوئية","الإلكترونات الضوئية","تردد العتبة"]'::jsonb, null, '[168,169]'::jsonb, 'مغطى', 'ص168 تعريف التأثير الكهروضوئي (لوح الزنك والأشعة فوق البنفسجية)، والشكل 2-6 (الخلية الكهروضوئية)، وفقرة «تردد العتبة»؛ ص169 أثر الشدة والتردد في تحرير الإلكترونات.', null, 'approved', '2026-11-24'::timestamptz),
(10406104, 104061, 'P32-C6-L1-O04', null, 4, 'أن يوضح الطالب فشل نظرية الموجات الكهرومغناطيسية في تفسير التأثير الكهروضوئي.', 'أن يوضّح الطالب سبب فشل نظرية الموجات الكهرومغناطيسية في تفسير التأثير الكهروضوئي', '[]'::jsonb, 'أن يوضّح الطالب سبب فشل نظرية الموجات الكهرومغناطيسية في تفسير التأثير الكهروضوئي', 'إضافة «سبب» لأن المطلوب تعليل الفشل لا ذكره، وتشكيل «يوضّح»', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["نظرية الموجات الكهرومغناطيسية","التأثير الكهروضوئي","شدة الإشعاع","تردد العتبة"]'::jsonb, null, '[168,169]'::jsonb, 'مغطى', 'ص168 «هذه النتيجة مناقضة للنظرية الكهرومغناطيسية»؛ ص169 «كيف تفسّر نظرية الموجات الكهرومغناطيسية التأثير الكهروضوئي؟ إنها غير قادرة على ذلك…» (الشدة لا التردد، وانطلاق الإلكترونات مباشرة).', null, 'approved', '2026-11-24'::timestamptz),
(10406105, 104061, 'P32-C6-L1-O05', null, 5, 'أن يفسر الطالب نظرية اينشتاين في تفسير التأثير الكهروضوئي.', 'أن يوضّح الطالب كيف تفسّر نظرية أينشتاين للفوتون التأثير الكهروضوئي ووجود تردد العتبة', '[]'::jsonb, 'أن يوضّح الطالب كيف تفسّر نظرية أينشتاين للفوتون التأثير الكهروضوئي ووجود تردد العتبة', 'تكرار «يفسر… في تفسير» ركيك، وكتابة «أينشتاين» بالهمزة كما في الكتاب، وتحديد المضمون (الفوتون وتردد العتبة)', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["نظرية أينشتاين","الفوتون","تكمية الطاقة","تردد العتبة","KE = hf − hf0"]'::jsonb, null, '[169,170,183]'::jsonb, 'مغطى', 'ص169 «الفوتونات وتكمية الطاقة» وتعريف الفوتون وE = hf؛ ص170 تفسير أينشتاين لوجود تردد العتبة ومعادلة الطاقة الحركية KE = hf − hf0؛ ص184 السؤالان 34 و35.', null, 'approved', '2026-11-24'::timestamptz),
