select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ العبارات الآتية تصف التيار الكهربائي في دائرة التوالي الكهربائية؟', null, null, '["يقل التيار تدريجيًّا كلما مر في عنصر من عناصر الدائرة","يكون التيار نفسه في كل جزء من أجزاء الدائرة","يكون التيار أكبر ما يمكن قرب القطب الموجب للبطارية","يتوزع التيار بين عناصر الدائرة بحسب مقاوماتها"]'::jsonb, 'فهم', 'وصف خاصية', 'سهل', 'الكتاب ص 43 — تعريف دائرة التوالي'),
('mcq', 2, 'في دائرة التوالي الآتية ثلاثة أميترات، وقراءة الأميتر $\mathrm{A}_1$ تساوي 0.30 A. ما قراءتا الأميترين $\mathrm{A}_2$ و$\mathrm{A}_3$ على الترتيب؟', null, '[{"src":"qimg/phys32/c2l1-o01-amps.svg","alt":"دائرة توالٍ: بطارية على الضلع الأيسر قطبها الموجب في الأعلى. في السلك العلوي أميتر A1 مكتوب تحته 0.30 A ثم مقاومة RA. في الضلع الأيمن أميتر A2. في السلك السفلي مقاومة RB ثم أميتر A3 ثم يعود السلك إلى البطارية. مسار واحد للتيار بلا تفرعات."}]'::jsonb, '["0.15 A و0.15 A","0.20 A و0.10 A","0.30 A وصفر","0.30 A و0.30 A"]'::jsonb, 'فهم', 'تفسير قراءة أجهزة', 'سهل', 'الكتاب ص 43 — الشكل 2-3 وقراءات الأميترات'),
('mcq', 3, 'في الدائرة الآتية وُصلت مقاومتان $\mathrm{R}_\mathrm{A}$ و$\mathrm{R}_\mathrm{B}$ على التوالي ببطارية جهدها 12 V، فكانت قراءة الفولتمتر $\mathrm{V}_\mathrm{A}$ تساوي 4.5 V. ما قراءة الفولتمتر $\mathrm{V}_\mathrm{B}$؟', null, '[{"src":"qimg/phys32/c2l1-o01-drops.svg","alt":"دائرة توالٍ: بطارية جهدها 12 V على الضلع الأيسر، والسلك العلوي فيه مقاومة RA، والضلع الأيمن فيه مقاومة RB، ثم يعود السلك السفلي إلى البطارية. فولتمتر VA موصول بين طرفي RA بسلكين يتفرعان من طرفيها، وفولتمتر VB موصول بين طرفي RB. لا تظهر قراءات الفولتمترين على الرسم."}]'::jsonb, '["7.5 V","4.5 V","12 V","16.5 V"]'::jsonb, 'فهم', 'تطبيق علاقة وصفية', 'متوسط', 'الكتاب ص 43 — مجموع الهبوط في الجهد يساوي جهد المصدر'),
('mcq', 4, 'دائرة توالٍ فيها ثلاثة مصابيح متماثلة متصلة ببطارية. ماذا يحدث للمصباحين الآخرين إذا احترق فتيل أحد المصابيح؟', null, null, '["يزداد سطوعهما؛ لأن التيار يتوزع عليهما فقط","يبقيان مضيئين بالسطوع نفسه؛ لأن لكل منهما مسارًا مستقلًّا","ينطفئان؛ لأن المسار الوحيد للتيار انقطع","ينطفئ المصباح الذي يلي المحترق فقط في اتجاه التيار"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 62 — السؤال 30'),
('mcq', 5, 'أيّ الدوائر الآتية يكون فيها المصباحان موصولين على التوالي؟', null, '[{"src":"qimg/phys32/c2l1-o01-which.svg","alt":"ثلاث دوائر مرقمة، في كل منها بطارية على اليسار ومصباحان. الدائرة (1): المصباحان متجاوران في السلك العلوي ثم يعود السلك إلى البطارية دون أي تفرع. الدائرة (2): السلك العلوي يتفرع عند نقطة توصيل إلى فرعين رأسيين في كل منهما مصباح، ويلتقي الفرعان عند نقطة توصيل في السلك السفلي. الدائرة (3): مصباح في السلك العلوي ومصباح آخر في السلك السفلي، ولا توجد أي نقطة تفرع."}]'::jsonb, '["(1) فقط","(2) فقط","(2) و(3)","(1) و(3)"]'::jsonb, 'تحليل', 'تصنيف دوائر', 'صعب', 'الكتاب ص 42–43 — دائرة التوالي'),
('mcq', 6, 'عند مرور تيار في مصباح موصول في دائرة توالٍ يكون هناك هبوط في الجهد بين طرفيه. ماذا يعني هذا الهبوط في الجهد؟', null, null, '["أن جزءًا من التيار يُستهلك في المصباح فيخرج منه تيار أقل","أن الطاقة الكهربائية تتحول في المصباح إلى طاقة حرارية وضوئية","أن الشحنات تتجمع عند أحد طرفي المصباح","أن مقاومة المصباح تساوي صفرًا"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 43 — الهبوط في الجهد عبر المصباح'),
('mcq', 7, 'لماذا يكون التيار متساويًا في جميع أجزاء دائرة التوالي الكهربائية؟', null, null, '["لأن مقاومات العناصر في دائرة التوالي متساوية دائمًا","لأن فرق الجهد بين طرفي كل عنصر يساوي جهد المصدر","لأن للشحنة مسارًا واحدًا، وهي لا تفنى، فالداخل منها إلى أي جزء يساوي الخارج منه","لأن البطارية تزود كل عنصر بتيار مستقل عن العناصر الأخرى"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 42 — حفظ الشحنة في دائرة التوالي'),
('essay', 1, 'صف دائرة التوالي الكهربائية من حيث: (a) عدد مسارات التيار، (b) مقدار التيار في أجزائها، (c) العلاقة بين الهبوط في الجهد عبر عناصرها وجهد المصدر، (d) ما يحدث للعناصر الأخرى إذا انقطع المسار عند أحد العناصر.', null, null, null, 'فهم', 'وصف', 'سهل', 'الكتاب ص 43 و61–62 — دائرة التوالي والسؤال 30'),
('essay', 2, 'في الدائرة الآتية مصباحان مختلفان $\mathrm{L}_1$ و$\mathrm{L}_2$ موصولان على التوالي ببطارية جهدها 9.0 V، والفولتمتر بين طرفي $\mathrm{L}_1$ يقرأ 3.0 V. (a) إذا كانت قراءة الأميتر $\mathrm{A}_1$ تساوي 0.25 A فما قراءتا $\mathrm{A}_2$ و$\mathrm{A}_3$؟ علّل. (b) ما الهبوط في الجهد عبر $\mathrm{L}_2$؟ (c) أيّ المصباحين مقاومته أكبر؟ علّل دون حساب، ثم تحقق بالحساب.', null, '[{"src":"qimg/phys32/c2l1-o01-e2.svg","alt":"دائرة توالٍ: بطارية جهدها 9.0 V على اليسار. في السلك العلوي أميتر A1 ثم مصباح L1، وفولتمتر موصول بين طرفي L1 مكتوب تحته 3.0 V. في الضلع الأيمن أميتر A2. في السلك السفلي مصباح L2 ثم أميتر A3 ثم يعود السلك إلى البطارية."}]'::jsonb, null, 'تحليل', 'تحليل دائرة', 'متوسط', 'الكتاب ص 43 — الشكل 2-3 والهبوط في الجهد'),
('essay', 3, 'قال طالب: «في دائرة التوالي يضيء المصباح الأقرب إلى القطب الموجب للبطارية أكثر من غيره؛ لأن التيار يصل إليه أولًا فيستهلك جزءًا منه». قوّم هذه العبارة، ثم صف تجربة بسيطة باستخدام الأميترات تختبر بها صحتها، وما النتيجة المتوقعة.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 42–43 — توقعات الطلاب والشكل 2-3')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'دائرة التوالي هي الدائرة التي يمر التيار نفسه في كل جزء من أجزائها؛ لأن للشحنة مسارًا واحدًا، والشحنة لا تفنى ولا تُستحدث.', '["الشحنة لا تفنى ولا تُستهلك في العناصر؛ ما يتحول هو الطاقة، أما التيار فيبقى نفسه.","","لا يوجد موضع في دائرة التوالي يكون التيار فيه أكبر؛ فللشحنة مسار واحد فقط.","توزع التيار بين المسارات صفة دائرة التوازي؛ أما في دائرة التوالي فهناك مسار واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.329Z"}'::jsonb),
('mcq', 2, 3, 'الأميترات الثلاثة موصولة على التوالي في مسار واحد، والتيار في دائرة التوالي متساوٍ في جميع أجزائها، فتقرأ جميعها 0.30 A.', '["قسمة التيار بين الأميترين خطأ؛ فلا تفرع في دائرة التوالي.","افتراض أن كل مقاومة «تستهلك» جزءًا من التيار خطأ؛ فالتيار نفسه في جميع أجزاء الدائرة.","افتراض أن التيار يُستهلك كله قبل عودته إلى البطارية خطأ؛ فالشحنة الداخلة إلى الدائرة تساوي الخارجة منها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.330Z"}'::jsonb),
('mcq', 3, 0, 'في دائرة التوالي يساوي مجموع الهبوط في الجهد عبر المقاومات جهد المصدر: $\mathrm{V}_{\text{مصدر}} = \mathrm{V}_\mathrm{A} + \mathrm{V}_\mathrm{B}$، إذن $\mathrm{V}_\mathrm{B} = 12 - 4.5 = 7.5\ \text{V}$.', '["","افتراض تساوي الهبوط في الجهد عبر المقاومتين خطأ؛ فالهبوط يتساوى فقط إذا تساوت المقاومتان.","افتراض أن فرق الجهد بين طرفي كل مقاومة يساوي جهد البطارية صفة التوازي لا التوالي.","جمع جهد البطارية مع الهبوط عبر $\\mathrm{R}_\\mathrm{A}$ خطأ؛ فمجموع الهبوطين هو الذي يساوي جهد المصدر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.331Z"}'::jsonb),
('mcq', 4, 2, 'ينطفئ المصباحان؛ لأن المسار الوحيد للتيار انقطع: في دائرة التوالي للتيار مسار واحد، فإذا احترق فتيل أي مصباح انفتحت الدائرة وتوقف التيار في جميع أجزائها، فتنطفئ المصابيح كلها.', '["لا يمر تيار أصلًا بعد انقطاع المسار الوحيد، فلا يزداد سطوع أي مصباح.","المسارات المستقلة صفة دائرة التوازي، أما في التوالي فالمسار واحد.","","انقطاع المسار في أي موضع يوقف التيار في الدائرة كلها، لا في جزء منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.331Z"}'::jsonb),
('mcq', 5, 3, 'يكون التوصيل على التوالي عندما يمر التيار نفسه في المصباحين عبر مسار واحد. في (1) و(3) لا توجد نقاط تفرع، فالتيار يمر في المصباح الأول ثم الثاني مهما كان موضعهما في الرسم. أما (2) ففيها نقطتا تفرع ومساران.', '["الدائرة (3) أيضًا ذات مسار واحد يمر في المصباحين، فلا يُشترط أن يكون المصباحان متجاورين في الرسم.","في الدائرة (2) يتفرع التيار إلى مسارين عند نقطة التوصيل، فالمصباحان فيها على التوازي.","الدائرة (2) فيها مساران للتيار فهي توازٍ، وإن صح الحكم على الدائرة (3).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.332Z"}'::jsonb),
('mcq', 6, 1, 'القدرة $\mathrm{P} = \mathrm{I}\mathrm{V}$؛ فوجود فرق في الجهد (هبوط) عبر المصباح يعني أن الطاقة الكهربائية تتحول فيه من شكل إلى آخر، ويُحسب الهبوط من $\mathrm{V} = \mathrm{I}\mathrm{R}$.', '["التيار لا يُستهلك؛ فالتيار نفسه يدخل المصباح ويخرج منه في دائرة التوالي.","","الشحنات لا تتجمع في أي جزء من الدائرة؛ فما يدخل منها يخرج.","لو كانت المقاومة صفرًا لكان الهبوط $\\mathrm{V} = \\mathrm{I}\\mathrm{R}$ صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.332Z"}'::jsonb),
('mcq', 7, 2, 'للشحنة في دائرة التوالي مسار واحد، وهي لا تفنى ولا تُستحدث، فالداخل منها إلى أي جزء في وحدة الزمن يساوي الخارج منه؛ أي أن التيار نفسه في جميع الأجزاء.', '["تساوي التيار لا يتطلب تساوي المقاومات؛ فالمقاومات المختلفة على التوالي يمر فيها التيار نفسه.","فرق الجهد بين طرفي كل عنصر في التوالي جزء من جهد المصدر لا يساويه.","","التيار المستقل لكل عنصر صفة الفروع في دائرة التوازي، لا التوالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.333Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) دائرة التوالي لها مسار واحد فقط يسلكه التيار. (b) يمر التيار نفسه في كل جزء من أجزائها؛ لأن الشحنة لا تفنى ولا تُستحدث. (c) مجموع الهبوط في الجهد عبر عناصرها يساوي جهد المصدر: $\mathrm{V}_{\text{مصدر}} = \mathrm{V}_\mathrm{A} + \mathrm{V}_\mathrm{B} + \ldots$ (d) إذا انقطع المسار عند أي عنصر (كاحتراق فتيل مصباح) يتوقف التيار في الدائرة كلها فتتوقف جميع العناصر عن العمل.', '["مسار واحد للتيار","التيار نفسه في جميع الأجزاء","مجموع الهبوط في الجهد يساوي جهد المصدر","انقطاع المسار يوقف التيار في الدائرة كلها"]'::jsonb, '[]'::jsonb, '[{"element":"عدد المسارات","marks":1},{"element":"التيار","marks":1},{"element":"الهبوط في الجهد","marks":1},{"element":"انقطاع المسار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التيار يقل بعد كل عنصر","القول إن فرق الجهد بين طرفي كل عنصر يساوي جهد المصدر","القول إن العناصر الأخرى تبقى تعمل عند انقطاع أحدها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.333Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{A}_2$ و$\mathrm{A}_3$ تقرآن 0.25 A؛ لأن الدائرة توالٍ لها مسار واحد، والتيار نفسه في جميع أجزائها. (b) مجموع الهبوط يساوي جهد المصدر: $\mathrm{V}_2 = 9.0 - 3.0 = 6.0\ \text{V}$. (c) يمر في المصباحين التيار نفسه، والهبوط عبر $\mathrm{L}_2$ أكبر، وبما أن $\mathrm{V} = \mathrm{I}\mathrm{R}$ فمقاومة $\mathrm{L}_2$ أكبر. حسابيًّا: $\mathrm{R}_1 = 3.0/0.25 = 12\ \Omega$ و$\mathrm{R}_2 = 6.0/0.25 = 24\ \Omega$.', '["قراءتا الأميترين 0.25 A مع التعليل بالمسار الواحد","الهبوط عبر $\\mathrm{L}_2$ يساوي 6.0 V","مقاومة $\\mathrm{L}_2$ أكبر لأن الهبوط أكبر والتيار نفسه","التحقق: 12 Ω و24 Ω"]'::jsonb, '["$\\mathrm{I}_2 = \\mathrm{I}_3 = \\mathrm{I}_1 = 0.25\\ \\text{A}$","$\\mathrm{V}_2 = \\mathrm{V}_{\\text{مصدر}} - \\mathrm{V}_1 = 9.0 - 3.0 = 6.0\\ \\text{V}$","$\\mathrm{R}_1 = \\frac{3.0\\ \\text{V}}{0.25\\ \\text{A}} = 12\\ \\Omega$","$\\mathrm{R}_2 = \\frac{6.0\\ \\text{V}}{0.25\\ \\text{A}} = 24\\ \\Omega$"]'::jsonb, '[{"element":"قراءتا الأميترين والتعليل","marks":2},{"element":"الهبوط عبر $\\mathrm{L}_2$","marks":1},{"element":"المقارنة والتعليل","marks":1},{"element":"التحقق الحسابي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل قراءة $\\mathrm{A}_3$ أقل من $\\mathrm{A}_1$ لأن المصباحين «استهلكا» التيار","افتراض أن الهبوط عبر $\\mathrm{L}_2$ يساوي 3.0 V أيضًا","الاستنتاج أن المقاومة الأكبر يمر فيها تيار أقل في دائرة التوالي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.334Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة: المصباح لا يستهلك التيار، وإنما يحوّل الطاقة الكهربائية إلى طاقة حرارية وضوئية. الشحنة لا تفنى ولا تُستحدث، ولها في دائرة التوالي مسار واحد، فالتيار نفسه في جميع أجزاء الدائرة، والمصابيح المتماثلة يتساوى سطوعها. التجربة: نصل مصباحين متماثلين على التوالي ببطارية، ونضع أميترًا قبل المصباح الأول وآخر بينهما وثالثًا بعد الثاني. النتيجة المتوقعة: تتساوى قراءات الأميترات الثلاثة، ويتساوى سطوع المصباحين.', '["الحكم بخطأ العبارة","التعليل: الشحنة لا تفنى والتيار نفسه في كل الأجزاء","التمييز بين استهلاك الطاقة واستهلاك التيار","وصف توصيل الأميترات في مواضع مختلفة","النتيجة: قراءات متساوية وسطوع متساوٍ"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بحفظ الشحنة","marks":1},{"element":"الطاقة لا التيار","marks":1},{"element":"وصف التجربة","marks":1},{"element":"النتيجة المتوقعة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن المصباح «يستهلك» شيئًا","توصيل الأميتر على التوازي مع المصباح في التجربة","توقع قراءات متناقصة للأميترات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.335Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
