from (values
('mcq', 1, 0, 'في دائرة التوازي يتصل طرفا كل مسار بطرفي المسار الآخر، فيكون فرق الجهد هو نفسه في كل مسار (الجهد متساوٍ في جميع المسارات).', '["","توزع جهد المصدر على العناصر بحسب مقاوماتها صفة دائرة التوالي.","لا أثر لموضع الفرع؛ فطرفا كل فرع متصلان بطرفي الفروع الأخرى.","فروق الجهد في الفروع لا تُجمع؛ فكلها متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.336Z"}'::jsonb),
('mcq', 2, 2, 'التيار الكلي في دائرة التوازي يساوي مجموع التيارات في الفروع: $\mathrm{I} = 0.50 + 1.2 + 0.30 = 2.0\ \text{A}$.', '["هذا تيار الفرع الأكبر فقط، والتيار الكلي يساوي مجموع تيارات الفروع جميعها.","هذا متوسط تيارات الفروع، والتيار الكلي مجموعها لا متوسطها.","","هذا تيار الفرع الأول فقط، كأن الدائرة توالٍ يمر فيها التيار نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.337Z"}'::jsonb),
('mcq', 3, 1, 'الشحنة لا تفنى ولا تُستحدث، فما يدخل نقطة التفرع من شحنة في وحدة الزمن يخرج منها موزعًا على الفرعين؛ أي أن التيار الداخل يساوي مجموع التيارين الخارجين.', '["الشحنة لا تُستهلك عند نقطة التفرع ولا في أي مكان؛ فهي لا تفنى.","","لو تساوى كل تيار خارج مع الداخل لكان مجموع الخارج ضعف الداخل، وهذا يخالف حفظ الشحنة.","الفروع لا تُنتج شحنات؛ فالشحنة لا تُستحدث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-27T21:51:39.338Z"}'::jsonb),
('mcq', 4, 3, 'طرفا المقاومة 30 Ω متصلان مباشرة بطرفي البطارية كبقية الفروع، وفرق الجهد في دائرة التوازي هو نفسه في كل فرع، فيقرأ الفولتمتر 9.0 V.', '["قسمة جهد البطارية بالتساوي على المقاومات الثلاث خطأ؛ فالجهد لا يتوزع في دائرة التوازي.","هذا ما ينتج عن معاملة المقاومات كأنها على التوالي وأخذ حصة المقاومة 30 Ω من 60 Ω.","هذا ما ينتج عن معاملتها كأنها على التوالي وأخذ حصة المقاومة 10 Ω.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.338Z"}'::jsonb),
('mcq', 5, 3, 'فرق الجهد هو نفسه بين طرفي الفرعين، و$\mathrm{R} = \frac{\mathrm{V}}{\mathrm{I}}$، فالفرع Y الذي تياره ربع تيار X تكون مقاومته أربعة أمثال مقاومة X.', '["الفرع الذي يمر فيه تيار أكبر بالجهد نفسه مقاومته أصغر لا أكبر.","فرق الجهد متساوٍ في جميع فروع دائرة التوازي، فلا يختلف بين X وY.","تساوي الجهد مع اختلاف التيار يعني اختلاف المقاومتين، لا تساويهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-27T21:51:39.339Z"}'::jsonb),
('mcq', 6, 0, 'يتصل طرفا $\mathrm{R}_\mathrm{B}$ بطرفي $\mathrm{R}_\mathrm{C}$ عند نقطتي التفرع، فهما فرعان على التوازي وفرق الجهد بين طرفيهما متساوٍ، أما $\mathrm{R}_\mathrm{A}$ ففي السلك الرئيس.', '["","$\\mathrm{R}_\\mathrm{A}$ في السلك الرئيس يمر فيها التيار الكلي، وطرفاها غير متصلين بطرفي الفرعين.","التجاور في الرسم لا يحدد نوع التوصيل؛ فطرفا $\\mathrm{R}_\\mathrm{A}$ لا يتصلان بطرفي $\\mathrm{R}_\\mathrm{B}$.","التيار يتفرع بعد $\\mathrm{R}_\\mathrm{A}$ إلى مسارين، فلا يمر التيار نفسه في $\\mathrm{R}_\\mathrm{B}$ و$\\mathrm{R}_\\mathrm{C}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.339Z"}'::jsonb),
('mcq', 7, 2, 'تكون المقاومات على التوازي عند اتصال طرفي كل مقاومة بطرفي المقاومتين الأخريين؛ فدائرة التوازي تحتوي على مسارات متعددة للتيار، حيث يتصل طرفا كل مسار بطرفي المسار الآخر.', '["شكل الرسم لا يحدد نوع التوصيل؛ المعتبر هو نقاط اتصال الأطراف.","مرور التيار نفسه في العناصر صفة التوصيل على التوالي.","","يجب أن يتصل الطرفان كلاهما بطرفي المسارات الأخرى، لا طرف واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-27T21:51:39.339Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) لها مسارات متعددة للتيار، ويتصل طرفا كل مسار بطرفي المسارات الأخرى. (b) فرق الجهد هو نفسه بين طرفي كل فرع. (c) التيار الكلي يساوي مجموع تيارات الفروع: $\mathrm{I} = \mathrm{I}_\mathrm{A} + \mathrm{I}_\mathrm{B} + \mathrm{I}_\mathrm{C}$. (d) إذا فُتح فرع فلا يمر فيه تيار، ولا تتغير قيم التيارات في الفروع الأخرى؛ لأن تيار كل فرع يعتمد فقط على فرق الجهد بين طرفيه ومقاومته.', '["مسارات متعددة متصلة الأطراف","الجهد نفسه في كل فرع","التيار الكلي مجموع تيارات الفروع","فتح فرع لا يغير تيارات الفروع الأخرى"]'::jsonb, '[]'::jsonb, '[{"element":"المسارات","marks":1},{"element":"الجهد","marks":1},{"element":"التيار الكلي","marks":1},{"element":"فتح فرع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التيار متساوٍ في جميع الفروع","القول إن جهد المصدر يتوزع على الفروع","القول إن تيارات الفروع الأخرى تزداد لتعويض الفرع المفتوح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.340Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) 12 V لكل منهما؛ لأن فرق الجهد متساوٍ في جميع فروع دائرة التوازي. (b) $\mathrm{I} = 3.0 + 2.0 + 1.0 = 6.0\ \text{A}$. (c) بما أن الجهد نفسه، فالفرع الذي يمر فيه تيار أكبر مقاومته أصغر: $\mathrm{R}_\mathrm{A} < \mathrm{R}_\mathrm{B} < \mathrm{R}_\mathrm{C}$. (d) $\mathrm{R}_\mathrm{A} = 12/3.0 = 4.0\ \Omega$، $\mathrm{R}_\mathrm{B} = 12/2.0 = 6.0\ \Omega$، $\mathrm{R}_\mathrm{C} = 12/1.0 = 12\ \Omega$.', '["الجهد 12 V في كل فرع مع التعليل","التيار الكلي 6.0 A","الترتيب مع التعليل بالتيار","حساب المقاومات 4.0 و6.0 و12 Ω"]'::jsonb, '["$\\mathrm{V}_\\mathrm{B} = \\mathrm{V}_\\mathrm{C} = \\mathrm{V}_\\mathrm{A} = 12\\ \\text{V}$","$\\mathrm{I} = \\mathrm{I}_\\mathrm{A} + \\mathrm{I}_\\mathrm{B} + \\mathrm{I}_\\mathrm{C} = 6.0\\ \\text{A}$","$\\mathrm{R} = \\frac{\\mathrm{V}}{\\mathrm{I}}$ لكل فرع: 4.0 Ω و6.0 Ω و12 Ω"]'::jsonb, '[{"element":"الجهد والتعليل","marks":1},{"element":"التيار الكلي","marks":1},{"element":"الترتيب والتعليل","marks":2},{"element":"التحقق الحسابي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تقسيم 12 V على الفروع الثلاثة","جعل قراءة الأميتر الرئيس تساوي تيار أحد الفروع","عكس الترتيب: المقاومة الأكبر يمر فيها تيار أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.340Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزءان خاطئان. أولًا: الجهد لا يتوزع على فروع التوازي؛ لأن طرفي كل فرع متصلان مباشرة بطرفي المصدر (بإهمال مقاومة الأسلاك)، فيكون فرق الجهد بين طرفي كل فرع مساويًا لجهد البطارية. توزع الجهد صفة دائرة التوالي. ثانيًا: التيار لا يكون نفسه في كل فرع، بل يعتمد على مقاومة الفرع ($\mathrm{I} = \mathrm{V}/\mathrm{R}$)، فالفرع الأقل مقاومة يمر فيه تيار أكبر، ويكون التيار الكلي مجموع تيارات الفروع. تساوي التيار صفة دائرة التوالي.', '["الحكم بخطأ الجزء الأول مع التعليل","التصحيح: الجهد نفسه ويساوي جهد المصدر","الحكم بخطأ الجزء الثاني","التصحيح: التيار يعتمد على مقاومة الفرع والكلي مجموعها","بيان أن الصفتين لدائرة التوالي"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء الأول","marks":2},{"element":"الجزء الثاني","marks":2},{"element":"الربط بدائرة التوالي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الجزء الأول لأن المصدر «يعطي» كل فرع جزءًا من جهده","تصحيح الجزء الثاني بالقول إن التيار يتوزع بالتساوي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.341Z"}'::jsonb)
