select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المقاومة المكافئة لمقاومات على التوالي مجموعها: $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \mathrm{R}_\mathrm{C} = 12 + 18 + 30 = 60\ \Omega$.', '["هذه المقاومة المكافئة لو وُصلت المقاومات على التوازي (جمع المقلوبات).","","هذا متوسط المقاومات الثلاث، والمكافئة في التوالي مجموعها.","هذه أكبر مقاومة مفردة، والمكافئة على التوالي أكبر من أي مقاومة مفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-27T21:51:39.342Z"}'::jsonb),
('mcq', 2, 3, '$\mathrm{R} = 33.0 + 47.0 = 80.0\ \Omega$، ثم $\mathrm{I} = \frac{\mathrm{V}_{\text{مصدر}}}{\mathrm{R}} = \frac{24.0\ \text{V}}{80.0\ \Omega} = 0.300\ \text{A}$.', '["قسمة جهد البطارية على $\\mathrm{R}_\\mathrm{A}$ وحدها خطأ؛ فالتيار يُحسب بالمقاومة المكافئة.","قسمة جهد البطارية على $\\mathrm{R}_\\mathrm{B}$ وحدها خطأ؛ فالتيار يُحسب بالمقاومة المكافئة.","هذا ناتج حساب المقاومة المكافئة كأن المقاومتين على التوازي (19.4 Ω).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-27T21:51:39.342Z"}'::jsonb),
('mcq', 3, 0, '$\mathrm{R} = 10.0 + 20.0 + 60.0 = 90.0\ \Omega$، $\mathrm{I} = \frac{45.0}{90.0} = 0.500\ \text{A}$، والهبوط $\mathrm{V} = \mathrm{I}\mathrm{R} = (0.500\ \text{A})(20.0\ \Omega) = 10.0\ \text{V}$.', '["","قسمة جهد البطارية بالتساوي على المقاومات الثلاث خطأ؛ فالهبوط يتناسب مع المقاومة.","هذا الهبوط عبر المقاومة 60.0 Ω لا عبر 20.0 Ω.","هذا جهد البطارية كله، والهبوط عبر مقاومة واحدة على التوالي جزء منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-27T21:51:39.342Z"}'::jsonb),
('mcq', 4, 2, 'مجموع الهبوط في الجهد عبر مقاومات التوالي يساوي جهد المصدر: $\mathrm{V}_3 = 9.00 - 2.45 - 3.10 = 3.45\ \text{V}$.', '["هذا مجموع الهبوطين المعلومين، لا الهبوط عبر المقاومة الثالثة.","جمع جهد البطارية مع الهبوطين خطأ؛ فمجموع الهبوط الثلاثة هو الذي يساوي جهد البطارية.","","قسمة جهد البطارية على ثلاثة تفترض تساوي المقاومات، وهذا غير معطى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.343Z"}'::jsonb),
('mcq', 5, 1, '$\mathrm{I} = \frac{\mathrm{V}_\mathrm{A}}{\mathrm{R}_\mathrm{A}} = \frac{6.0\ \text{V}}{120\ \Omega} = 0.050\ \text{A}$، وهو التيار نفسه في الدائرة، إذن $\mathrm{V}_{\text{مصدر}} = \mathrm{I}(\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}) = (0.050)(300) = 15\ \text{V}$.', '["هذا الهبوط عبر $\\mathrm{R}_\\mathrm{B}$ وحدها، وجهد البطارية مجموع الهبوطين.","","هذا ناتج ضرب 6.0 V في نسبة المقاومة المكافئة إلى $\\mathrm{R}_\\mathrm{B}$ بدلًا من $\\mathrm{R}_\\mathrm{A}$.","افتراض أن جهد البطارية يساوي قراءة الفولتمتر خطأ؛ فهو يقيس الهبوط عبر مقاومة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.343Z"}'::jsonb),
('mcq', 6, 0, '$\mathrm{R} = \frac{120\ \text{V}}{0.080\ \text{A}} = 1.5\times10^{3}\ \Omega$ للسلك كله، والمصابيح متماثلة على التوالي فمقاومة كل منها $\frac{1500}{20} = 75\ \Omega$.', '["","هذه المقاومة المكافئة للسلك كله، ولم تُقسم على عدد المصابيح.","ضرب المقاومة المكافئة في عدد المصابيح خطأ؛ فالمكافئة مجموع مقاومات المصابيح.","هذا ناتج قسمة التيار على جهد المصباح ($\\mathrm{I}/\\mathrm{V}$)، أي مقلوب العلاقة الصحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.343Z"}'::jsonb),
('mcq', 7, 3, 'الهبوط المطلوب عبر المقاومة $12 - 3.0 = 9.0\ \text{V}$، والتيار نفسه في دائرة التوالي 0.20 A، إذن $\mathrm{R} = \frac{9.0\ \text{V}}{0.20\ \text{A}} = 45\ \Omega$.', '["هذه المقاومة المكافئة للدائرة كلها، ويجب طرح مقاومة المصباح منها.","هذه مقاومة المصباح نفسه، لا المقاومة المضافة.","هذا ناتج جمع الجهدين (15 V) بدل طرحهما قبل القسمة على التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.344Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\mathrm{R} = 15.0 + 25.0 + 40.0 = 80.0\ \Omega$. (b) $\mathrm{I} = 24.0/80.0 = 0.300\ \text{A}$. (c) $\mathrm{V}_\mathrm{A} = (0.300)(15.0) = 4.50\ \text{V}$، $\mathrm{V}_\mathrm{B} = (0.300)(25.0) = 7.50\ \text{V}$، $\mathrm{V}_\mathrm{C} = (0.300)(40.0) = 12.0\ \text{V}$. (d) $4.50 + 7.50 + 12.0 = 24.0\ \text{V}$ وهو جهد البطارية.', '["المقاومة المكافئة 80.0 Ω","التيار 0.300 A","الهبوط 4.50 و7.50 و12.0 V","التحقق: المجموع 24.0 V"]'::jsonb, '["$\\mathrm{R} = \\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{B} + \\mathrm{R}_\\mathrm{C} = 80.0\\ \\Omega$","$\\mathrm{I} = \\frac{\\mathrm{V}_{\\text{مصدر}}}{\\mathrm{R}} = \\frac{24.0\\ \\text{V}}{80.0\\ \\Omega} = 0.300\\ \\text{A}$","$\\mathrm{V} = \\mathrm{I}\\mathrm{R}$ لكل مقاومة: 4.50 V و7.50 V و12.0 V","$4.50 + 7.50 + 12.0 = 24.0\\ \\text{V}$"]'::jsonb, '[{"element":"المقاومة المكافئة","marks":1},{"element":"التيار","marks":1},{"element":"الهبوط عبر المقاومات","marks":2},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب تيار مختلف لكل مقاومة بقسمة جهد البطارية عليها","إهمال الأرقام المعنوية (كتابة 0.3 A)","جمع مقلوبات المقاومات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-27T21:51:39.344Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{I} = 3.6/180 = 0.020\ \text{A}$. (b) $\mathrm{V}_\mathrm{B} = 9.0 - 3.6 = 5.4\ \text{V}$. (c) $\mathrm{R}_\mathrm{B} = 5.4/0.020 = 270\ \Omega$. (d) $\mathrm{R} = 180 + 270 = 450\ \Omega$، والتحقق: $9.0/0.020 = 450\ \Omega$.', '["التيار 0.020 A","الهبوط عبر $\\mathrm{R}_\\mathrm{B}$ يساوي 5.4 V","$\\mathrm{R}_\\mathrm{B}$ = 270 Ω","المكافئة 450 Ω والتحقق منها"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{V}_\\mathrm{A}}{\\mathrm{R}_\\mathrm{A}} = \\frac{3.6\\ \\text{V}}{180\\ \\Omega} = 0.020\\ \\text{A}$","$\\mathrm{V}_\\mathrm{B} = \\mathrm{V}_{\\text{مصدر}} - \\mathrm{V}_\\mathrm{A} = 5.4\\ \\text{V}$","$\\mathrm{R}_\\mathrm{B} = \\frac{5.4\\ \\text{V}}{0.020\\ \\text{A}} = 270\\ \\Omega$","$\\mathrm{R} = \\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{B} = 450\\ \\Omega = \\frac{9.0\\ \\text{V}}{0.020\\ \\text{A}}$"]'::jsonb, '[{"element":"التيار","marks":1},{"element":"الهبوط عبر $\\mathrm{R}_\\mathrm{B}$","marks":1},{"element":"قيمة $\\mathrm{R}_\\mathrm{B}$","marks":1},{"element":"المكافئة والتحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب التيار بقسمة 9.0 V على 180 Ω","اعتبار 3.6 V هبوطًا عبر $\\mathrm{R}_\\mathrm{B}$","نسيان أن التيار نفسه يمر في المقاومتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-27T21:51:39.345Z"}'::jsonb),
('essay', 3, null::int, null, null, 'حل الطالب خاطئ؛ فقد عامل المقاومتين كأنهما على التوازي وأن فرق الجهد بين طرفي كل منهما 10 V. في دائرة التوالي يمر التيار نفسه في المقاومتين، ويتوزع جهد المصدر عليهما، فنحسب المقاومة المكافئة أولًا: $\mathrm{R} = 20 + 30 = 50\ \Omega$، ثم $\mathrm{I} = 10/50 = 0.20\ \text{A}$. الهبوط: $\mathrm{V}_1 = (0.20)(20) = 4.0\ \text{V}$، $\mathrm{V}_2 = (0.20)(30) = 6.0\ \text{V}$، ومجموعهما 10 V.', '["الحكم بخطأ الحل","تحديد مصدر الخطأ: معاملة التوالي معاملة التوازي","المقاومة المكافئة 50 Ω والتيار 0.20 A","الهبوط 4.0 V و6.0 V"]'::jsonb, '["$\\mathrm{R} = 20 + 30 = 50\\ \\Omega$","$\\mathrm{I} = \\frac{10\\ \\text{V}}{50\\ \\Omega} = 0.20\\ \\text{A}$","$\\mathrm{V}_1 = 4.0\\ \\text{V}$، $\\mathrm{V}_2 = 6.0\\ \\text{V}$"]'::jsonb, '[{"element":"الحكم وتحديد الخطأ","marks":2},{"element":"التيار الصحيح","marks":2},{"element":"الهبوط عبر المقاومتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الحل لأن العمليات الحسابية صحيحة","حساب الهبوط بافتراض 10 V لكل مقاومة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.346Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
