from (values
('mcq', 1, 'وُصلت مقاومتان 30.0 Ω و60.0 Ω على التوازي. ما مقدار المقاومة المكافئة لهما؟', null, null, '["20.0 Ω","90.0 Ω","45.0 Ω","0.0500 Ω"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 49 — المقاومة المكافئة على التوازي'),
('mcq', 2, 'ما قراءة الأميتر في الدائرة الآتية؟', null, '[{"src":"qimg/phys32/c2l1-o04-three.svg","alt":"دائرة توازٍ: بطارية جهدها 18.0 V على اليسار، ثم أميتر في السلك العلوي الرئيس، ثم ثلاثة فروع رأسية على التوازي فيها مقاومات 6.0 Ω و9.0 Ω و18.0 Ω، وتلتقي الفروع في السلك السفلي العائد إلى البطارية."}]'::jsonb, '["0.55 A","1.0 A","6.0 A","3.0 A"]'::jsonb, 'تطبيق', 'حساب التيار الكلي', 'متوسط', 'الكتاب ص 50 — مثال 3'),
('mcq', 3, 'وُصلت مقاومتان 15.0 Ω و45.0 Ω على التوازي ببطارية جهدها 9.00 V. ما التيار المار في المقاومة 45.0 Ω؟', null, null, '["0.600 A","0.200 A","0.150 A","0.800 A"]'::jsonb, 'تطبيق', 'حساب تيار فرع', 'سهل', 'الكتاب ص 48 — حساب تيار كل فرع'),
('mcq', 4, 'دائرة توازٍ فيها أربعة فروع، التيارات فيها: 150 mA و0.45 A و300 mA و1.2 A. ما مقدار التيار الذي يولّده المصدر؟', null, null, '["452 mA","1.2 A","0.53 A","2.1 A"]'::jsonb, 'تطبيق', 'حساب التيار الكلي', 'متوسط', 'الكتاب ص 51 — السؤال 16'),
('mcq', 5, 'في الدائرة الآتية، الأميتر الرئيس يقرأ 1.50 A، والأميتر في فرع المقاومة $\mathrm{R}_\mathrm{A} = 20.0\ \Omega$ يقرأ 0.60 A. ما مقدار المقاومة $\mathrm{R}_\mathrm{B}$؟', null, '[{"src":"qimg/phys32/c2l1-o04-find.svg","alt":"دائرة توازٍ: بطارية على اليسار بلا قيمة، يليها في السلك العلوي أميتر رئيس مكتوب فوقه 1.50 A. يتفرع السلك إلى فرعين رأسيين: الأول فيه أميتر قراءته 0.60 A ثم مقاومة RA = 20.0 Ω، والثاني فيه مقاومة مجهولة RB. يلتقي الفرعان في السلك السفلي."}]'::jsonb, '["13.3 Ω","8.00 Ω","20.0 Ω","33.3 Ω"]'::jsonb, 'تحليل', 'حساب متعدد الخطوات', 'صعب', 'الكتاب ص 64 — السؤال 58'),
('mcq', 6, 'وُصلت أربع مقاومات متماثلة، مقاومة كل منها 48 Ω، على التوازي. ما مقدار المقاومة المكافئة لها؟', null, null, '["192 Ω","48 Ω","0.083 Ω","12 Ω"]'::jsonb, 'تطبيق', 'حساب مباشر', 'متوسط', 'الكتاب ص 67 — السؤال 83'),
('mcq', 7, 'فرع في دائرة كهربائية مقاومته 60.0 Ω، ويراد خفض مقاومته إلى 40.0 Ω بإضافة مقاومة إليه. ما المقاومة المطلوبة، وكيف توصل؟', null, null, '["20.0 Ω على التوالي مع مقاومة الفرع","20.0 Ω على التوازي مع مقاومة الفرع","120 Ω على التوازي مع مقاومة الفرع","100 Ω على التوازي مع مقاومة الفرع"]'::jsonb, 'تطبيق', 'حساب عكسي', 'صعب', 'الكتاب ص 51 — المسألة 13'),
('essay', 1, 'في الدائرة الآتية ثلاث مقاومات على التوازي ببطارية جهدها 24.0 V. احسب: (a) التيار المار في كل فرع، (b) المقاومة المكافئة للدائرة، (c) التيار المار في البطارية بطريقتين، وقارن بينهما.', null, '[{"src":"qimg/phys32/c2l1-o04-e1.svg","alt":"دائرة توازٍ: بطارية جهدها 24.0 V على اليسار ثم أميتر في السلك الرئيس العلوي. ثلاثة فروع رأسية، في كل فرع أميتر في الأعلى ثم مقاومة: الفرع الأول أميتره IA ومقاومته RA = 40.0 Ω، والثاني أميتره IB ومقاومته RB = 60.0 Ω، والثالث أميتره IC ومقاومته RC = 24.0 Ω."}]'::jsonb, null, 'تطبيق', 'مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 50 — مثال 3'),
('essay', 2, 'في الدائرة الآتية ثلاث مقاومات على التوازي، وقراءة الأميتر $\mathrm{A}_3$ تساوي 0.80 A. احسب: (a) جهد البطارية، (b) قراءتي الأميترين $\mathrm{A}_2$ و$\mathrm{A}_4$، (c) قراءة الأميتر $\mathrm{A}_1$، (d) المقاومة المكافئة، وتحقق منها بقسمة جهد البطارية على قراءة $\mathrm{A}_1$.', null, '[{"src":"qimg/phys32/c2l1-o04-e2.svg","alt":"دائرة توازٍ: بطارية جهدها V على اليسار. السلك العلوي يتفرع إلى ثلاثة فروع رأسية، في كل فرع أميتر في الأعلى ثم مقاومة: الفرع الأول أميتره A2 ومقاومته 30.0 Ω، والثاني أميتره A3 ومقاومته 15.0 Ω، والثالث أميتره A4 ومقاومته 10.0 Ω. في السلك السفلي الرئيس العائد إلى البطارية أميتر A1."}]'::jsonb, null, 'تحليل', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 64 — السؤالان 57 و58'),
('essay', 3, 'وُصلت مقاومتان 10 Ω و40 Ω على التوازي. قال أحد الطلاب إن المقاومة المكافئة لهما 25 Ω لأنها متوسطهما، وقال آخر إنها 50 Ω. قوّم الإجابتين، ثم احسب المقاومة المكافئة الصحيحة، وبيّن قاعدة عامة تتحقق بها من معقولية إجابتك.', null, null, null, 'تقويم', 'تقويم حل', 'متوسط', 'الكتاب ص 49–50 — المقاومة في دائرة التوازي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
