insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, '$\frac{1}{\mathrm{R}} = \frac{1}{30.0} + \frac{1}{60.0} = \frac{1}{20.0}$، إذن $\mathrm{R} = 20.0\ \Omega$، وهي أقل من أصغر المقاومتين.', '["","هذا مجموع المقاومتين، وهو المكافئة لو كانتا على التوالي.","هذا متوسط المقاومتين، والمكافئة على التوازي أقل من أصغر مقاومة.","هذا مقدار $\\frac{1}{\\mathrm{R}}$ (بوحدة $\\Omega^{-1}$)، ولم يُحسب مقلوبه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-27T21:51:39.347Z"}'::jsonb),
('mcq', 2, 2, 'الأميتر في السلك الرئيس يقيس التيار الكلي. $\frac{1}{\mathrm{R}} = \frac{1}{6.0} + \frac{1}{9.0} + \frac{1}{18.0} = \frac{1}{3.0}$، فـ $\mathrm{R} = 3.0\ \Omega$ و$\mathrm{I} = \frac{18.0}{3.0} = 6.0\ \text{A}$ (أو مجموع تيارات الفروع $3.0 + 2.0 + 1.0$).', '["هذا ناتج جمع المقاومات (33 Ω) كأنها على التوالي.","هذا تيار فرع المقاومة 18.0 Ω وحده.","","هذا تيار فرع المقاومة 6.0 Ω وحده، والأميتر في السلك الرئيس يقيس التيار الكلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.347Z"}'::jsonb),
('mcq', 3, 1, 'فرق الجهد بين طرفي كل فرع يساوي جهد البطارية، إذن $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}} = \frac{9.00\ \text{V}}{45.0\ \Omega} = 0.200\ \text{A}$.', '["هذا تيار المقاومة 15.0 Ω لا 45.0 Ω.","","هذا ناتج قسمة الجهد على مجموع المقاومتين كأنهما على التوالي.","هذا التيار الكلي في البطارية، لا تيار الفرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.347Z"}'::jsonb),
('mcq', 4, 3, 'نوحّد الوحدات: $0.150 + 0.45 + 0.300 + 1.2 = 2.1\ \text{A}$، والتيار الكلي في دائرة التوازي يساوي مجموع تيارات الفروع.', '["جُمعت الأعداد دون توحيد الوحدات (حُسبت 0.45 و1.2 كأنها بالمللي أمبير).","هذا أكبر تيارات الفروع فقط، والتيار الكلي مجموعها.","هذا متوسط التيارات، والتيار الكلي مجموعها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-27T21:51:39.348Z"}'::jsonb),
('mcq', 5, 0, '$\mathrm{V} = \mathrm{I}_\mathrm{A}\mathrm{R}_\mathrm{A} = (0.60)(20.0) = 12\ \text{V}$، وهو جهد كل فرع. $\mathrm{I}_\mathrm{B} = 1.50 - 0.60 = 0.90\ \text{A}$، إذن $\mathrm{R}_\mathrm{B} = \frac{12}{0.90} = 13.3\ \Omega$.', '["","هذه المقاومة المكافئة للدائرة ($\\mathrm{V}/\\mathrm{I}$ الكلي)، لا مقاومة الفرع.","استُعمل تيار الفرع $\\mathrm{R}_\\mathrm{A}$ (0.60 A) لحساب $\\mathrm{R}_\\mathrm{B}$ بدل تيار فرعها.","حُسب الجهد بضرب التيار الكلي في $\\mathrm{R}_\\mathrm{A}$ (30.0 V)، مع أن تيار $\\mathrm{R}_\\mathrm{A}$ هو 0.60 A فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.348Z"}'::jsonb),
('mcq', 6, 3, '$\frac{1}{\mathrm{R}} = 4\times\frac{1}{48} = \frac{1}{12}$، إذن $\mathrm{R} = \frac{48}{4} = 12\ \Omega$.', '["هذا مجموع المقاومات، أي المكافئة على التوالي.","هذه مقاومة واحدة، والمكافئة على التوازي أقل من أي مقاومة مفردة.","هذا مقدار $\\frac{1}{\\mathrm{R}} = \\frac{4}{48}$، ولم يُحسب مقلوبه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-27T21:51:39.349Z"}'::jsonb),
('mcq', 7, 2, 'لخفض المقاومة توصل مقاومة $\mathrm{R}_\mathrm{B}$ على التوازي مع مقاومة الفرع $\mathrm{R}_\mathrm{A} = 60.0\ \Omega$: $\frac{1}{\mathrm{R}} = \frac{1}{\mathrm{R}_\mathrm{A}} + \frac{1}{\mathrm{R}_\mathrm{B}}$، إذن $\frac{1}{\mathrm{R}_\mathrm{B}} = \frac{1}{40.0} - \frac{1}{60.0} = \frac{1}{120}$، و$\mathrm{R}_\mathrm{B} = 120\ \Omega$.', '["التوصيل على التوالي يزيد المقاومة دائمًا، فلا يمكن أن يخفضها.","طرح المقاومتين لا يصلح في التوازي؛ فالعلاقة تُجمع فيها المقلوبات.","","جمع المقاومتين 60.0 و40.0 لا يعطي المقاومة المطلوبة؛ والصحيح طرح المقلوبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-27T21:51:39.349Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\mathrm{I}_\mathrm{A} = 24.0/40.0 = 0.600\ \text{A}$، $\mathrm{I}_\mathrm{B} = 24.0/60.0 = 0.400\ \text{A}$، $\mathrm{I}_\mathrm{C} = 24.0/24.0 = 1.00\ \text{A}$. (b) $\frac{1}{\mathrm{R}} = \frac{1}{40.0} + \frac{1}{60.0} + \frac{1}{24.0} = \frac{1}{12.0}$، إذن $\mathrm{R} = 12.0\ \Omega$. (c) $\mathrm{I} = 24.0/12.0 = 2.00\ \text{A}$، و$\mathrm{I} = 0.600 + 0.400 + 1.00 = 2.00\ \text{A}$؛ النتيجتان متطابقتان.', '["تيارات الفروع 0.600 و0.400 و1.00 A","المقاومة المكافئة 12.0 Ω","التيار الكلي 2.00 A بالطريقتين"]'::jsonb, '["$\\mathrm{I}_\\mathrm{A} = \\frac{\\mathrm{V}}{\\mathrm{R}_\\mathrm{A}}$، $\\mathrm{I}_\\mathrm{B} = \\frac{\\mathrm{V}}{\\mathrm{R}_\\mathrm{B}}$، $\\mathrm{I}_\\mathrm{C} = \\frac{\\mathrm{V}}{\\mathrm{R}_\\mathrm{C}}$","$\\frac{1}{\\mathrm{R}} = \\frac{1}{\\mathrm{R}_\\mathrm{A}} + \\frac{1}{\\mathrm{R}_\\mathrm{B}} + \\frac{1}{\\mathrm{R}_\\mathrm{C}}$، إذن $\\mathrm{R} = 12.0\\ \\Omega$","$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}} = 2.00\\ \\text{A} = \\mathrm{I}_\\mathrm{A} + \\mathrm{I}_\\mathrm{B} + \\mathrm{I}_\\mathrm{C}$"]'::jsonb, '[{"element":"تيارات الفروع","marks":2},{"element":"المقاومة المكافئة","marks":1},{"element":"التيار الكلي بطريقتين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع المقاومات بدل جمع مقلوباتها","نسيان قلب الناتج بعد جمع المقلوبات","قسمة جهد البطارية على الفروع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.349Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{A}_3$ في فرع المقاومة 15.0 Ω: $\mathrm{V} = (0.80)(15.0) = 12\ \text{V}$. (b) $\mathrm{A}_2$: $12/30.0 = 0.40\ \text{A}$، $\mathrm{A}_4$: $12/10.0 = 1.2\ \text{A}$. (c) $\mathrm{A}_1 = 0.40 + 0.80 + 1.2 = 2.4\ \text{A}$. (d) $\frac{1}{\mathrm{R}} = \frac{1}{30.0} + \frac{1}{15.0} + \frac{1}{10.0} = \frac{1}{5.00}$، $\mathrm{R} = 5.0\ \Omega$، والتحقق $12/2.4 = 5.0\ \Omega$.', '["جهد البطارية 12 V","$\\mathrm{A}_2$ = 0.40 A و$\\mathrm{A}_4$ = 1.2 A","$\\mathrm{A}_1$ = 2.4 A","المكافئة 5.0 Ω والتحقق"]'::jsonb, '["$\\mathrm{V} = \\mathrm{I}_3 \\times 15.0\\ \\Omega = (0.80\\ \\text{A})(15.0\\ \\Omega) = 12\\ \\text{V}$","$\\mathrm{I}_2 = \\frac{12}{30.0} = 0.40\\ \\text{A}$، $\\mathrm{I}_4 = \\frac{12}{10.0} = 1.2\\ \\text{A}$","$\\mathrm{I}_1 = 0.40 + 0.80 + 1.2 = 2.4\\ \\text{A}$","$\\mathrm{R} = 5.0\\ \\Omega = \\frac{12\\ \\text{V}}{2.4\\ \\text{A}}$"]'::jsonb, '[{"element":"جهد البطارية","marks":1},{"element":"$\\mathrm{A}_2$ و$\\mathrm{A}_4$","marks":2},{"element":"$\\mathrm{A}_1$","marks":1},{"element":"المكافئة والتحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["افتراض أن قراءات الأميترات في الفروع متساوية","جعل $\\mathrm{A}_1$ مساويًا لقراءة $\\mathrm{A}_3$","حساب الجهد بضرب 0.80 A في مجموع المقاومات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.350Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الإجابتان خاطئتان: الأولى أخذت المتوسط ولا أساس له، والثانية جمعت المقاومتين وهذه قاعدة التوالي. الصحيح: $\frac{1}{\mathrm{R}} = \frac{1}{10} + \frac{1}{40} = \frac{5}{40}$، إذن $\mathrm{R} = 8.0\ \Omega$. القاعدة: المقاومة المكافئة لمقاومات على التوازي أقل من أصغر مقاومة فيها؛ و8.0 Ω أقل من 10 Ω، فالإجابة معقولة، بينما 25 Ω و50 Ω أكبر من 10 Ω فلا يمكن أن تكونا صحيحتين.', '["رفض إجابة المتوسط","رفض إجابة الجمع (قاعدة التوالي)","الحساب الصحيح 8.0 Ω","قاعدة: المكافئة أقل من أصغر مقاومة"]'::jsonb, '["$\\frac{1}{\\mathrm{R}} = \\frac{1}{10\\ \\Omega} + \\frac{1}{40\\ \\Omega} = \\frac{5}{40\\ \\Omega}$","$\\mathrm{R} = 8.0\\ \\Omega$"]'::jsonb, '[{"element":"تقويم الإجابتين","marks":2},{"element":"الحساب الصحيح","marks":1},{"element":"قاعدة المعقولية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الناتج 0.125 Ω بنسيان قلب المقلوب","قبول 25 Ω لأنها بين القيمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.350Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
