insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ الكميتين تكون متساوية لجميع العناصر في كل من دائرتي التوالي والتوازي على الترتيب؟', null, null, '["فرق الجهد في دائرة التوالي، والتيار في دائرة التوازي","التيار في الدائرتين كلتيهما","التيار في دائرة التوالي، وفرق الجهد في دائرة التوازي","فرق الجهد في الدائرتين كلتيهما"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 51 — السؤال 15'),
('mcq', 2, 'في أيّ نوع من الدوائر يتناسب الهبوط في الجهد عبر كل مقاومة طرديًّا مع مقدار تلك المقاومة؟', null, null, '["دائرة التوالي؛ لأن التيار نفسه يمر في جميع المقاومات","دائرة التوازي؛ لأن التيار يتوزع على المقاومات بحسب قيمها","الدائرتين كلتيهما؛ لأن العلاقة $\\mathrm{V} = \\mathrm{I}\\mathrm{R}$ تنطبق على كل مقاومة","دائرة التوازي؛ لأن فرق الجهد يتوزع على الفروع"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 63 — السؤال 46 (d)'),
('mcq', 3, 'في أيّ نوع من الدوائر تكون المقاومة المكافئة أقل من أصغر مقاومة مفردة فيها؟', null, null, '["دائرة التوالي؛ لأن التيار يتوزع على المقاومات","دائرة التوالي؛ لأن المقاومات تُجمع","الدائرتين كلتيهما؛ لأن المكافئة تمثل متوسط المقاومات","دائرة التوازي؛ لأن كل مقاومة تضيف مسارًا للتيار"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 43 و49 — المقاومة المكافئة في التوالي والتوازي'),
('mcq', 4, 'في الدائرتين X وY الآتيتين، ما فرق الجهد بين طرفي إحدى المقاومتين في كل دائرة؟', null, '[{"src":"qimg/phys32/c2l1-o05-pair.svg","alt":"دائرتان متجاورتان. الدائرة X: بطارية جهدها 6.0 V ومقاومتان مقدار كل منهما 10 Ω متتاليتان في السلك العلوي على التوالي. الدائرة Y: بطارية جهدها 6.0 V ومقاومتان مقدار كل منهما 10 Ω في فرعين رأسيين على التوازي بين السلكين العلوي والسفلي."}]'::jsonb, '["6.0 V في X، و3.0 V في Y","3.0 V في X، و6.0 V في Y","3.0 V في الدائرتين","6.0 V في الدائرتين"]'::jsonb, 'فهم', 'مقارنة كمية', 'متوسط', 'الكتاب ص 43 و48 — الجهد في دائرتي التوالي والتوازي'),
('mcq', 5, 'في الدائرتين X وY الآتيتين، كيف يقارن التيار الخارج من البطارية في Y بالتيار الخارج من البطارية في X؟', null, '[{"src":"qimg/phys32/c2l1-o05-pair.svg","alt":"دائرتان متجاورتان. الدائرة X: بطارية جهدها 6.0 V ومقاومتان مقدار كل منهما 10 Ω متتاليتان في السلك العلوي على التوالي. الدائرة Y: بطارية جهدها 6.0 V ومقاومتان مقدار كل منهما 10 Ω في فرعين رأسيين على التوازي بين السلكين العلوي والسفلي."}]'::jsonb, '["التيار متساوٍ في الدائرتين","التيار في Y مثلا التيار في X","التيار في Y أربعة أمثاله في X","التيار في X أربعة أمثاله في Y"]'::jsonb, 'تحليل', 'مقارنة كمية', 'صعب', 'الكتاب ص 43 و49 — المقاومة المكافئة والتيار'),
('mcq', 6, 'دائرة كهربائية إذا أصبح التيار في إحدى مقاوماتها صفرًا لا يمر تيار في جميع مقاوماتها الأخرى. ما نوع هذه الدائرة؟', null, null, '["دائرة توازٍ؛ لأن الفروع جميعها متصلة بالمصدر نفسه","دائرة توالٍ؛ لأن فرق الجهد متساوٍ في جميع أجزائها","دائرة توازٍ؛ لأن التيار الكلي يساوي مجموع تيارات الفروع","دائرة توالٍ؛ لأن للتيار فيها مسارًا واحدًا"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 63 — السؤال 46 (g)'),
('mcq', 7, 'أيّ المقارنات الآتية بين دائرتي التوالي والتوازي صحيحة؟', null, null, '["عدد مسارات التيار: واحد في التوالي، ومتعدد في التوازي","المقاومة المكافئة: $\\mathrm{R} = \\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{B}$ في التوازي، وجمع المقلوبات في التوالي","التيار: الكلي يساوي مجموع التيارات في التوالي، وهو نفسه في كل فرع في التوازي","فرق الجهد: هو نفسه لكل عنصر في التوالي، ويتوزع على الفروع في التوازي"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 61–62 — المفاهيم الرئيسة وخريطة المفاهيم (السؤال 29)'),
('essay', 1, 'قارن بين دائرتي التوالي والتوازي الكهربائيتين من حيث: (a) عدد مسارات التيار، (b) التيار، (c) فرق الجهد، (d) المقاومة المكافئة ومعادلتها، (e) أثر انقطاع أحد العناصر في بقية الدائرة.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 51 و61 — السؤال 15 والمفاهيم الرئيسة'),
('essay', 2, 'المقاومتان 20 Ω و30 Ω موصولتان ببطارية جهدها 12 V مرة على التوالي (a) ومرة على التوازي (b) كما في الشكل الآتي. احسب لكل دائرة: المقاومة المكافئة، والتيار الخارج من البطارية، وفرق الجهد بين طرفي كل مقاومة، والتيار المار في كل منهما. ثم اكتب استنتاجين من المقارنة.', null, '[{"src":"qimg/phys32/c2l1-o05-e2.svg","alt":"دائرتان. (a): بطارية جهدها 12 V ومقاومتان 20 Ω و30 Ω متتاليتان في السلك العلوي على التوالي. (b): بطارية جهدها 12 V ومقاومتان 20 Ω و30 Ω في فرعين رأسيين على التوازي."}]'::jsonb, null, 'تحليل', 'مقارنة كمية', 'صعب', 'الكتاب ص 45–50 — مثالا 1 و3'),
('essay', 3, 'صنّف كل عبارة مما يأتي إلى «توالٍ» أو «توازٍ»، مع تعليل مختصر لكل منها: (a) التيار متساوٍ في جميع أجزاء الدائرة. (b) الهبوط في الجهد عبر كل مقاومة متساوٍ. (c) المقاومة المكافئة تساوي مجموع المقاومات المفردة. (d) إذا انعدم التيار في إحدى المقاومات لم تتغير التيارات في المقاومات الأخرى. (e) هذا النوع من التوصيل مناسب لتمديدات الأسلاك في المنزل.', null, null, null, 'تحليل', 'تصنيف', 'متوسط', 'الكتاب ص 63 — السؤال 46')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
