from (values
('mcq', 1, 2, 'في دائرة التوالي مسار واحد فيمر التيار نفسه في جميع العناصر، وفي دائرة التوازي يتصل طرفا كل فرع بطرفي المصدر فيكون فرق الجهد نفسه بين طرفي كل فرع.', '["هذا عكس الصحيح؛ ففي التوالي يتوزع الجهد، وفي التوازي يتوزع التيار.","التيار في دائرة التوازي يتوزع على الفروع بحسب مقاوماتها فلا يتساوى بالضرورة.","","فرق الجهد في دائرة التوالي يتوزع على العناصر بحسب مقاوماتها فلا يتساوى بالضرورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.351Z"}'::jsonb),
('mcq', 2, 0, 'في دائرة التوالي $\mathrm{V} = \mathrm{I}\mathrm{R}$ والتيار $\mathrm{I}$ نفسه لجميع المقاومات، فيكون الهبوط أكبر عبر المقاومة الأكبر بالنسبة نفسها. أما في التوازي فالجهد نفسه لكل الفروع.', '["","في التوازي فرق الجهد نفسه لجميع الفروع مهما اختلفت مقاوماتها.","العلاقة تنطبق على كل مقاومة، لكن التناسب مع $\\mathrm{R}$ يتطلب ثبات $\\mathrm{I}$، وهذا يتحقق في التوالي فقط.","فرق الجهد لا يتوزع على فروع التوازي؛ فهو نفسه في كل فرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.352Z"}'::jsonb),
('mcq', 3, 3, 'في دائرة التوازي كل مقاومة تضيف مسارًا للتيار، وتُجمع مقلوبات المقاومات، فيكون مقلوب المكافئة أكبر من مقلوب أي مقاومة، أي أن المكافئة أقل من أصغر مقاومة؛ بخلاف التوالي حيث المكافئة أكبر من أي مقاومة مفردة.', '["التيار لا يتوزع في التوالي، والمكافئة فيها أكبر من أي مقاومة مفردة.","جمع المقاومات يعطي قيمة أكبر من كل منها لا أصغر.","المكافئة ليست متوسطًا في أيٍّ من الدائرتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.352Z"}'::jsonb),
('mcq', 4, 1, 'في X تتقاسم المقاومتان المتماثلتان جهد البطارية: $6.0/2 = 3.0\ \text{V}$ لكل منهما. في Y طرفا كل مقاومة متصلان بطرفي البطارية: 6.0 V لكل منهما.', '["هذا عكس الصحيح؛ فالجهد يتوزع في التوالي (X) لا في التوازي (Y).","","في Y المقاومتان على التوازي فلكل منهما جهد البطارية كاملًا.","في X المقاومتان على التوالي فيتقاسمان جهد البطارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.352Z"}'::jsonb),
('mcq', 5, 2, 'في X: $\mathrm{R} = 20\ \Omega$ و$\mathrm{I} = 6.0/20 = 0.30\ \text{A}$. في Y: $\mathrm{R} = 5.0\ \Omega$ و$\mathrm{I} = 6.0/5.0 = 1.2\ \text{A}$، أي أربعة أمثال.', '["المقاومة المكافئة مختلفة في الدائرتين (20 Ω و5.0 Ω) فلا يتساوى التيار.","هذا يراعي تغير عدد المسارات فقط؛ والصحيح أن المكافئة تصغر من 20 Ω إلى 5.0 Ω أي إلى الربع.","","هذا عكس الصحيح؛ فالمقاومة المكافئة في X أكبر، فتيارها أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.353Z"}'::jsonb),
('mcq', 6, 3, 'في دائرة التوالي مسار واحد للتيار، فإذا انقطع التيار في أي مقاومة توقف في الدائرة كلها؛ أما في التوازي فلا تتأثر الفروع الأخرى.', '["اتصال الفروع بالمصدر يجعل كلًّا منها مستقلًّا، فانقطاع أحدها لا يوقف غيره.","النوع صحيح لكن التعليل خاطئ؛ ففرق الجهد لا يتساوى في أجزاء دائرة التوالي.","في التوازي إذا انعدم تيار فرع بقيت تيارات الفروع الأخرى كما هي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-27T21:51:39.353Z"}'::jsonb),
('mcq', 7, 0, 'دائرة التوالي لها مسار واحد للتيار، ودائرة التوازي تحتوي على مسارات متعددة للتيار؛ وبقية المقارنات بُدّل فيها وصفا الدائرتين.', '["","المعادلتان مبدّلتان: الجمع المباشر للتوالي، وجمع المقلوبات للتوازي.","الوصفان مبدّلان: التيار نفسه في التوالي، والكلي مجموع تيارات الفروع في التوازي.","الوصفان مبدّلان: الجهد يتوزع في التوالي، وهو نفسه لكل فرع في التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.353Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) التوالي: مسار واحد؛ التوازي: مسارات متعددة. (b) التوالي: التيار نفسه في جميع الأجزاء؛ التوازي: التيار الكلي مجموع تيارات الفروع، وتيار كل فرع يعتمد على مقاومته. (c) التوالي: مجموع الهبوط في الجهد يساوي جهد المصدر؛ التوازي: فرق الجهد نفسه لكل فرع. (d) التوالي: $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \ldots$ وهي أكبر من أي مقاومة مفردة؛ التوازي: $\frac{1}{\mathrm{R}} = \frac{1}{\mathrm{R}_\mathrm{A}} + \frac{1}{\mathrm{R}_\mathrm{B}} + \ldots$ وهي أقل من أصغر مقاومة. (e) التوالي: يتوقف التيار في الدائرة كلها؛ التوازي: يتوقف تيار ذلك الفرع فقط.', '["المسارات","التيار","فرق الجهد","المقاومة المكافئة ومعادلتاها","أثر الانقطاع"]'::jsonb, '[]'::jsonb, '[{"element":"المسارات","marks":1},{"element":"التيار","marks":1},{"element":"فرق الجهد","marks":1},{"element":"المقاومة المكافئة","marks":1},{"element":"أثر الانقطاع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل صفتي التيار والجهد بين الدائرتين","تبديل معادلتي المقاومة المكافئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.354Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) التوالي: $\mathrm{R} = 50\ \Omega$، $\mathrm{I} = 12/50 = 0.24\ \text{A}$ في المقاومتين، $\mathrm{V}_{20} = 4.8\ \text{V}$، $\mathrm{V}_{30} = 7.2\ \text{V}$. (b) التوازي: $\frac{1}{\mathrm{R}} = \frac{1}{20} + \frac{1}{30}$، إذن $\mathrm{R} = 12\ \Omega$، الجهد 12 V لكل منهما، $\mathrm{I}_{20} = 0.60\ \text{A}$، $\mathrm{I}_{30} = 0.40\ \text{A}$، والكلي $1.0\ \text{A}$. الاستنتاجات: المكافئة في التوالي أكبر من كل مقاومة وفي التوازي أصغر من كل مقاومة؛ تيار البطارية في التوازي أكبر؛ في التوالي يتوزع الجهد ويتساوى التيار، وفي التوازي يتساوى الجهد ويتوزع التيار.', '["حسابات دائرة التوالي","حسابات دائرة التوازي","استنتاجان صحيحان من المقارنة"]'::jsonb, '["التوالي: $\\mathrm{R} = 20 + 30 = 50\\ \\Omega$، $\\mathrm{I} = 0.24\\ \\text{A}$، $\\mathrm{V} = \\mathrm{I}\\mathrm{R}$: 4.8 V و7.2 V","التوازي: $\\mathrm{R} = 12\\ \\Omega$، $\\mathrm{I}_{20} = \\frac{12}{20} = 0.60\\ \\text{A}$، $\\mathrm{I}_{30} = \\frac{12}{30} = 0.40\\ \\text{A}$، $\\mathrm{I} = 1.0\\ \\text{A}$"]'::jsonb, '[{"element":"دائرة التوالي","marks":2},{"element":"دائرة التوازي","marks":2},{"element":"الاستنتاجان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"4–5 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–3 درجات","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال 12 V لكل مقاومة في دائرة التوالي","تقسيم 12 V على مقاومتي التوازي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.354Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) توالٍ: للتيار مسار واحد والشحنة لا تفنى. (b) توازٍ: طرفا كل فرع متصلان بطرفي المصدر. (c) توالٍ: $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \ldots$ (d) توازٍ: فروع التوازي لا يعتمد بعضها على بعض. (e) توازٍ: يعمل كل جهاز بجهد المصدر ويُشغَّل مستقلًّا عن غيره.', '["(a) توالٍ مع التعليل","(b) توازٍ مع التعليل","(c) توالٍ مع التعليل","(d) توازٍ مع التعليل","(e) توازٍ مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1},{"element":"(e)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–2 درجة","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (b) توالٍ لأن «الهبوط» يُذكر عادة مع التوالي","تصنيف (d) توالٍ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.355Z"}'::jsonb)
