('mcq', 5, 'كيف تقارن المقاومة المكافئة لمجموعة مقاومات موصولة على التوالي بالمقاومات المفردة فيها؟', null, null, '["أصغر من أصغر مقاومة مفردة","أكبر من أي مقاومة مفردة","تساوي متوسط المقاومات المفردة","تساوي أكبر مقاومة مفردة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 43 — المقاومة المكافئة أكبر من أي مقاومة مفردة'),
('mcq', 6, 'في الشكل الآتي دائرتان (1) و(2) لهما البطارية نفسها، والأميتر فيهما يقرأ 1.0 A. ما مقدار المقاومة $\mathrm{R}$ في الدائرة (2) لتكون مقاومة مكافئة لمقاومتي الدائرة (1)؟', null, '[{"src":"qimg/phys32/c2l1-o06-eq.svg","alt":"دائرتان. (1): بطارية جهدها 12 V، وأميتر مكتوب فوقه 1.0 A، ومقاومة RA = 4.0 Ω في السلك العلوي، ومقاومة RB = 8.0 Ω في الضلع الأيمن، على التوالي. (2): بطارية جهدها 12 V، وأميتر مكتوب فوقه 1.0 A، ومقاومة واحدة R في الضلع الأيمن."}]'::jsonb, '["2.7 Ω","6.0 Ω","12 Ω","8.0 Ω"]'::jsonb, 'فهم', 'تطبيق تعريف', 'صعب', 'الكتاب ص 43 — تعريف المقاومة المكافئة'),
('mcq', 7, 'أكمل العبارة: «مقلوب المقاومة المكافئة لمجموعة مقاومات موصولة على التوازي يساوي ...»', null, null, '["مجموع المقاومات المفردة","مقلوب مجموع المقاومات المفردة","حاصل ضرب المقاومات المفردة","مجموع مقلوبات المقاومات المفردة"]'::jsonb, 'تذكر', 'استرجاع علاقة', 'متوسط', 'الكتاب ص 49 — المقاومة المكافئة على التوازي'),
('essay', 1, 'عرّف كلًّا من: (a) المقاومة المكافئة، (b) مجزّئ الجهد. ثم اكتب معادلة المقاومة المكافئة لمقاومات موصولة على التوالي، ومعادلتها لمقاومات موصولة على التوازي.', null, null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 43–44 و49 و61 — المفردات'),
('essay', 2, 'يحتاج طالب إلى تشغيل جهاز صغير بفرق جهد أقل من جهد بطارية لديه. (a) ما اسم الدائرة التي يستخدمها؟ وما تعريفها؟ (b) صف مكوناتها وطريقة توصيلها، ومن أين يؤخذ الجهد الناتج. (c) هل يمكن أن يكون الجهد الناتج أكبر من جهد البطارية؟ علّل.', null, null, null, 'فهم', 'شرح مفهوم', 'متوسط', 'الكتاب ص 44 و61 — مجزّئ الجهد والشكل 2-4'),
('essay', 3, 'قال طالب: «المقاومة المكافئة مقاومة حقيقية إضافية توجد داخل الدائرة إلى جانب المقاومات الأخرى». حلّل هذه العبارة، ثم وضّح المعنى الصحيح للمقاومة المكافئة بمثال عددي: ثلاث مقاومات 10 Ω و20 Ω و30 Ω على التوالي ببطارية جهدها 12 V، مقارنة بمقاومة مفردة 60 Ω بالبطارية نفسها.', null, null, null, 'تحليل', 'تحليل ادعاء', 'صعب', 'الكتاب ص 43 — المقاومة المكافئة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
