from (values
('mcq', 1, 1, 'المقاومة المكافئة هي مقاومة واحدة $\mathrm{R}$ يمر فيها التيار نفسه الذي يمر في مجموعة المقاومات عند وصلها بالجهد نفسه، فتحل محل المجموعة دون أن يتغير التيار.', '["مجموع المقلوبات يساوي مقلوب المكافئة في التوازي فقط، وليس هو المكافئة نفسها.","","المكافئة لا تساوي أكبر مقاومة؛ فهي في التوالي أكبر منها وفي التوازي أصغر من أصغرها.","مقاومة أسلاك التوصيل تُهمل عادة، ولا علاقة لها بتعريف المكافئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.355Z"}'::jsonb),
('mcq', 2, 2, 'مجزّئ الجهد دائرة توالٍ تُستخدم لإنتاج مصدر جهد بالقيمة المطلوبة من بطارية ذات جهد كبير، ويؤخذ الجهد الناتج من طرفي إحدى المقاومتين.', '["مجزّئ الجهد دائرة توالٍ لا توازٍ، وغرضه الحصول على جهد لا توزيع التيار.","هذا وصف الفولتمتر، لا مجزّئ الجهد.","","مجزّئ الجهد يعطي جهدًا أصغر من جهد البطارية، ولا يمكن أن يرفعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.356Z"}'::jsonb),
('mcq', 3, 3, 'دائرة التوالي التي تُنتج من بطارية ذات جهد كبير جهدًا بالقيمة المطلوبة تسمى مجزّئ الجهد.', '["المقاومة المكافئة مقاومة مفردة تكافئ مجموعة مقاومات، لا دائرة لإنتاج جهد.","المقاومتان موصولتان على التوالي لا على التوازي.","قاطع الدائرة مفتاح آلي يفتح الدائرة عند زيادة التيار، ولا علاقة له بإنتاج الجهد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-27T21:51:39.356Z"}'::jsonb),
('mcq', 4, 0, 'في مجزّئ الجهد يؤخذ الجهد الناتج من طرفي إحدى المقاومتين؛ والفولتمتر هنا بين طرفي $\mathrm{R}_\mathrm{B}$، فهو يقيس الهبوط $\mathrm{V}_\mathrm{B} = \mathrm{I}\mathrm{R}_\mathrm{B}$.', '["","الفولتمتر ليس موصولًا بين طرفي البطارية، بل بين طرفي $\\mathrm{R}_\\mathrm{B}$ فقط.","الفولتمتر موصول بين طرفي $\\mathrm{R}_\\mathrm{B}$ لا $\\mathrm{R}_\\mathrm{A}$.","الجهد الناتج يتوقف على قيمتي المقاومتين، ولا يساوي النصف إلا إذا تساوتا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.356Z"}'::jsonb),
('mcq', 5, 1, '$\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \ldots$، فالمجموع أكبر من أي حد فيه؛ أي أن المقاومة المكافئة في التوصيل على التوالي أكبر من أي مقاومة مفردة.', '["هذا وصف المقاومة المكافئة لمقاومات على التوازي.","","المكافئة على التوالي مجموع المقاومات لا متوسطها.","المكافئة تساوي المجموع، فهي أكبر من أكبر مقاومة لا مساوية لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.356Z"}'::jsonb),
('mcq', 6, 2, 'المقاومة المكافئة يمر فيها التيار نفسه عند الجهد نفسه: $\mathrm{R} = \frac{12\ \text{V}}{1.0\ \text{A}} = 12\ \Omega$، وهي تساوي $\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} = 4.0 + 8.0$.', '["هذه المكافئة لو كانت المقاومتان على التوازي، وهما في الدائرة (1) على التوالي.","هذا متوسط المقاومتين، والمكافئة على التوالي مجموعهما.","","هذه أكبر المقاومتين فقط، ولو وُضعت لمر تيار 1.5 A لا 1.0 A."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.357Z"}'::jsonb),
('mcq', 7, 3, '$\frac{1}{\mathrm{R}} = \frac{1}{\mathrm{R}_\mathrm{A}} + \frac{1}{\mathrm{R}_\mathrm{B}} + \frac{1}{\mathrm{R}_\mathrm{C}} + \ldots$؛ أي أن مقلوب المقاومة المكافئة يساوي مجموع مقلوبات المقاومات المفردة.', '["مجموع المقاومات يساوي المكافئة في التوالي لا مقلوبها في التوازي.","مقلوب المجموع يختلف عن مجموع المقلوبات؛ ولا يعطي المكافئة على التوازي.","حاصل الضرب لا يرد في معادلة المكافئة على التوازي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.357Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المقاومة المكافئة: مقاومة مفردة $\mathrm{R}$ يمر فيها التيار نفسه الذي يمر في مجموعة المقاومات عند الجهد نفسه، فتكافئ المجموعة. (b) مجزّئ الجهد: دائرة توالٍ تُستخدم لإنتاج مصدر جهد بالقيمة المطلوبة من بطارية ذات جهد كبير. التوالي: $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \ldots$ التوازي: $\frac{1}{\mathrm{R}} = \frac{1}{\mathrm{R}_\mathrm{A}} + \frac{1}{\mathrm{R}_\mathrm{B}} + \ldots$', '["تعريف المقاومة المكافئة","تعريف مجزّئ الجهد","معادلة التوالي","معادلة التوازي"]'::jsonb, '[]'::jsonb, '[{"element":"المقاومة المكافئة","marks":1},{"element":"مجزّئ الجهد","marks":1},{"element":"معادلة التوالي","marks":1},{"element":"معادلة التوازي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف مجزّئ الجهد بأنه دائرة توازٍ","تبديل معادلتي التوالي والتوازي","تعريف المكافئة بأنها مجموع المقاومات دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.358Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) مجزّئ الجهد: دائرة توالٍ تُستخدم لإنتاج مصدر جهد بالقيمة المطلوبة من بطارية ذات جهد كبير. (b) تتكون من البطارية ومقاومتين $\mathrm{R}_\mathrm{A}$ و$\mathrm{R}_\mathrm{B}$ موصولتين على التوالي بين قطبيها، ويؤخذ الجهد الناتج من طرفي إحدى المقاومتين (مثل $\mathrm{R}_\mathrm{B}$)، ويساوي الهبوط في الجهد عبرها. (c) لا؛ لأن مجموع الهبوط في الجهد عبر المقاومتين يساوي جهد البطارية، فالهبوط عبر إحداهما جزء منه لا يتجاوزه.', '["الاسم والتعريف","مقاومتان على التوالي بين قطبي البطارية","أخذ الجهد من طرفي إحدى المقاومتين","الجهد الناتج أقل من جهد البطارية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم والتعريف","marks":1},{"element":"المكونات والتوصيل","marks":1},{"element":"موضع أخذ الجهد","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توصيل المقاومتين على التوازي","أخذ الجهد من طرفي البطارية","الظن أن مجزّئ الجهد يرفع الجهد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-27T21:51:39.358Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة؛ فالمقاومة المكافئة ليست عنصرًا إضافيًّا في الدائرة، بل هي قيمة مقاومة مفردة لو وُضعت بدل المجموعة كلها لمر في الدائرة التيار نفسه. المثال: المقاومات الثلاث على التوالي مكافئتها $\mathrm{R} = 10 + 20 + 30 = 60\ \Omega$، والتيار $\mathrm{I} = 12/60 = 0.20\ \text{A}$. المقاومة المفردة 60 Ω بالبطارية نفسها يمر فيها $12/60 = 0.20\ \text{A}$ أيضًا؛ فهي تكافئ المجموعة من حيث التيار المسحوب من البطارية، ولا تضاف إليها.', '["الحكم بخطأ العبارة","المعنى الصحيح: مقاومة مفردة تحل محل المجموعة","حساب المكافئة 60 Ω والتيار 0.20 A","بيان تساوي التيار في الحالتين"]'::jsonb, '["$\\mathrm{R} = 10 + 20 + 30 = 60\\ \\Omega$","$\\mathrm{I} = \\frac{12\\ \\text{V}}{60\\ \\Omega} = 0.20\\ \\text{A}$ في الحالتين"]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المعنى الصحيح","marks":1},{"element":"الحساب","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة 60 Ω إلى المقاومات الثلاث وحساب التيار بمقاومة 120 Ω","الظن أن المكافئة تُحسب فقط للتوالي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-27T21:51:39.359Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
