select (select id from public.objectives where code = 'P32-C2-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ مما يأتي يمثل غرضين من أغراض توصيل المقاومات على التوالي؟', null, null, '["زيادة المقاومة المكافئة لتقليل التيار، وتجزئة جهد المصدر","تقليل المقاومة المكافئة، وجعل كل جهاز يعمل مستقلًّا عن غيره","زيادة المقاومة المكافئة، وجعل جهد كل جهاز مساويًا لجهد المصدر","تجزئة جهد المصدر، وزيادة التيار المار في الأجهزة"]'::jsonb, 'تذكر', 'ذكر غرض', 'سهل', 'الكتاب ص 43–44 — المقاومة المكافئة على التوالي ومجزّئ الجهد'),
('mcq', 2, 'وصل طالب مقاومتين على التوالي بين قطبي بطارية جهدها 12 V، ثم أخذ الجهد من طرفي إحدى المقاومتين لتشغيل جهاز. ما الغرض من ذلك؟', null, null, '["الحصول على فرق جهد أكبر من جهد البطارية لتشغيل جهاز يحتاج إلى جهد كبير","الحصول على فرق جهد أصغر بالقيمة المطلوبة من بطارية ذات جهد أكبر","مضاعفة التيار المار في الجهاز ليعمل بقدرة أكبر","حماية الدائرة من التيارات الكبيرة بقطع التيار"]'::jsonb, 'تذكر', 'ذكر غرض', 'سهل', 'الكتاب ص 44 — مجزّئ الجهد تطبيق على دوائر التوالي'),
('mcq', 3, 'لديك بطارية جهدها 6 V وعدد من المصابيح المتماثلة، كل منها يعمل بفرق جهد 1.5 V. كيف توصل المصابيح لتضيء دون أن يزيد فرق الجهد بين طرفي أي منها على 1.5 V؟', null, null, '["أربعة مصابيح على التوازي","مصباحان على التوالي","أربعة مصابيح على التوالي","مصباح واحد يوصل مباشرة بالبطارية"]'::jsonb, 'فهم', 'تطبيق غرض', 'متوسط', 'الكتاب ص 62 — السؤال 44'),
('mcq', 4, 'لماذا يوصل المنصهر الكهربائي على التوالي بمصدر الجهد في دائرة كهربائية؟', null, null, '["ليكون فرق الجهد بين طرفيه مساويًا لجهد المصدر","ليقلل المقاومة المكافئة للدائرة فيزداد التيار","ليمر فيه تيار فرع واحد فقط من فروع الدائرة","ليمر فيه التيار الكلي فينصهر إذا زاد على الحد المسموح"]'::jsonb, 'تذكر', 'ذكر غرض', 'متوسط', 'الكتاب ص 53 — توصيل المنصهر على التوالي'),
('mcq', 5, 'في الدائرة الآتية مصباح صُمّم ليعمل بفرق جهد 6.0 V، ووُصل معه على التوالي مقاومة $\mathrm{R}$ ببطارية جهدها 9.0 V. ما الغرض من المقاومة $\mathrm{R}$؟', null, '[{"src":"qimg/phys32/c2l1-o07-lamp.svg","alt":"دائرة توالٍ: بطارية جهدها 9.0 V على اليسار، ومقاومة R في السلك العلوي، ومصباح في الضلع الأيمن مكتوب بجانبه «مصباح» و6.0 V، ثم يعود السلك السفلي إلى البطارية."}]'::jsonb, '["ترفع فرق الجهد بين طرفي المصباح إلى 9.0 V ليزداد سطوعه إلى أقصى حد","تأخذ جزءًا من جهد البطارية فيبقى بين طرفي المصباح الجهد المناسب لعمله","تجعل التيار المار فيها أكبر من التيار المار في المصباح","توفر مسارًا آخر للتيار إذا احترق فتيل المصباح"]'::jsonb, 'فهم', 'تفسير غرض', 'متوسط', 'الكتاب ص 43–44 — الهبوط في الجهد ومجزّئ الجهد'),
('mcq', 6, 'سلك زينة فيه عدد كبير من المصابيح الصغيرة يوصل بجهد الخط. لماذا توصل مصابيحه غالبًا على التوالي؟', null, null, '["ليعمل كل مصباح بجهد الخط كاملًا","ليبقى باقي المصابيح مضيئًا إذا احترق أحدها","ليزداد التيار المار في كل مصباح فيشتد سطوعه","ليتقاسم المصابيح جهد الخط فيعمل كل مصباح بجهد صغير"]'::jsonb, 'تذكر', 'ذكر غرض', 'سهل', 'الكتاب ص 43–44 و47 و64 — الهبوط في الجهد والمسائل 3 و7 و61'),
('mcq', 7, 'يُراد خفض التيار الذي تزوّده البطارية في دائرة فيها مصباح. أيّ الترتيبات الثلاثة الآتية يحقق ذلك (البطارية نفسها في الترتيبات جميعها)؟', null, '[{"src":"qimg/phys32/c2l1-o07-choose.svg","alt":"ثلاثة ترتيبات مرقمة، في كل منها البطارية نفسها على اليسار. (1): مصباح وحده في الضلع الأيمن. (2): مقاومة R في السلك العلوي ومصباح في الضلع الأيمن على التوالي. (3): مصباح ومقاومة R في فرعين رأسيين على التوازي."}]'::jsonb, '["الترتيب (2)؛ لأن المقاومة المكافئة فيه أكبر","الترتيب (3)؛ لأن التيار يتوزع فيه بين فرعين","الترتيب (1)؛ لأن المصباح وحده يأخذ التيار كله","الترتيبات الثلاثة بالقدر نفسه؛ لأن البطارية واحدة"]'::jsonb, 'تحليل', 'اختيار تصميم', 'صعب', 'الكتاب ص 43 و49 — المقاومة المكافئة على التوالي والتوازي'),
('essay', 1, 'اذكر ثلاثة أغراض لتوصيل المقاومات أو الأجهزة على التوالي، ووضّح كيف يحقق التوصيل على التوالي كل غرض منها.', null, null, null, 'تذكر', 'ذكر أغراض', 'سهل', 'الكتاب ص 43–45 و53 — تطبيقات التوصيل على التوالي'),
('essay', 2, 'وضّح كيف يمكن الحصول على جهد مقداره 4.0 V من بطارية جهدها 12 V باستعمال مقاومتين، مبيّنًا: (a) طريقة توصيل المقاومتين ولماذا، (b) من أين يؤخذ الجهد المطلوب، (c) أيّ المقاومتين يجب أن تكون أكبر، ولماذا.', null, null, null, 'فهم', 'تفسير تطبيق', 'متوسط', 'الكتاب ص 44 — مجزّئ الجهد والشكل 2-4'),
('essay', 3, 'توصل مصابيح أسلاك الزينة غالبًا على التوالي. (a) لماذا تُستخدم مصابيح خاصة تشكّل دائرة قصر عندما يحترق فتيلها؟ (b) ماذا يحدث للتيار في السلك كلما احترق مصباح من هذا النوع؟ (c) لماذا يحترق منصهر مجموعة المصابيح بعد احتراق عدد منها؟', null, null, null, 'تحليل', 'تحليل تطبيق', 'صعب', 'الكتاب ص 47 — المسألة 7')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'في التوصيل على التوالي تكون المقاومة المكافئة مجموع المقاومات $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B} + \ldots$ فهي أكبر من أي مقاومة مفردة، فيقل التيار $\mathrm{I} = \frac{\mathrm{V}_{\text{مصدر}}}{\mathrm{R}}$ عند ثبات جهد المصدر؛ ومجموع الهبوط في الجهد عبر المقاومات يساوي جهد المصدر فيتجزأ الجهد عليها، وهذا أساس مجزّئ الجهد.', '["","هذان غرضا التوصيل على التوازي؛ فالتوازي يقلل المقاومة المكافئة، وفروعه لا يعتمد بعضها على بعض.","الشق الأول صحيح، لكن تساوي جهد كل جهاز مع جهد المصدر صفة التوازي؛ أما في التوالي فيتوزع جهد المصدر على الأجهزة.","الشق الأول صحيح، لكن التوصيل على التوالي يزيد المقاومة المكافئة فيقل التيار ولا يزداد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.360Z"}'::jsonb),
('mcq', 2, 1, 'هذه دائرة مجزّئ الجهد، ومن التطبيقات المهمة للتوصيل على التوالي؛ وتُستخدم لإنتاج مصدر جهد بالقيمة المطلوبة من بطارية ذات جهد كبير.', '["الهبوط عبر إحدى المقاومتين جزء من جهد البطارية، فلا يمكن أن يزيد عليه.","","زيادة المقاومة على التوالي تقلل التيار ولا تضاعفه.","قطع التيار الكبير وظيفة المنصهر الكهربائي أو قاطع الدائرة، لا مجزّئ الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.360Z"}'::jsonb),
('mcq', 3, 2, 'في التوالي يتقاسم المصابيح المتماثلة جهد البطارية بالتساوي؛ فأربعة مصابيح يكون جهد كل منها $\frac{6}{4} = 1.5\ \text{V}$.', '["على التوازي يكون جهد كل مصباح 6 V كاملًا، فيزيد على 1.5 V.","على التوالي يتقاسم المصباحان 6 V فيكون جهد كل منهما 3 V.","","المصباح الواحد يكون جهده 6 V كاملًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.360Z"}'::jsonb),
('mcq', 4, 3, 'يوصل المنصهر على التوالي بمصدر الجهد ليمر فيه التيار الكلي فينصهر إذا زاد على الحد المسموح؛ فإذا تجاوز التيار ما تتحمله الدائرة انصهرت قطعته وفُتحت الدائرة.', '["لو كان فرق الجهد بين طرفيه مساويًا لجهد المصدر لكان موصولًا على التوازي، وهذا يحدث دائرة قصر.","إضافة عنصر على التوالي لا تقلل المقاومة المكافئة.","الغرض أن يحمي الدائرة كلها، فيجب أن يمر فيه التيار الكلي لا تيار فرع واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-27T21:51:39.361Z"}'::jsonb),
('mcq', 5, 1, 'مجموع الهبوط في الجهد يساوي جهد البطارية، فتأخذ المقاومة $\mathrm{R}$ نحو 3.0 V ويبقى 6.0 V للمصباح؛ وهذا تطبيق على تجزئة الجهد والحد من التيار.', '["المقاومة على التوالي تقلل جهد المصباح عن جهد البطارية ولا ترفعه.","","التيار نفسه في المقاومة والمصباح لأنهما على التوالي.","المسار البديل يتطلب توصيلًا على التوازي، والمقاومة هنا على التوالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-27T21:51:39.361Z"}'::jsonb),
('mcq', 6, 3, 'المصابيح الصغيرة لا تتحمل جهد الخط، وعند وصلها على التوالي يتوزع جهد الخط عليها، فيكون جهد كل مصباح جزءًا صغيرًا منه.', '["جهد الخط كاملًا لكل مصباح صفة التوصيل على التوازي.","في التوالي إذا احترق مصباح انطفأت المصابيح كلها؛ فهذا ليس غرضًا للتوالي.","زيادة عدد المصابيح على التوالي تزيد المقاومة المكافئة فيقل التيار ولا يزداد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.361Z"}'::jsonb),
('mcq', 7, 0, 'الترتيب (2) يحقق ذلك؛ لأن المقاومة المكافئة فيه أكبر: إضافة المقاومة على التوالي تزيد المقاومة المكافئة فيقل التيار الذي تزوده البطارية، بينما إضافتها على التوازي في (3) تقلل المكافئة فيزداد التيار الكلي.', '["","في (3) يتوزع التيار بين الفرعين، لكن المقاومة المكافئة أقل، فيزداد التيار الكلي من البطارية.","الترتيب (1) هو المرجع الأصلي، ولا توجد فيه أي مقاومة إضافية تخفض التيار.","التيار الذي تزوده البطارية يعتمد على المقاومة المكافئة، وهي مختلفة في الترتيبات الثلاثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-27T21:51:39.362Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) زيادة المقاومة المكافئة لتقليل التيار: المكافئة على التوالي مجموع المقاومات، فهي أكبر من أي مقاومة مفردة، فيقل التيار عند ثبات جهد المصدر. (2) تجزئة الجهد (مجزّئ الجهد): مجموع الهبوط في الجهد يساوي جهد المصدر، فيؤخذ من طرفي إحدى المقاومتين جهد أصغر بالقيمة المطلوبة. (3) الحماية بالمنصهر: يوصل المنصهر على التوالي بمصدر الجهد فيمر فيه التيار الكلي، وينصهر إذا زاد التيار على الحد المسموح. (ويُقبل أيضًا: تشغيل مصابيح صغيرة بجهد كبير بتقاسمها الجهد، كأسلاك الزينة.)', '["غرض أول مع التوضيح","غرض ثانٍ مع التوضيح","غرض ثالث مع التوضيح"]'::jsonb, '[]'::jsonb, '[{"element":"الغرض الأول","marks":2},{"element":"الغرض الثاني","marks":2},{"element":"الغرض الثالث","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"4–5 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–3 درجات","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «استقلال عمل الأجهزة» غرضًا للتوالي","ذكر أن التوالي يزيد التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.362Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) توصل المقاومتان على التوالي بين قطبي البطارية؛ لأن التيار نفسه يمر فيهما، فيتوزع جهد البطارية عليهما بحسب مقاومتيهما ($\mathrm{V} = \mathrm{I}\mathrm{R}$)، ومجموع الهبوطين 12 V. (b) يؤخذ الجهد من طرفي إحدى المقاومتين (ولتكن $\mathrm{R}_\mathrm{B}$)، فيكون الهبوط عبرها 4.0 V، والهبوط عبر الأخرى 8.0 V. (c) المقاومة التي لا يؤخذ منها الجهد ($\mathrm{R}_\mathrm{A}$) يجب أن تكون أكبر (مثلي $\mathrm{R}_\mathrm{B}$)؛ لأن الهبوط عبرها 8.0 V أكبر، والتيار نفسه في المقاومتين.', '["التوصيل على التوالي مع التعليل","أخذ الجهد من طرفي إحدى المقاومتين","الهبوط عبر الأخرى 8.0 V","المقاومة الأخرى أكبر (مثلا الأولى) مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"التوصيل والتعليل","marks":1},{"element":"موضع أخذ الجهد","marks":1},{"element":"الهبوط عبر الأخرى","marks":1},{"element":"المقارنة والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توصيل المقاومتين على التوازي","جعل المقاومة التي يؤخذ منها 4.0 V هي الأكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.363Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأن المصابيح على التوالي لها مسار واحد، فلو انفتح فتيل مصباح لانطفأت المصابيح كلها؛ أما المصباح الخاص فيصبح عند احتراقه موصلًا مقاومته صغيرة جدًّا فيبقى المسار مغلقًا وتظل بقية المصابيح مضيئة. (b) احتراق مصباح يجعل مقاومته نحو الصفر، فتقل المقاومة المكافئة للسلك، ويزداد التيار، ويزداد جهد كل مصباح باقٍ ليصل تدريجيًّا إلى جهد الخط. (c) كلما احترق مصباح زاد التيار، فإذا احترق عدد منها تجاوز التيار الحد الذي يتحمله المنصهر الموصول على التوالي، فينصهر ويفتح الدائرة حمايةً للمصابيح الباقية والأسلاك.', '["التوالي مسار واحد والمصباح الخاص يحافظ على إغلاقه","نقص المقاومة المكافئة وزيادة التيار وجهد كل مصباح","زيادة التيار فوق حد المنصهر فينصهر للحماية"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":2},{"element":"(b)","marks":2},{"element":"(c)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"4–5 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–3 درجات","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن دائرة القصر في مصباح واحد تطفئ المصابيح كلها","القول إن التيار يقل بعد احتراق المصابيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.363Z"}'::jsonb)
