('mcq', 6, 'أيّ مما يأتي ليس من أغراض توصيل الأجهزة على التوازي؟', null, null, '["عمل كل جهاز مستقلًّا عن الأجهزة الأخرى","حصول كل جهاز على جهد المصدر كاملًا","تجزئة جهد المصدر للحصول على جهد أصغر","تقليل المقاومة المكافئة للدائرة"]'::jsonb, 'تذكر', 'تمييز أغراض', 'متوسط', 'الكتاب ص 44 و48–49 — مجزّئ الجهد ودائرة التوازي'),
