('mcq', 2, 0, 'توصيل مقاومتين أو أكثر على التوازي يقلل دائمًا من المقاومة المكافئة للدائرة، فيزداد التيار الكلي مع بقاء فرق الجهد ثابتًا.', '["","زيادة المقاومة المكافئة غرض التوصيل على التوالي.","تقسيم جهد المصدر يحدث في التوالي (مجزّئ الجهد)، أما في التوازي فالجهد نفسه لكل فرع.","تساوي التيار صفة التوالي؛ وفي التوازي يعتمد تيار كل فرع على مقاومته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.364Z"}'::jsonb),
('mcq', 3, 3, 'يستمر المصباح والتلفاز في العمل كما هما؛ لأن لكل منهما مسارًا مستقلًّا وجهد المصدر نفسه: الأجهزة موصولة على التوازي، وفروع دائرة التوازي لا يعتمد بعضها على بعض؛ ففتح فرع الغلاية لا يغير جهد الفرعين الآخرين ولا تياريهما.', '["فتح المفتاح يقطع تيار فرع الغلاية فقط؛ فلكل فرع في التوازي مسار خاص.","تيار كل فرع يعتمد على جهده ومقاومته فقط، فلا يتغير بفتح فرع آخر.","جهد كل فرع يبقى مساويًا لجهد المصدر، ولا يتوزع في التوازي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-27T21:51:39.365Z"}'::jsonb),
('mcq', 4, 1, 'يوصل مقاومتين منها على التوازي؛ لأن التوصيل على التوازي يعطي مقاومة مكافئة أقل من أصغر مقاومة: $\frac{1}{\mathrm{R}} = \frac{1}{10} + \frac{1}{10}$، إذن $\mathrm{R} = 5.0\ \Omega$.', '["التوصيل على التوالي يعطي 20 Ω، أي مقاومة أكبر لا أصغر.","","أربع مقاومات على التوازي تعطي 2.5 Ω، وهي أقل من المطلوب.","هذا الترتيب يعطي مكافئة نحو 6.7 Ω لا 5.0 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.365Z"}'::jsonb),
('mcq', 5, 3, 'في التوازي (Y) يتصل طرفا كل مصباح بطرفي البطارية فيعمل بجهده الصحيح 12 V. وفي التوالي (X) يتوزع الجهد على المصابيح الثلاثة فيكون جهد كل منها $\frac{12}{3} = 4.0\ \text{V}$.', '["تساوي التيار لا يكفي؛ ففي X يتقاسم المصابيح 12 V فيكون جهد كل منها 4.0 V فقط.","زيادة المكافئة في X تقلل التيار والجهد لكل مصباح فيضيء بسطوع أقل من الصحيح.","في X يكون جهد كل مصباح 4.0 V وفي Y يكون 12 V، فلا يتساوى السطوع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.365Z"}'::jsonb),
('mcq', 6, 2, 'تجزئة جهد المصدر غرض التوصيل على التوالي (مجزّئ الجهد)؛ أما في التوازي فالجهد نفسه بين طرفي كل فرع.', '["هذا من أغراض التوازي؛ ففروعه لا يعتمد بعضها على بعض.","هذا من أغراض التوازي؛ فطرفا كل فرع متصلان بطرفي المصدر.","","هذا من أغراض التوازي؛ فكل فرع جديد يضيف مسارًا للتيار ويقلل المكافئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.365Z"}'::jsonb),
('mcq', 7, 0, 'بقاء المصباحين الآخرين مضيئين بالسطوع نفسه يعني أن انقطاع مسار المصباح المحترق لم يغيّر مسارَي المصباحين الآخرين ولا جهديهما؛ وهذا غرض التوصيل على التوازي: لكل مصباح مسار مستقل، وفروع التوازي لا يعتمد بعضها على بعض.', '["","في التوالي مسار واحد، فاحتراق مصباح يفتح الدائرة وتنطفئ المصابيح كلها.","كبر المقاومة المكافئة لا يمنع انقطاع المسار الوحيد في التوالي.","النوع صحيح لكن التعليل خاطئ؛ فالتيار لا يكون نفسه بالضرورة في فروع التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-27T21:51:39.366Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) استقلال عمل كل جهاز: فروع التوازي لا يعتمد بعضها على بعض، فيمكن تشغيل جهاز أو إطفاؤه دون التأثير في غيره، ولا يتوقف الباقي إذا تعطل أحدها. (2) حصول كل جهاز على جهد المصدر كاملًا: طرفا كل فرع متصلان بطرفي المصدر، فيعمل كل جهاز بجهده الصحيح. (3) تقليل المقاومة المكافئة: كل فرع جديد يضيف مسارًا للتيار، فتصبح المكافئة أقل من أصغر مقاومة. وتكون تمديدات المنازل على التوازي لأن الأجهزة المنزلية يجب أن تعمل جميعها بجهد المقبس نفسه، وأن تُشغَّل وتُطفأ كلٌّ على حدة.', '["استقلال عمل الأجهزة مع التوضيح","جهد المصدر كاملًا لكل جهاز مع التوضيح","تقليل المقاومة المكافئة مع التوضيح","تعليل التمديدات المنزلية"]'::jsonb, '[]'::jsonb, '[{"element":"الغرض الأول","marks":1},{"element":"الغرض الثاني","marks":1},{"element":"الغرض الثالث","marks":1},{"element":"التمديدات المنزلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «تجزئة الجهد» غرضًا للتوازي","القول إن التوازي يقلل التيار الكلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-27T21:51:39.366Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) على التوازي: $\frac{1}{\mathrm{R}} = \frac{3}{30}$، إذن $\mathrm{R} = 10\ \Omega$. (b) على التوالي: $\mathrm{R} = 90\ \Omega$. (c) التوازي: $\mathrm{I} = 6.0/10 = 0.60\ \text{A}$، والتوالي: $\mathrm{I} = 6.0/90 = 0.067\ \text{A}$؛ فالتيار الكلي أكبر في التوازي. والغرض المحقق تقليل المقاومة المكافئة وزيادة التيار الكلي مع بقاء جهد كل مقاومة 6.0 V.', '["التوازي يعطي 10 Ω","التوالي يعطي 90 Ω","التياران 0.60 A و0.067 A","التوازي يقلل المكافئة ويزيد التيار الكلي"]'::jsonb, '["$\\frac{1}{\\mathrm{R}} = \\frac{1}{30} + \\frac{1}{30} + \\frac{1}{30}$، إذن $\\mathrm{R} = 10\\ \\Omega$","$\\mathrm{R} = 30 + 30 + 30 = 90\\ \\Omega$","$\\mathrm{I} = \\frac{6.0}{10} = 0.60\\ \\text{A}$ و$\\mathrm{I} = \\frac{6.0}{90} = 0.067\\ \\text{A}$"]'::jsonb, '[{"element":"التوصيل على التوازي","marks":1},{"element":"التوصيل على التوالي","marks":1},{"element":"التياران","marks":1},{"element":"الغرض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا مع نقص في التعليل أو في أحد العناصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس التوصيلين","نسيان قلب مجموع المقلوبات (0.10 Ω)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.366Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) يتقاسم الأجهزة الثلاثة جهد المقبس، فيكون جهد كل منها أقل من 120 V فلا يعمل بصورة صحيحة؛ وفي التوازي يحصل كل جهاز على 120 V كاملة. (2) لا يمكن تشغيل جهاز وحده؛ فإطفاء أي جهاز أو تعطله يفتح المسار الوحيد فتتوقف الأجهزة كلها؛ وفي التوازي لكل جهاز مسار مستقل. (3) يمر التيار نفسه في الأجهزة جميعها رغم اختلاف حاجاتها، والمقاومة المكافئة كبيرة فيكون التيار صغيرًا؛ وفي التوازي يأخذ كل جهاز التيار المناسب له بحسب مقاومته.', '["مشكلة تقاسم الجهد ومعالجتها","مشكلة اعتماد الأجهزة بعضها على بعض ومعالجتها","مشكلة التيار الواحد ومعالجتها"]'::jsonb, '[]'::jsonb, '[{"element":"المشكلة الأولى","marks":2},{"element":"المشكلة الثانية","marks":2},{"element":"المشكلة الثالثة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بعناصرها جميعها"},{"level":"4–5 درجات","description":"معظم العناصر صحيحة مع خطأ أو نقص محدود"},{"level":"1–3 درجات","description":"عناصر قليلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأجهزة تعمل بجهد أكبر على التوالي","إغفال أن إطفاء جهاز يوقف الأجهزة الأخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.367Z"}'::jsonb)
