from (values
('mcq', 1, 'في دائرة مجزّئ الجهد الآتية، ما قراءة الفولتمتر الموصول بين طرفي المقاومة $\mathrm{R}_\mathrm{B}$؟', null, '[{"src":"qimg/phys32/c2l1-o12-div.svg","alt":"دائرة مجزّئ جهد: بطارية على اليسار مكتوب بجانبها 12.0 V وقطبها الموجب أعلى. على الضلع الأيمن مقاومتان على التوالي: العليا RA مقدارها 200 Ω، والسفلى RB مقدارها 400 Ω. فولتمتر V موصول بسلكين بين طرفي المقاومة RB (من نقطة الوصل بين المقاومتين إلى السلك السفلي)."}]'::jsonb, '["$4.0\\ \\text{V}$","$8.0\\ \\text{V}$","$6.0\\ \\text{V}$","$24\\ \\text{V}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 46–47 — مثال 2 (مجزّئ الجهد)'),
('mcq', 2, 'يُراد تصميم مجزّئ جهد يعطي 3.0 V بين طرفي مقاومة $\mathrm{R}_\mathrm{B} = 1.0\ \text{k}\Omega$ من بطارية جهدها 9.0 V. ما مقدار المقاومة $\mathrm{R}_\mathrm{A}$ التي توصل معها على التوالي؟', null, null, '["$0.50\\ \\text{k}\\Omega$","$3.0\\ \\text{k}\\Omega$","$2.0\\ \\text{k}\\Omega$","$1.0\\ \\text{k}\\Omega$"]'::jsonb, 'تطبيق', 'تصميم', 'متوسط', 'الكتاب ص 47 — مسائل تدريبية 11؛ ص 65 السؤال 64'),
('mcq', 3, 'تُصنع المقاومة الضوئية عادة من مواد شبه موصلة مثل السليكون. كيف تتغير مقاومتها بزيادة كمية الضوء الساقط عليها؟', null, null, '["تزداد من نحو 400 Ω إلى نحو 400,000 Ω","تبقى ثابتة لأنها مقاومة أومية","تقل، فتكون أصغر كثيرًا في الضوء منها في الظلام","تقل إلى الصفر فتصبح موصلًا فائق التوصيل"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 45 — مجزّئات الجهد مع المجسّات والشكل 2-5'),
('mcq', 4, 'يبين الشكل الآتي دائرة مقياس للضوء: مجزّئ جهد فيه مقاومة $\mathrm{R}_\mathrm{A}$ ومقاومة ضوئية، وفولتمتر بين طرفي المقاومة الضوئية. ماذا يحدث لقراءة الفولتمتر عند زيادة الضوء الساقط على المقاومة الضوئية؟', null, '[{"src":"qimg/phys32/c2l1-o12-meter.svg","alt":"دائرة مقياس ضوء: بطارية على اليسار قطبها الموجب أعلى. على الضلع الأيمن مقاومة RA في الأعلى، وتحتها على التوالي مقاومة ضوئية (رمز مقاومة متعرجة داخل إطار بيضوي) مكتوب بجانبها «مقاومة ضوئية». أربعة أسهم حمراء أفقية مكتوب فوقها «ضوء» تتجه نحو المقاومة الضوئية من اليمين. فولتمتر V موصول بسلكين بين طرفي المقاومة الضوئية (من نقطة الوصل بين RA والمقاومة الضوئية إلى السلك السفلي)."}]'::jsonb, '["تزداد، لأن الضوء يعطي المقاومة الضوئية طاقة إضافية","تقل، لأن نصيب المقاومة الضوئية من جهد البطارية يقل بنقص مقاومتها","تبقى ثابتة، لأن جهد البطارية لم يتغير","تقل إلى الصفر، لأن التيار يتوقف في الدائرة"]'::jsonb, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 45 — مجزّئات الجهد مع المجسّات والشكل 2-5'),
('mcq', 5, 'وُصلت مقاومة ثابتة $\mathrm{R}_\mathrm{A} = 2.0\ \text{k}\Omega$ على التوالي بمقاومة ضوئية وبطارية جهدها 6.0 V. إذا كانت مقاومة المقاومة الضوئية في ضوء ساطع 400 Ω، فما مقدار الهبوط في الجهد عبرها؟', null, null, '["$1.0\\ \\text{V}$","$5.0\\ \\text{V}$","$3.0\\ \\text{V}$","$1.2\\ \\text{V}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 45 — مجزّئات الجهد مع المجسّات والشكل 2-5'),
('mcq', 6, 'في مجزّئ جهد يتكون من بطارية ومقاومتين $\mathrm{R}_\mathrm{A}$ و$\mathrm{R}_\mathrm{B}$ على التوالي، استُبدلت بالمقاومة $\mathrm{R}_\mathrm{A}$ مقاومة متغيرة، ثم زيد مقدارها. ماذا يحدث للجهد الناتج $\mathrm{V}_\mathrm{B}$ بين طرفي $\mathrm{R}_\mathrm{B}$؟', null, null, '["يزداد، لأن المقاومة المكافئة للدائرة زادت","يبقى ثابتًا، لأن $\\mathrm{R}_\\mathrm{B}$ لم تتغير","يزداد، لأن الجهد الكلي يتوزع على مقاومة أكبر","يقل، لأن التيار يقل ويزداد نصيب $\\mathrm{R}_\\mathrm{A}$ من الجهد"]'::jsonb, 'تحليل', 'تنبؤ', 'متوسط', 'الكتاب ص 62 — السؤال 41'),
('mcq', 7, 'يُراد استعمال مجزّئ جهد مكوَّن من بطارية ومقاومة ثابتة ومقاومة ضوئية على التوالي، بحيث تزداد قراءة فولتمتر كلما زاد الضوء الساقط على المقاومة الضوئية. أين يجب توصيل الفولتمتر؟', null, null, '["بين طرفي المقاومة الضوئية، لأن مقاومتها تتغير مع الضوء","على التوالي مع المقاومة الضوئية، ليمر فيه التيار نفسه","بين طرفي المقاومة الثابتة، لأن نصيبها من الجهد يزداد عند نقص مقاومة المجسّ","بين قطبي البطارية، لأن جهدها يزداد بزيادة الضوء"]'::jsonb, 'تحليل', 'تصميم', 'صعب', 'الكتاب ص 45 — مجزّئات الجهد مع المجسّات والشكل 2-5'),
('essay', 1, 'وُصلت مقاومتان $\mathrm{R}_\mathrm{A} = 330\ \Omega$ و$\mathrm{R}_\mathrm{B} = 560\ \Omega$ على التوالي ببطارية جهدها 9.0 V على شكل مجزّئ جهد. (a) اشتق العلاقة $\mathrm{V}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$ من قاعدتي دائرة التوالي. (b) احسب الجهد الناتج بين طرفي $\mathrm{R}_\mathrm{B}$. (c) احسب الهبوط في الجهد عبر $\mathrm{R}_\mathrm{A}$، وتحقق من أن مجموع الهبوطين يساوي جهد البطارية.', null, null, null, 'تطبيق', 'اشتقاق وحساب', 'سهل', 'الكتاب ص 44 — مجزّئ الجهد والشكل 2-4'),
('essay', 2, 'يريد طالب تشغيل جهاز يحتاج إلى 6.0 V من بطارية جهدها 15.0 V، فصمّم مجزّئ جهد يكون فيه الجهاز موصولًا بين طرفي مقاومة $\mathrm{R}_\mathrm{B} = 2.0\ \text{k}\Omega$. (a) احسب مقدار المقاومة $\mathrm{R}_\mathrm{A}$ اللازمة. (b) احسب التيار المار في المجزّئ. (c) ارسم مخططًا للدائرة يبين موضع الفولتمتر الذي يتحقق به الطالب من الجهد الناتج.', null, null, null, 'تطبيق', 'تصميم', 'صعب', 'الكتاب ص 47 — مسائل تدريبية 10 و11؛ ص 65 السؤال 64'),
('essay', 3, 'يبين الشكل الآتي دائرة مقياس للضوء: بطارية جهدها 9.0 V، ومقاومة ضبط الحساسية $\mathrm{R}_\mathrm{A} = 10\ \text{k}\Omega$، ومقاومة ضوئية مقاومتها نحو 400 Ω في الضوء الساطع ونحو 400 kΩ في الظلام، وفولتمتر بين طرفي المقاومة الضوئية. (a) احسب قراءة الفولتمتر في الضوء الساطع وفي الظلام. (b) فسّر كيف تصلح هذه الدائرة مقياسًا لكمية الضوء. (c) ماذا يحدث لقراءة الفولتمتر في الضوء نفسه إذا زيدت مقاومة ضبط الحساسية؟ وضّح.', null, '[{"src":"qimg/phys32/c2l1-o12-e3.svg","alt":"دائرة مقياس ضوء: بطارية على اليسار مكتوب بجانبها 9.0 V وقطبها الموجب أعلى. على الضلع الأيمن مقاومة RA مكتوب بجانبها 10 kΩ في الأعلى، وتحتها على التوالي مقاومة ضوئية (رمز مقاومة متعرجة داخل إطار بيضوي) مكتوب بجانبها «مقاومة ضوئية». أربعة أسهم حمراء أفقية مكتوب فوقها «ضوء» تتجه نحو المقاومة الضوئية. فولتمتر V موصول بين طرفي المقاومة الضوئية."}]'::jsonb, null, 'تحليل', 'تفسير تطبيق', 'صعب', 'الكتاب ص 45 — مجزّئات الجهد مع المجسّات والشكل 2-5')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
