from (values
('mcq', 1, 1, '$\mathrm{V}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}} = \frac{(12.0\ \text{V})(400\ \Omega)}{200\ \Omega + 400\ \Omega} = 8.0\ \text{V}$.', '["عوّض $\\mathrm{R}_\\mathrm{A}$ بدل $\\mathrm{R}_\\mathrm{B}$ في البسط، فحسب الهبوط عبر المقاومة الأخرى.","","افترض أن الجهد يتوزع بالتساوي على المقاومتين مع أنهما مختلفتان.","قسم على $\\mathrm{R}_\\mathrm{A}$ وحدها بدل مجموع المقاومتين ($\\frac{12.0 \\times 400}{200}$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.379Z"}'::jsonb),
('mcq', 2, 2, 'التيار $\mathrm{I} = \frac{\mathrm{V}_\mathrm{B}}{\mathrm{R}_\mathrm{B}} = \frac{3.0\ \text{V}}{1.0\ \text{k}\Omega} = 3.0\ \text{mA}$، والهبوط عبر $\mathrm{R}_\mathrm{A}$ $= 9.0 - 3.0 = 6.0\ \text{V}$، إذن $\mathrm{R}_\mathrm{A} = \frac{6.0\ \text{V}}{3.0\ \text{mA}} = 2.0\ \text{k}\Omega$.', '["قلب النسبة فجعل $\\mathrm{R}_\\mathrm{A} = \\mathrm{R}_\\mathrm{B}\\frac{\\mathrm{V}_\\mathrm{B}}{\\mathrm{V} - \\mathrm{V}_\\mathrm{B}}$.","هذه المقاومة المكافئة للدائرة $\\frac{9.0}{3.0\\ \\text{mA}}$ لا مقدار $\\mathrm{R}_\\mathrm{A}$.","","المقاومتان المتساويتان تقسمان الجهد مناصفة (4.5 V)، لا 3.0 V."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-27T21:51:39.380Z"}'::jsonb),
('mcq', 3, 2, 'تعتمد المقاومة الضوئية على كمية الضوء الساقط عليها؛ فمقاومتها في الضوء نحو 400 Ω، وتصل إلى نحو 400,000 Ω في مكان معتم؛ أي أنها تقل كثيرًا بزيادة الضوء.', '["عكس الاتجاه: 400,000 Ω قيمتها في الظلام، و400 Ω قيمتها في الضوء.","المقاومة الضوئية مجسّ تتغير مقاومته مع الضوء، ولو كانت ثابتة لما صلحت لقياس الضوء.","","تبقى لها مقاومة في الضوء (نحو 400 Ω)، ولا تصبح صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.380Z"}'::jsonb),
('mcq', 4, 1, 'بزيادة الضوء تقل مقاومة المجسّ $\mathrm{R}_\mathrm{B}$، فيقل الكسر $\frac{\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$ في العلاقة $\mathrm{V}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$؛ أي أن نصيب المقاومة الضوئية من جهد البطارية يقل بنقص مقاومتها، فتقل قراءة الفولتمتر عند زيادة الاستضاءة.', '["الضوء يغير مقاومة المجسّ فقط، ونقص مقاومته يقلل الهبوط في الجهد عبره.","","جهد البطارية ثابت، لكن توزيعه بين المقاومتين يتغير بتغير مقاومة المجسّ.","التيار يزداد ولا يتوقف، والمجسّ تبقى له مقاومة فلا ينعدم الجهد عبره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-27T21:51:39.380Z"}'::jsonb),
('mcq', 5, 0, '$\mathrm{V}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}} = \frac{(6.0\ \text{V})(400\ \Omega)}{2000\ \Omega + 400\ \Omega} = 1.0\ \text{V}$.', '["","هذا الهبوط عبر المقاومة الثابتة $\\mathrm{R}_\\mathrm{A}$ (6.0 − 1.0) لا عبر المقاومة الضوئية.","افترض أن الجهد يتوزع مناصفة بين المقاومتين.","قسم على $\\mathrm{R}_\\mathrm{A}$ وحدها بدل مجموع المقاومتين ($\\frac{6.0 \\times 400}{2000}$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.381Z"}'::jsonb),
('mcq', 6, 3, 'زيادة $\mathrm{R}_\mathrm{A}$ تزيد المقاومة المكافئة فيقل التيار، و$\mathrm{V}_\mathrm{B} = \mathrm{I}\mathrm{R}_\mathrm{B}$ يقل؛ أو من العلاقة $\mathrm{V}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$ يزداد المقام فيقل $\mathrm{V}_\mathrm{B}$، ويزداد نصيب $\mathrm{R}_\mathrm{A}$ من جهد البطارية.', '["زيادة المقاومة المكافئة تقلل التيار، فيقل الهبوط عبر $\\mathrm{R}_\\mathrm{B}$ لا يزيد.","الهبوط $\\mathrm{V}_\\mathrm{B} = \\mathrm{I}\\mathrm{R}_\\mathrm{B}$ يعتمد على التيار أيضًا، وقد قلّ التيار.","المقاومة التي زادت هي $\\mathrm{R}_\\mathrm{A}$، فيزداد نصيبها هي من الجهد لا نصيب $\\mathrm{R}_\\mathrm{B}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-27T21:51:39.381Z"}'::jsonb),
('mcq', 7, 2, 'بزيادة الضوء تقل مقاومة المجسّ فيزداد التيار، فيزداد الهبوط في الجهد عبر المقاومة الثابتة $\mathrm{V}_\mathrm{A} = \mathrm{I}\mathrm{R}_\mathrm{A}$ بينما يقل الهبوط عبر المجسّ؛ ولأن مجموع الهبوطين يساوي جهد البطارية، فالفولتمتر بين طرفي المقاومة الثابتة تزداد قراءته بزيادة الضوء.', '["الهبوط عبر المقاومة الضوئية يقل بزيادة الضوء، فقراءة الفولتمتر بين طرفيها تقل لا تزداد.","الفولتمتر يوصل على التوازي لقياس فرق الجهد، وتوصيله على التوالي يعطل الدائرة لكبر مقاومته.","","جهد البطارية لا يعتمد على الضوء، فقراءة الفولتمتر بين قطبيها لا تتأثر به."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.382Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المقاومة المكافئة $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}$، والتيار $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$ وهو نفسه في المقاومتين، و$\mathrm{V}_\mathrm{B} = \mathrm{I}\mathrm{R}_\mathrm{B} = \frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$. (b) $\mathrm{V}_\mathrm{B} = \frac{(9.0\ \text{V})(560\ \Omega)}{890\ \Omega} = 5.7\ \text{V}$. (c) $\mathrm{V}_\mathrm{A} = \frac{(9.0\ \text{V})(330\ \Omega)}{890\ \Omega} = 3.3\ \text{V}$، و$5.7 + 3.3 = 9.0\ \text{V}$ يساوي جهد البطارية. والنتيجة منطقية لأن $\mathrm{R}_\mathrm{B}$ أكبر من نصف المقاومة المكافئة فنصيبها أكبر من نصف جهد البطارية.', '["الاشتقاق من $\\mathrm{R} = \\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{B}$ و$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}}$ و$\\mathrm{V}_\\mathrm{B} = \\mathrm{I}\\mathrm{R}_\\mathrm{B}$","$\\mathrm{V}_\\mathrm{B} = 5.7\\ \\text{V}$","$\\mathrm{V}_\\mathrm{A} = 3.3\\ \\text{V}$","التحقق: المجموع 9.0 V"]'::jsonb, '["$\\mathrm{I} = \\frac{9.0\\ \\text{V}}{330\\ \\Omega + 560\\ \\Omega} = 0.010\\ \\text{A}$","$\\mathrm{V}_\\mathrm{B} = \\frac{9.0 \\times 560}{890} = 5.66 \\approx 5.7\\ \\text{V}$","$\\mathrm{V}_\\mathrm{A} = \\frac{9.0 \\times 330}{890} = 3.34 \\approx 3.3\\ \\text{V}$","$5.7 + 3.3 = 9.0\\ \\text{V}$"]'::jsonb, '[{"element":"الاشتقاق","marks":1},{"element":"حساب $\\mathrm{V}_\\mathrm{B}$","marks":1},{"element":"حساب $\\mathrm{V}_\\mathrm{A}$ والتحقق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"اشتقاق صحيح وحسابات صحيحة مع التحقق."},{"level":"2 درجتان","description":"حسابات صحيحة دون اشتقاق، أو اشتقاق مع خطأ في حساب."},{"level":"1 درجة","description":"حساب واحد صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["وضع $\\mathrm{R}_\\mathrm{A}$ في البسط عند حساب $\\mathrm{V}_\\mathrm{B}$.","القسمة على $\\mathrm{R}_\\mathrm{B}$ وحدها بدل مجموع المقاومتين.","كتابة الناتج 5.66 V بأرقام معنوية تزيد على أرقام المعطيات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.382Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يجب أن يكون الهبوط عبر $\mathrm{R}_\mathrm{A}$ $= 15.0 - 6.0 = 9.0\ \text{V}$. ولأن التيار نفسه في المقاومتين: $\frac{\mathrm{V}_\mathrm{A}}{\mathrm{R}_\mathrm{A}} = \frac{\mathrm{V}_\mathrm{B}}{\mathrm{R}_\mathrm{B}}$، إذن $\mathrm{R}_\mathrm{A} = \mathrm{R}_\mathrm{B}\frac{\mathrm{V}_\mathrm{A}}{\mathrm{V}_\mathrm{B}} = (2.0\ \text{k}\Omega)\frac{9.0}{6.0} = 3.0\ \text{k}\Omega$. (b) $\mathrm{I} = \frac{\mathrm{V}_\mathrm{B}}{\mathrm{R}_\mathrm{B}} = \frac{6.0\ \text{V}}{2000\ \Omega} = 3.0\times10^{-3}\ \text{A} = 3.0\ \text{mA}$، وللتحقق: $\frac{15.0\ \text{V}}{5.0\ \text{k}\Omega} = 3.0\ \text{mA}$. (c) بطارية 15.0 V موصولة على التوالي بالمقاومتين $\mathrm{R}_\mathrm{A} = 3.0\ \text{k}\Omega$ و$\mathrm{R}_\mathrm{B} = 2.0\ \text{k}\Omega$، والفولتمتر موصول على التوازي بين طرفي $\mathrm{R}_\mathrm{B}$ فيقرأ 6.0 V.', '["الهبوط عبر $\\mathrm{R}_\\mathrm{A}$ يساوي 9.0 V","$\\mathrm{R}_\\mathrm{A} = 3.0\\ \\text{k}\\Omega$","التيار 3.0 mA","مخطط صحيح بالرموز والفولتمتر على التوازي مع $\\mathrm{R}_\\mathrm{B}$"]'::jsonb, '["$\\mathrm{V}_\\mathrm{A} = 15.0 - 6.0 = 9.0\\ \\text{V}$","$\\mathrm{R}_\\mathrm{A} = 2.0 \\times \\frac{9.0}{6.0} = 3.0\\ \\text{k}\\Omega$","$\\mathrm{I} = \\frac{6.0}{2000} = 3.0\\ \\text{mA}$"]'::jsonb, '[{"element":"حساب الهبوط عبر $\\mathrm{R}_\\mathrm{A}$ ومقدارها","marks":2},{"element":"حساب التيار","marks":1},{"element":"المخطط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة ومخطط صحيح."},{"level":"2–3 درجات","description":"حساب $\\mathrm{R}_\\mathrm{A}$ صحيح مع خطأ في التيار أو المخطط."},{"level":"1 درجة","description":"حساب الهبوط عبر $\\mathrm{R}_\\mathrm{A}$ فقط أو مخطط صحيح فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["حساب $\\mathrm{R}_\\mathrm{A} = \\mathrm{R}_\\mathrm{B}\\frac{\\mathrm{V}_\\mathrm{B}}{\\mathrm{V}_\\mathrm{A}}$ بقلب النسبة.","توصيل الفولتمتر على التوالي في المخطط.","إهمال تحويل kΩ إلى Ω عند حساب التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-27T21:51:39.384Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) في الضوء: $\mathrm{V}_\mathrm{B} = \frac{(9.0)(400)}{10000 + 400} = 0.35\ \text{V}$. في الظلام: $\mathrm{V}_\mathrm{B} = \frac{(9.0)(400000)}{10000 + 400000} = 8.8\ \text{V}$. (b) يعتمد الجهد الناتج عن المجزّئ على مقاومة المجسّ، ومقاومته تعتمد على كمية الضوء الساقط عليه؛ فكلما زادت الاستضاءة قلّت مقاومته وقلّ نصيبه من جهد البطارية، فتقل قراءة الفولتمتر؛ وتحوّل دائرة إلكترونية هذه القراءة إلى قياس للاستضاءة. (c) زيادة $\mathrm{R}_\mathrm{A}$ تزيد المقاومة المكافئة فيقل التيار، فيقل الجهد بين طرفي المقاومة الضوئية $\frac{\mathrm{V}\mathrm{R}_\mathrm{B}}{\mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{B}}$ (يكبر المقام)؛ لذا تُستعمل $\mathrm{R}_\mathrm{A}$ لضبط مدى القراءات (الحساسية).', '["قراءة الضوء نحو 0.35 V","قراءة الظلام نحو 8.8 V","تفسير عمل المقياس بتغير مقاومة المجسّ ونصيبه من الجهد","زيادة $\\mathrm{R}_\\mathrm{A}$ تقلل القراءة مع التعليل"]'::jsonb, '["ضوء: $\\frac{9.0 \\times 400}{10400} = 0.346 \\approx 0.35\\ \\text{V}$","ظلام: $\\frac{9.0 \\times 400000}{410000} = 8.78 \\approx 8.8\\ \\text{V}$"]'::jsonb, '[{"element":"حسابا القراءتين","marks":2},{"element":"تفسير عمل المقياس","marks":1},{"element":"أثر زيادة $\\mathrm{R}_\\mathrm{A}$ مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسيران صحيحان."},{"level":"2–3 درجات","description":"حسابان صحيحان مع تفسير واحد، أو تفسيران مع حساب واحد."},{"level":"1 درجة","description":"حساب واحد أو تفسير واحد."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["القول إن القراءة تزداد بزيادة الضوء.","نسيان تحويل kΩ إلى Ω فيُجمع 10 مع 400.","القول إن زيادة $\\mathrm{R}_\\mathrm{A}$ تزيد القراءة لأن المقاومة المكافئة زادت."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-27T21:51:39.385Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C2-L1-O12') and x.type = v.type and x.number = v.number
