insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L1-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'مصباحان كهربائيان صُمّما للعمل على جهد 120 V، قدرة الأول 60 W وقدرة الثاني 100 W. أيّهما مقاومته أكبر؟', null, null, '["المصباح 100 W، لأن قدرته أكبر","المصباح 60 W، لأن قدرته أقل عند الجهد نفسه","مقاومتاهما متساويتان لأنهما يعملان على الجهد نفسه","المصباح 100 W، لأنه يسحب تيارًا أكبر"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة'),
('mcq', 2, 'وُصل مصباحان قدرتاهما 60 W و100 W (صُمّما للعمل على 120 V) على التوازي بمصدر جهده 120 V. أيّ العبارات الآتية تصف سطوعيهما؟', null, null, '["سطوع المصباح 100 W أكبر، لأن جهديهما متساويان ومقاومته أصغر فيستنفد قدرة أكبر","سطوع المصباح 60 W أكبر، لأن مقاومته أكبر فيستنفد قدرة أكبر","سطوعاهما متساويان، لأن فرق الجهد بين طرفي كل منهما متساوٍ","سطوع المصباح 100 W أكبر، لأن التيار نفسه يمر فيهما ومقاومته أصغر"]'::jsonb, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة'),
('mcq', 3, 'وُصل المصباحان نفسهما (60 W و100 W، صُمّما للعمل على 120 V) على التوالي بمصدر جهده 120 V. أيّ العبارات الآتية صحيحة؟', null, null, '["سطوع المصباح 100 W أكبر، لأن قدرته المكتوبة عليه أكبر","سطوعاهما متساويان، لأن التيار نفسه يمر فيهما","سطوع المصباح 100 W أكبر، لأن مقاومته أصغر فيمر فيه تيار أكبر","سطوع المصباح 60 W أكبر، لأن مقاومته أكبر والتيار متساوٍ"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة؛ ص 63 السؤال 45'),
('mcq', 4, 'وُصل مصباح مقاومته 240 Ω (قدرته المقررة 60 W) ومصباح مقاومته 144 Ω (قدرته المقررة 100 W) على التوالي بمصدر جهده 120 V. ما مقدار القدرة المستنفدة في المصباح 240 Ω؟ (افترض ثبات المقاومتين)', null, null, '["$14\\ \\text{W}$","$60\\ \\text{W}$","$23\\ \\text{W}$","$38\\ \\text{W}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة'),
('mcq', 5, 'في الدائرة الآتية ثلاثة مصابيح متماثلة. كيف يُرتَّب سطوعها؟', null, '[{"src":"qimg/phys32/c2l1-o13-mix.svg","alt":"دائرة كهربائية: بطارية على الضلع الأيسر قطبها الموجب أعلى، وسلك علوي وسلك سفلي يتصل بينهما فرعان على التوازي: الفرع الأوسط فيه المصباح L1 وحده، والفرع الأيمن فيه المصباحان L2 (أعلى) وL3 (أسفل) موصولان على التوالي."}]'::jsonb, '["$\\mathrm{L}_1$ أكبرها سطوعًا، و$\\mathrm{L}_2$ و$\\mathrm{L}_3$ متساويان وأقل سطوعًا","$\\mathrm{L}_2$ أكبرها سطوعًا، ثم $\\mathrm{L}_3$، ثم $\\mathrm{L}_1$","المصابيح الثلاثة متساوية السطوع لأنها متماثلة ويمر فيها التيار الكلي","$\\mathrm{L}_1$ أقلها سطوعًا، و$\\mathrm{L}_2$ و$\\mathrm{L}_3$ متساويان وأكبر سطوعًا"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 57 — السؤال 23 والشكل 2-13'),
('mcq', 6, 'وُصلت مقاومتان (مصباحان) $\mathrm{R}_\mathrm{X} = 20\ \Omega$ و$\mathrm{R}_\mathrm{Y} = 40\ \Omega$ على التوالي ببطارية. ما النسبة $\frac{\mathrm{P}_\mathrm{Y}}{\mathrm{P}_\mathrm{X}}$ بين القدرتين المستنفدتين فيهما؟', null, null, '["تساوي 0.5","تساوي 4","تساوي 1","تساوي 2"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 51 — سطوع المصباح يتناسب طرديًّا مع القدرة المستنفدة، P = I²R'),
('mcq', 7, 'وُصل مصباحان متماثلان على التوالي ببطارية، ثم أُعيد توصيلهما على التوازي بالبطارية نفسها. كيف تقارن القدرة المستنفدة في كل مصباح في حالة التوازي بقدرته في حالة التوالي؟ (أهمل المقاومة الداخلية للبطارية، وافترض ثبات مقاومة المصباح)', null, null, '["أربعة أمثالها، فيكون سطوعه أكبر","مثلاها، لأن التيار المار فيه يتضاعف","تساويها، لأن المصباحين والبطارية لم يتغيرا","نصفها، لأن التيار يتوزع على فرعين"]'::jsonb, 'تحليل', 'مقارنة كمية', 'صعب', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة'),
('essay', 1, 'مصباحان صُمّما للعمل على 120 V، قدرة الأول 60 W وقدرة الثاني 100 W. (a) احسب مقاومة كل منهما. (b) إذا وُصلا على التوازي بمصدر 120 V، فاحسب القدرة المستنفدة في كل منهما، وحدّد أيهما أكثر سطوعًا. (c) إذا وُصلا على التوالي بالمصدر نفسه، فاحسب التيار والقدرة المستنفدة في كل منهما، وحدّد أيهما أكثر سطوعًا. (d) فسّر اختلاف النتيجتين. (افترض ثبات المقاومتين)', null, null, null, 'تحليل', 'مقارنة بالحساب', 'متوسط', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة؛ ص 63 السؤال 45'),
('essay', 2, 'في الدائرة الآتية ثلاثة مصابيح متماثلة مقاومة كل منها 12 Ω، وجهد البطارية 6.0 V. (a) احسب التيار والقدرة المستنفدة في كل مصباح، ثم رتّب المصابيح حسب سطوعها. (b) إذا انقطع فتيل $\mathrm{L}_3$، فماذا يحدث لسطوع كل من $\mathrm{L}_1$ و$\mathrm{L}_2$؟ (c) اقترح طريقة لجعل المصابيح الثلاثة تضيء بالسطوع نفسه دون إضافة مقاومات، وعلّل.', null, '[{"src":"qimg/phys32/c2l1-o13-mix.svg","alt":"دائرة كهربائية: بطارية على الضلع الأيسر قطبها الموجب أعلى، وسلك علوي وسلك سفلي يتصل بينهما فرعان على التوازي: الفرع الأوسط فيه المصباح L1 وحده، والفرع الأيمن فيه المصباحان L2 (أعلى) وL3 (أسفل) موصولان على التوالي."}]'::jsonb, null, 'تحليل', 'تحليل دائرة', 'صعب', 'الكتاب ص 57 — الأسئلة 23 و25 و28 والشكل 2-13'),
('essay', 3, 'قال طالب: «المصباح المكتوب عليه قدرة أكبر يكون دائمًا أشد سطوعًا من المصباح المكتوب عليه قدرة أقل». قوّم هذه العبارة، مستخدمًا مصباحين صُمّما للعمل على 220 V قدرتاهما 40 W و100 W، بحساب القدرة المستنفدة في كل منهما عند توصيلهما على التوالي بمصدر 220 V، ثم اذكر الحالة التي تصح فيها عبارة الطالب. (افترض ثبات المقاومتين)', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 51 — أثر توصيلات التوالي والتوازي في دوائر الإضاءة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
