insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'عند الجهد نفسه $\mathrm{R} = \frac{\mathrm{V}^2}{\mathrm{P}}$: للمصباح 60 W $\frac{(120)^2}{60} = 240\ \Omega$، وللمصباح 100 W $\frac{(120)^2}{100} = 144\ \Omega$؛ فمقاومة المصباح 60 W أكبر لأن قدرته أقل عند الجهد نفسه.', '["القدرة الأكبر عند الجهد نفسه تعني مقاومة أصغر، لا أكبر.","","تساوي الجهد لا يعني تساوي المقاومة؛ فاختلاف القدرة سببه اختلاف المقاومة.","سحبه تيارًا أكبر عند الجهد نفسه دليل على أن مقاومته أصغر ($\\mathrm{R} = \\frac{\\mathrm{V}}{\\mathrm{I}}$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.386Z"}'::jsonb),
('mcq', 2, 0, 'في التوازي فرق الجهد بين طرفي كل مصباح 120 V، والقدرة $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}}$ (أو $\mathrm{P} = \mathrm{I}^2\mathrm{R}$ مع تيار أكبر في المصباح ذي المقاومة الأصغر) أكبر للمصباح ذي المقاومة الأصغر؛ فيستنفد المصباح 100 W قدرة أكبر ويكون سطوعه أكبر.', '["","المقاومة الأكبر تستنفد قدرة أكبر عند تساوي التيار (توالٍ)، أما عند تساوي الجهد فالمقاومة الأصغر تستنفد قدرة أكبر.","تساوي الجهد لا يعني تساوي القدرة؛ فالتيار في المصباح ذي المقاومة الأصغر أكبر.","النتيجة صحيحة لكن التعليل خاطئ؛ فالتيار لا يكون نفسه في فرعي التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-27T21:51:39.386Z"}'::jsonb),
('mcq', 3, 3, 'في التوالي يكون التيار المار في المصباحين متساويًا، ولأن مقاومة المصباح 60 W (240 Ω) أكبر من مقاومة المصباح 100 W (144 Ω) فإن القدرة المستنفدة فيه $\mathrm{P} = \mathrm{I}^2\mathrm{R}$ أكبر؛ أي أن سطوع المصباح 60 W سيكون أكبر.', '["القدرة المكتوبة على المصباح هي قدرته عند جهده المقرر فقط، وفي التوالي لا يعمل أي منهما على 120 V.","تساوي التيار لا يعني تساوي القدرة؛ فالقدرة $\\mathrm{I}^2\\mathrm{R}$ تعتمد على المقاومة أيضًا.","في دائرة التوالي يمر التيار نفسه في المصباحين، فلا يمر في أحدهما تيار أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-27T21:51:39.388Z"}'::jsonb),
('mcq', 4, 2, '$\mathrm{I} = \frac{120\ \text{V}}{240\ \Omega + 144\ \Omega} = 0.3125\ \text{A}$، و$\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.3125\ \text{A})^2(240\ \Omega) = 23\ \text{W}$؛ وهي أكبر من قدرة المصباح الآخر (14 W) فسطوعه أكبر، وكلاهما أقل من قدرته المقررة.', '["هذه القدرة المستنفدة في المصباح 144 Ω لا في المصباح 240 Ω.","هذه قدرته المقررة عند 120 V، وفي التوالي يكون الجهد بين طرفيه أقل من 120 V.","","هذه القدرة الكلية للدائرة $\\frac{(120)^2}{384}$ لا قدرة المصباح وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.388Z"}'::jsonb),
('mcq', 5, 0, 'جهد فرع $\mathrm{L}_1$ يساوي جهد البطارية كله، أما $\mathrm{L}_2$ و$\mathrm{L}_3$ فيقتسمان الجهد نفسه على التوالي، فيمر فيهما نحو نصف تيار $\mathrm{L}_1$، فتكون القدرة $\mathrm{P} = \mathrm{I}^2\mathrm{R}$ في كل منهما نحو ربع قدرة $\mathrm{L}_1$؛ لذا $\mathrm{L}_1$ أكبرها سطوعًا، و$\mathrm{L}_2$ و$\mathrm{L}_3$ متساويان وأقل سطوعًا لأن التيار نفسه يمر فيهما.', '["","$\\mathrm{L}_2$ و$\\mathrm{L}_3$ على التوالي فيمر فيهما التيار نفسه ويتساوى سطوعهما؛ ولا يستهلك الأول التيار.","التيار في فرع $\\mathrm{L}_1$ أكبر من تيار الفرع الآخر لأن مقاومة فرعه أصغر، فلا تتساوى القدرات.","عكس الترتيب: فرع $\\mathrm{L}_2$ و$\\mathrm{L}_3$ مقاومته أكبر فيمر فيه تيار أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.388Z"}'::jsonb),
('mcq', 6, 3, 'التيار متساوٍ في التوالي، فـ $\frac{\mathrm{P}_\mathrm{Y}}{\mathrm{P}_\mathrm{X}} = \frac{\mathrm{I}^2\mathrm{R}_\mathrm{Y}}{\mathrm{I}^2\mathrm{R}_\mathrm{X}} = \frac{40}{20} = 2$؛ فالمقاومة الأكبر تستنفد قدرة أكبر.', '["هذه النسبة لو كانتا على التوازي (الجهد متساوٍ فـ $\\mathrm{P} = \\frac{\\mathrm{V}^2}{\\mathrm{R}}$).","ربّع نسبة المقاومتين، والتربيع يقع على التيار المتساوي لا على المقاومة.","تساوي التيار لا يعني تساوي القدرة لأن المقاومتين مختلفتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.388Z"}'::jsonb),
('mcq', 7, 0, 'في التوالي جهد كل مصباح $\frac{\mathrm{V}}{2}$ فقدرته $\frac{(\mathrm{V}/2)^2}{\mathrm{R}} = \frac{\mathrm{V}^2}{4\mathrm{R}}$؛ وفي التوازي جهد كل مصباح $\mathrm{V}$ فقدرته $\frac{\mathrm{V}^2}{\mathrm{R}}$؛ أي أربعة أمثالها، فيكون سطوعه أكبر (يتضاعف التيار و$\mathrm{P} = \mathrm{I}^2\mathrm{R}$).', '["","التيار يتضاعف فعلًا، لكن القدرة $\\mathrm{I}^2\\mathrm{R}$ تتناسب مع مربع التيار فتصبح أربعة أمثالها.","طريقة التوصيل تغير الجهد بين طرفي كل مصباح والتيار المار فيه، فتتغير القدرة.","تيار كل فرع في التوازي $\\frac{\\mathrm{V}}{\\mathrm{R}}$ وهو ضعف تيار التوالي لا نصفه؛ فالتيار الكلي هو الذي يتضاعف أربع مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.389Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\mathrm{R} = \frac{\mathrm{V}^2}{\mathrm{P}}$: $\mathrm{R}_{60} = \frac{(120)^2}{60} = 240\ \Omega$، $\mathrm{R}_{100} = \frac{(120)^2}{100} = 144\ \Omega$. (b) على التوازي جهد كل منهما 120 V فيعمل كل منهما بقدرته المقررة: 60 W و100 W؛ فالمصباح 100 W أكثر سطوعًا. (c) $\mathrm{I} = \frac{120}{240 + 144} = 0.313\ \text{A}$؛ $\mathrm{P}_{60} = (0.3125)^2(240) = 23\ \text{W}$، $\mathrm{P}_{100} = (0.3125)^2(144) = 14\ \text{W}$؛ فالمصباح 60 W أكثر سطوعًا. (d) سطوع المصباح يتناسب طرديًّا مع القدرة المستنفدة. في التوازي يتساوى الجهد فتكون القدرة $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}}$ أكبر في المقاومة الأصغر (100 W). وفي التوالي يتساوى التيار فتكون $\mathrm{P} = \mathrm{I}^2\mathrm{R}$ أكبر في المقاومة الأكبر (60 W).', '["المقاومتان 240 Ω و144 Ω","في التوازي: 60 W و100 W، والأسطع 100 W","في التوالي: التيار 0.313 A، والقدرتان 23 W و14 W، والأسطع 60 W","التفسير بتساوي الجهد في التوازي وتساوي التيار في التوالي"]'::jsonb, '["$\\mathrm{R}_{60} = \\frac{14400}{60} = 240\\ \\Omega$، $\\mathrm{R}_{100} = \\frac{14400}{100} = 144\\ \\Omega$","توازٍ: $\\mathrm{P} = \\frac{\\mathrm{V}^2}{\\mathrm{R}}$ → 60 W و100 W","توالٍ: $\\mathrm{I} = \\frac{120}{384} = 0.3125\\ \\text{A}$","$\\mathrm{P}_{60} = 0.3125^2 \\times 240 = 23.4\\ \\text{W}$، $\\mathrm{P}_{100} = 0.3125^2 \\times 144 = 14.1\\ \\text{W}$"]'::jsonb, '[{"element":"حساب المقاومتين","marks":1},{"element":"حالة التوازي","marks":1},{"element":"حالة التوالي","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة في الحالتين مع تفسير صحيح."},{"level":"3–4 درجات","description":"حسابات صحيحة في حالة واحدة مع تفسير، أو حسابات كاملة دون تفسير."},{"level":"1–2 درجة","description":"حساب المقاومتين فقط أو حكم صحيح دون حسابات."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["افتراض أن المصباح ذا القدرة المكتوبة الأكبر أسطع دائمًا.","استعمال القدرة المقررة في حالة التوالي.","حساب التيار في التوالي بقسمة 120 V على مقاومة مصباح واحد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.389Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{L}_1$: جهده 6.0 V، $\mathrm{I}_1 = \frac{6.0}{12} = 0.50\ \text{A}$، $\mathrm{P}_1 = \mathrm{I}^2\mathrm{R} = (0.50)^2(12) = 3.0\ \text{W}$. $\mathrm{L}_2$ و$\mathrm{L}_3$ على التوالي: $\mathrm{I} = \frac{6.0}{24} = 0.25\ \text{A}$، والقدرة في كل منهما $(0.25)^2(12) = 0.75\ \text{W}$. الترتيب: $\mathrm{L}_1$ الأسطع، و$\mathrm{L}_2$ و$\mathrm{L}_3$ متساويان وأقل سطوعًا. (b) ينفتح فرع $\mathrm{L}_2$ و$\mathrm{L}_3$ فينطفئ $\mathrm{L}_2$، ويبقى سطوع $\mathrm{L}_1$ كما هو لأن جهد فرعه لم يتغير. (c) توصيل المصابيح الثلاثة جميعها على التوازي، فيكون فرق الجهد بين طرفي كل منها متساويًا (جهد البطارية)؛ أو توصيلها جميعها على التوالي، فيمر فيها التيار نفسه. وفي الحالتين تتساوى القدرة المستنفدة في المصابيح لتماثل مقاوماتها، فيتساوى سطوعها.', '["تيار $\\mathrm{L}_1$ 0.50 A وقدرته 3.0 W","تيار $\\mathrm{L}_2$ و$\\mathrm{L}_3$ 0.25 A وقدرة كل منهما 0.75 W","الترتيب الصحيح","أثر انقطاع $\\mathrm{L}_3$: ينطفئ $\\mathrm{L}_2$ ويبقى $\\mathrm{L}_1$","اقتراح توصيل المصابيح كلها على التوازي أو كلها على التوالي مع التعليل"]'::jsonb, '["$\\mathrm{I}_1 = \\frac{6.0}{12} = 0.50\\ \\text{A}$، $\\mathrm{P}_1 = 0.50^2 \\times 12 = 3.0\\ \\text{W}$","$\\mathrm{I}_{2} = \\mathrm{I}_{3} = \\frac{6.0}{12 + 12} = 0.25\\ \\text{A}$","$\\mathrm{P}_2 = \\mathrm{P}_3 = 0.25^2 \\times 12 = 0.75\\ \\text{W}$"]'::jsonb, '[{"element":"حسابات القدرة","marks":2},{"element":"الترتيب","marks":1},{"element":"أثر انقطاع $\\mathrm{L}_3$","marks":1},{"element":"الاقتراح والتعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة."},{"level":"3–4 درجات","description":"حسابات وترتيب صحيحان مع خطأ في (b) أو (c)."},{"level":"1–2 درجة","description":"ترتيب صحيح دون حسابات أو حساب واحد."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["جعل $\\mathrm{L}_2$ أسطع من $\\mathrm{L}_3$ لأنه أقرب إلى القطب الموجب.","القول إن $\\mathrm{L}_1$ يزداد سطوعًا عند انقطاع $\\mathrm{L}_3$.","حساب تيار الفرع الثاني بقسمة الجهد على مقاومة مصباح واحد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.389Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المقاومتان: $\mathrm{R}_{40} = \frac{(220)^2}{40} = 1210\ \Omega$، $\mathrm{R}_{100} = \frac{(220)^2}{100} = 484\ \Omega$. على التوالي: $\mathrm{I} = \frac{220}{1210 + 484} = 0.130\ \text{A}$، $\mathrm{P}_{40} = (0.130)^2(1210) = 20\ \text{W}$، $\mathrm{P}_{100} = (0.130)^2(484) = 8.2\ \text{W}$؛ فالمصباح 40 W أشد سطوعًا. إذن العبارة غير صحيحة على إطلاقها: القدرة المكتوبة هي القدرة عند الجهد المقرر فقط. وتصح العبارة عندما يعمل كل مصباح على جهده المقرر، كأن يوصلا على التوازي بمصدر 220 V، إذ يتساوى الجهد فتكون $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}}$ أكبر للمقاومة الأصغر (100 W). أما في التوالي فالتيار متساوٍ و$\mathrm{P} = \mathrm{I}^2\mathrm{R}$ أكبر للمقاومة الأكبر.', '["المقاومتان 1210 Ω و484 Ω","التيار 0.130 A في التوالي","القدرتان نحو 20 W و8.2 W والأسطع 40 W","الحكم بخطأ التعميم وتحديد حالة التوازي (الجهد المقرر)"]'::jsonb, '["$\\mathrm{R}_{40} = \\frac{48400}{40} = 1210\\ \\Omega$، $\\mathrm{R}_{100} = \\frac{48400}{100} = 484\\ \\Omega$","$\\mathrm{I} = \\frac{220}{1694} = 0.130\\ \\text{A}$","$\\mathrm{P}_{40} = 0.130^2 \\times 1210 = 20\\ \\text{W}$","$\\mathrm{P}_{100} = 0.130^2 \\times 484 = 8.2\\ \\text{W}$"]'::jsonb, '[{"element":"حساب المقاومتين","marks":1},{"element":"حساب التيار والقدرتين","marks":2},{"element":"الحكم المعلَّل وحالة صحة العبارة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة مع حكم معلَّل وتحديد الحالة."},{"level":"3–4 درجات","description":"حسابات صحيحة مع حكم دون تحديد الحالة أو العكس."},{"level":"1–2 درجة","description":"حكم صحيح دون حسابات، أو حساب المقاومتين فقط."},{"level":"صفر","description":"لا إجابة أو تأييد العبارة."}]'::jsonb, '["تأييد العبارة دون النظر إلى طريقة التوصيل.","استعمال القدرة المقررة 40 W و100 W في دائرة التوالي.","الخلط بين $\\mathrm{P} = \\mathrm{I}^2\\mathrm{R}$ و$\\mathrm{P} = \\frac{\\mathrm{V}^2}{\\mathrm{R}}$ في تحديد الأسطع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.390Z"}'::jsonb)
