from (values
('mcq', 1, 3, '$\mathrm{I} = \frac{9.0\ \text{V}}{6.0\ \Omega + 12\ \Omega} = 0.50\ \text{A}$، و$\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.50\ \text{A})^2(12\ \Omega) = 3.0\ \text{W}$.', '["هذه القدرة المستنفدة في المقاومة 6.0 Ω لا في 12 Ω.","هذه القدرة الكلية للدائرة $\\mathrm{I}\\mathrm{V} = (0.50)(9.0)$ لا قدرة المقاومة 12 Ω.","استعمل $\\frac{\\mathrm{V}^2}{\\mathrm{R}}$ بجهد البطارية كله (9.0 V)، والجهد بين طرفي المقاومة 12 Ω هو 6.0 V فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-27T21:51:39.390Z"}'::jsonb),
('mcq', 2, 0, 'جهد كل فرع 12.0 V: $\mathrm{P}_{20} = \frac{(12.0)^2}{20.0} = 7.20\ \text{W}$، $\mathrm{P}_{30} = \frac{(12.0)^2}{30.0} = 4.80\ \text{W}$، والقدرة الكلية $= 7.20 + 4.80 = 12.0\ \text{W}$ (أو $\frac{\mathrm{V}^2}{\mathrm{R}}$ مع $\mathrm{R} = 12.0\ \Omega$).', '["","عامل المقاومتين كأنهما على التوالي ($\\frac{(12.0)^2}{50.0}$).","هذه قدرة المقاومة 20.0 Ω وحدها.","هذه قدرة المقاومة 30.0 Ω وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-27T21:51:39.390Z"}'::jsonb),
('mcq', 3, 1, 'التيار نفسه 0.30 A يمر في المقاومتين على التوالي، فـ $\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.30\ \text{A})^2(18\ \Omega) = 1.6\ \text{W}$.', '["هذه القدرة المستنفدة في المقاومة 12 Ω.","","هذه القدرة الكلية في المقاومتين معًا $(0.30)^2(30)$.","حسب $\\mathrm{I}\\mathrm{R}$ (وهو الهبوط في الجهد 5.4 V) ونسي تربيع التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.391Z"}'::jsonb),
('mcq', 4, 2, '$\frac{1}{\mathrm{R}} = \frac{1}{10} + \frac{1}{40}$ فـ $\mathrm{R} = 8.0\ \Omega$، وجهد كل فرع $\mathrm{V} = \mathrm{I}\mathrm{R} = (1.0\ \text{A})(8.0\ \Omega) = 8.0\ \text{V}$، والقدرة في المقاومة 40 Ω: $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}} = \frac{(8.0)^2}{40} = 1.6\ \text{W}$ (تيارها 0.20 A).', '["استعمل التيار الكلي 1.0 A في $\\mathrm{I}^2\\mathrm{R}$، مع أن الذي يمر في المقاومة 40 Ω جزء منه فقط.","هذه القدرة المستنفدة في المقاومة 10 Ω (تيارها 0.80 A).","","هذه القدرة الكلية في المقاومتين معًا $(1.0)^2(8.0)$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.391Z"}'::jsonb),
('mcq', 5, 1, 'أقصى تيار آمن لكل مقاومة: $\mathrm{I} = \sqrt{\frac{\mathrm{P}}{\mathrm{R}}} = \sqrt{\frac{2.0}{100}} = 0.141\ \text{A}$، وهو نفسه في المقاومات الثلاث، فالجهد الأعظم الآمن $\mathrm{V} = \mathrm{I}\mathrm{R} = (0.141\ \text{A})(300\ \Omega) = 42\ \text{V}$، والقدرة الكلية عندئذٍ 6.0 W.', '["هذا الجهد الآمن لمقاومة واحدة $\\sqrt{(2.0)(100)}$، والمجموعة ثلاث مقاومات على التوالي.","","هذه القدرة الكلية العظمى (6.0 W) كُتبت بوحدة الجهد.","ضرب القدرة في المقاومة المكافئة $(2.0)(300)$ ولم يأخذ الجذر التربيعي ($\\mathrm{V}^2 = \\mathrm{P}\\mathrm{R}$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-27T21:51:39.391Z"}'::jsonb),
('mcq', 6, 3, 'التيار نفسه يمر في الثلاث، وأقل تيار آمن هو للمقاومة الكبرى: $\mathrm{I} = \sqrt{\frac{2.0}{400}} = 0.0707\ \text{A}$؛ فهو الذي يحدد الحد. $\mathrm{V} = \mathrm{I}\mathrm{R} = (0.0707\ \text{A})(700\ \Omega) = 49\ \text{V}$، وعندئذٍ تعمل المقاومة 400 Ω بقدرتها العظمى وتستنفد الأخريان قدرة أقل.', '["حدد التيار بالمقاومة الصغرى ($\\sqrt{\\frac{2.0}{100}} = 0.141\\ \\text{A}$)، فتتجاوز المقاومتان 200 Ω و400 Ω قدرتيهما.","جمع الجهود العظمى لكل مقاومة منفردة (14 + 20 + 28)، مع أن التيار مشترك فلا تبلغ كلها حدها معًا.","هذا الجهد الأعظم بين طرفي المقاومة 400 Ω وحدها، لا بين طرفي المجموعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-27T21:51:39.391Z"}'::jsonb),
('mcq', 7, 1, 'الجهد نفسه على المقاومتين، وأقل جهد آمن هو للمقاومة الصغرى: $\mathrm{V} = \sqrt{\mathrm{P}\mathrm{R}} = \sqrt{(2.0)(50)} = 10\ \text{V}$. عند هذا الجهد: $\mathrm{P}_{50} = 2.0\ \text{W}$، $\mathrm{P}_{200} = \frac{(10)^2}{200} = 0.50\ \text{W}$، فالقدرة العظمى الآمنة $= 2.5\ \text{W}$.', '["جمع القدرتين العظميين، لكن المقاومتين لا تبلغان حدهما معًا لأن الجهد مشترك.","","أخذ قدرة المقاومة 50 Ω وحدها ونسي قدرة المقاومة 200 Ω عند الجهد نفسه.","حدد الجهد بالمقاومة الكبرى (20 V)، فتستنفد المقاومة 50 Ω عندئذٍ 8.0 W وتتلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.391Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\mathrm{R} = 20.0 + 60.0 = 80.0\ \Omega$، $\mathrm{I} = \frac{24.0\ \text{V}}{80.0\ \Omega} = 0.300\ \text{A}$، $\mathrm{V}_\mathrm{A} = (0.300)(20.0) = 6.00\ \text{V}$، $\mathrm{V}_\mathrm{B} = (0.300)(60.0) = 18.0\ \text{V}$. (b) $\mathrm{P}_\mathrm{A} = \mathrm{I}^2\mathrm{R}_\mathrm{A} = (0.300)^2(20.0) = 1.80\ \text{W}$، $\mathrm{P}_\mathrm{B} = (0.300)^2(60.0) = 5.40\ \text{W}$. (c) $\mathrm{P} = \mathrm{I}\mathrm{V} = (0.300\ \text{A})(24.0\ \text{V}) = 7.20\ \text{W}$، و$1.80 + 5.40 = 7.20\ \text{W}$؛ فمجموع القدرتين يساوي القدرة الكلية.', '["التيار 0.300 A","الهبوطان 6.00 V و18.0 V","القدرتان 1.80 W و5.40 W","القدرة الكلية 7.20 W والتحقق"]'::jsonb, '["$\\mathrm{I} = \\frac{24.0}{80.0} = 0.300\\ \\text{A}$","$\\mathrm{V}_\\mathrm{A} = 6.00\\ \\text{V}$، $\\mathrm{V}_\\mathrm{B} = 18.0\\ \\text{V}$","$\\mathrm{P}_\\mathrm{A} = 0.300^2 \\times 20.0 = 1.80\\ \\text{W}$، $\\mathrm{P}_\\mathrm{B} = 0.300^2 \\times 60.0 = 5.40\\ \\text{W}$","$\\mathrm{P} = 0.300 \\times 24.0 = 7.20\\ \\text{W} = 1.80 + 5.40$"]'::jsonb, '[{"element":"التيار والهبوطان","marks":1},{"element":"القدرتان","marks":2},{"element":"القدرة الكلية والتحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بوحداتها مع التحقق."},{"level":"2–3 درجات","description":"خطأ في حساب واحد أو دون التحقق."},{"level":"1 درجة","description":"التيار فقط صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["حساب قدرة كل مقاومة بـ $\\frac{\\mathrm{V}^2}{\\mathrm{R}}$ بجهد البطارية كله.","نسيان تربيع التيار.","حساب القدرة الكلية بقسمة الجهد على المقاومة فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.392Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{I}_{30} = \frac{18.0}{30.0} = 0.600\ \text{A}$ و$\mathrm{P} = \mathrm{I}\mathrm{V} = 10.8\ \text{W}$؛ $\mathrm{I}_{60} = 0.300\ \text{A}$ و$\mathrm{P} = 5.40\ \text{W}$؛ $\mathrm{I}_{20} = 0.900\ \text{A}$ و$\mathrm{P} = 16.2\ \text{W}$. (b) $\frac{1}{\mathrm{R}} = \frac{1}{30.0} + \frac{1}{60.0} + \frac{1}{20.0} = \frac{1}{10.0}$، $\mathrm{R} = 10.0\ \Omega$. الطريقة الأولى: $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}} = \frac{(18.0)^2}{10.0} = 32.4\ \text{W}$؛ الطريقة الثانية: $10.8 + 5.40 + 16.2 = 32.4\ \text{W}$. (c) المقاومة 20.0 Ω أسخن، لأن الجهد متساوٍ على المقاومات فتكون $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}}$ أكبر للمقاومة الأصغر (16.2 W).', '["التيارات 0.600 A و0.300 A و0.900 A","القدرات 10.8 W و5.40 W و16.2 W","المقاومة المكافئة 10.0 Ω والقدرة الكلية 32.4 W بطريقتين","المقاومة 20.0 Ω أسخن مع التعليل"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}}$ لكل فرع: 0.600 و0.300 و0.900 A","$\\mathrm{P} = \\mathrm{I}\\mathrm{V}$: 10.8 و5.40 و16.2 W","$\\mathrm{R} = 10.0\\ \\Omega$","$\\mathrm{P} = \\frac{18.0^2}{10.0} = 32.4\\ \\text{W}$"]'::jsonb, '[{"element":"التيارات والقدرات","marks":2},{"element":"المقاومة المكافئة والقدرة الكلية بطريقتين","marks":2},{"element":"تحديد الأسخن مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة."},{"level":"3–4 درجات","description":"خطأ في طريقة واحدة أو تعليل ناقص."},{"level":"1–2 درجة","description":"تيارات الفروع فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["اختيار المقاومة الأكبر (60.0 Ω) على أنها الأسخن قياسًا على التوالي.","جمع المقاومات لحساب المقاومة المكافئة.","نسيان قلب مجموع المقلوبات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.392Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) التوالي: التيار مشترك، وأصغر تيار آمن للمقاومة الكبرى $\mathrm{I} = \sqrt{\frac{2.0}{200}} = 0.10\ \text{A}$؛ $\mathrm{V} = (0.10)(350) = 35\ \text{V}$، و$\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.10)^2(350) = 3.5\ \text{W}$. (b) التوازي: الجهد مشترك، وأصغر جهد آمن للمقاومة الصغرى $\mathrm{V} = \sqrt{(2.0)(50)} = 10\ \text{V}$؛ والقدرة $\frac{100}{50} + \frac{100}{100} + \frac{100}{200} = 2.0 + 1.0 + 0.50 = 3.5\ \text{W}$. (c) في التوالي تبلغ المقاومة 200 Ω حدها أولًا فيتوقف رفع الجهد قبل أن تبلغ الأخريان حديهما؛ وفي التوازي تبلغ المقاومة 50 Ω حدها أولًا. ولا تبلغ المقاومات الثلاث قدرتها العظمى معًا إلا إذا كانت متماثلة؛ لذا تكون القدرة العظمى الآمنة أقل من 6.0 W.', '["توالٍ: 0.10 A و35 V و3.5 W","توازٍ: 10 V و3.5 W","تحديد المقاومة التي تحدد الحد في كل حالة","التفسير بعدم بلوغ المقاومات حدودها معًا"]'::jsonb, '["توالٍ: $\\mathrm{I}_{\\max} = \\sqrt{\\frac{2.0}{200}} = 0.10\\ \\text{A}$","$\\mathrm{V} = 0.10 \\times 350 = 35\\ \\text{V}$، $\\mathrm{P} = 0.10^2 \\times 350 = 3.5\\ \\text{W}$","توازٍ: $\\mathrm{V}_{\\max} = \\sqrt{2.0 \\times 50} = 10\\ \\text{V}$","$\\mathrm{P} = 2.0 + 1.0 + 0.50 = 3.5\\ \\text{W}$"]'::jsonb, '[{"element":"حالة التوالي","marks":2},{"element":"حالة التوازي","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة في الحالتين مع تفسير."},{"level":"3–4 درجات","description":"حالة واحدة صحيحة كاملة مع جزء من الأخرى أو دون تفسير."},{"level":"1–2 درجة","description":"تحديد التيار أو الجهد الأعظم لمقاومة واحدة فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["تحديد تيار التوالي بالمقاومة الصغرى.","تحديد جهد التوازي بالمقاومة الكبرى.","جمع القدرات العظمى (6.0 W) دون تحقق."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.392Z"}'::jsonb)
