from (values
('mcq', 1, 'في تجربة لاستقصاء دائرة التوالي، رُكّبت الدائرة الآتية، ثم نُقل الأميتر إلى مواقع أخرى في الدائرة: بين المصباحين، ثم بعد المصباح $\mathrm{L}_2$. إذا كانت قراءته في موضعه الأول 150 mA، فماذا يُتوقع أن تكون قراءته في الموضعين الآخرين؟', null, '[{"src":"qimg/phys32/c2l1-o15-series.svg","alt":"دائرة تجربة التوالي: مصدر قدرة (رمز بطارية) على الضلع الأيسر قطبه الموجب أعلى، وأميتر A على السلك العلوي بعده مباشرة، ثم المصباح L1 على السلك العلوي، ثم المصباح L2 على الضلع الأيمن، والسلك السفلي يعود إلى المصدر. فولتمتر V موصول بسلكين بين طرفي المصباح L1."}]'::jsonb, '["150 mA في كل موضع","أقل من 150 mA بعد كل مصباح","75 mA في كل موضع","أكبر من 150 mA بعد كل مصباح"]'::jsonb, 'فهم', 'تنبؤ بنتيجة تجربة', 'سهل', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (الخطوة 6)'),
('mcq', 2, 'يبين الجدول الآتي قياسات طالب في دائرة توالٍ فيها مصباحان. ما المقاومة المكافئة للمصباحين؟', '{"headers":["موضع القياس في دائرة التوالي","التيار الكهربائي (mA)","فرق الجهد (V)"],"rows":[["بين طرفي النظام المكوّن من المصباحين","150","6.0"],["بين طرفي المصباح $\\mathrm{L}_1$","150","2.4"],["بين طرفي المصباح $\\mathrm{L}_2$","150","3.6"]]}'::jsonb, null, '["$0.040\\ \\Omega$","$16\\ \\Omega$","$40\\ \\Omega$","$9.0\\times10^{2}\\ \\Omega$"]'::jsonb, 'تطبيق', 'تحليل بيانات', 'سهل', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 1)'),
('mcq', 3, 'اعتمادًا على بيانات الجدول الآتي من دائرة توالٍ فيها مصباحان، أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["موضع القياس في دائرة التوالي","التيار الكهربائي (mA)","فرق الجهد (V)"],"rows":[["بين طرفي النظام المكوّن من المصباحين","150","6.0"],["بين طرفي المصباح $\\mathrm{L}_1$","150","2.4"],["بين طرفي المصباح $\\mathrm{L}_2$","150","3.6"]]}'::jsonb, null, '["فرق الجهد متساوٍ على المصباحين ويساوي فرق جهد النظام","مجموع فرقي الجهد على المصباحين يساوي فرق جهد النظام","المصباح $\\mathrm{L}_2$ يمر فيه تيار أكبر لأن فرق جهده أكبر","فرق الجهد على كل مصباح يتناسب عكسيًّا مع مقاومته"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 4)'),
('mcq', 4, 'رُكّب المصباحان نفسهما على التوازي كما في الشكل الآتي، وسجّل طالب البيانات في الجدول. أيّ الاستنتاجات الآتية تدعمه هذه البيانات؟', '{"headers":["الحالة في دائرة التوازي","قراءة الأميتر (mA)","قراءة الفولتمتر (V)"],"rows":[["المصباحان موصولان","305","3.0"],["بعد فصل $\\mathrm{L}_2$ (يعمل $\\mathrm{L}_1$ وحده)","170","3.0"],["بعد إعادة $\\mathrm{L}_2$ وفصل $\\mathrm{L}_1$","135","3.0"]]}'::jsonb, '[{"src":"qimg/phys32/c2l1-o15-parallel.svg","alt":"دائرة تجربة التوازي: مصدر قدرة (رمز بطارية) على الضلع الأيسر قطبه الموجب أعلى، وأميتر A على السلك العلوي قبل نقاط التفرع. بين السلك العلوي والسلك السفلي فرعان على التوازي: الأوسط فيه المصباح L1، والأيمن فيه المصباح L2. فولتمتر V موصول بسلكين بين طرفي المصباح L1."}]'::jsonb, '["التيار متساوٍ في المصباحين، وفرق الجهد يتوزع بينهما","التيار الكلي يساوي تيار المصباح الأكبر، وفرق الجهد يتوزع بينهما","التيار الكلي يساوي مجموع تياري المصباحين، وفرق الجهد نفسه على كل منهما","فرق الجهد يقل كلما زاد عدد المصابيح الموصولة"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (الخطوات 8–11)'),
('mcq', 5, 'في التجربة، فصل طالب أحد المصباحين من قاعدته مرة في دائرة التوالي ومرة في دائرة التوازي. أيّ العبارات الآتية تصف ملاحظاته؟', null, null, '["في التوالي يزداد سطوع المصباح الآخر، وفي التوازي ينطفئ","في الدائرتين ينطفئ المصباح الآخر، وتصبح قراءة الأميتر صفرًا","في الدائرتين يبقى المصباح الآخر مضيئًا، ولا تتغير قراءة الأميتر","في التوالي ينطفئ الآخر وتصبح قراءة الأميتر صفرًا، وفي التوازي يبقى مضيئًا وتقل قراءة الأميتر"]'::jsonb, 'تحليل', 'مقارنة نتائج تجربة', 'صعب', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (الخطوتان 3 و10)'),
('mcq', 6, 'اعتمادًا على بيانات الجدول الآتي من دائرة التوازي، ما مقدار مقاومة المصباح $\mathrm{L}_1$ في هذه الدائرة؟', '{"headers":["الحالة في دائرة التوازي","قراءة الأميتر (mA)","قراءة الفولتمتر (V)"],"rows":[["المصباحان موصولان","305","3.0"],["بعد فصل $\\mathrm{L}_2$ (يعمل $\\mathrm{L}_1$ وحده)","170","3.0"],["بعد إعادة $\\mathrm{L}_2$ وفصل $\\mathrm{L}_1$","135","3.0"]]}'::jsonb, null, '["$0.018\\ \\Omega$","$9.8\\ \\Omega$","$22\\ \\Omega$","$18\\ \\Omega$"]'::jsonb, 'تطبيق', 'تحليل بيانات', 'سهل', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 5)'),
('mcq', 7, 'حسب طالب مقاومة المصباح $\mathrm{L}_1$ من بياناته فوجدها 16 Ω في دائرة التوالي (فرق الجهد بين طرفيه 2.4 V) و18 Ω في دائرة التوازي (فرق الجهد بين طرفيه 3.0 V). ما التفسير الأرجح لهذا الاختلاف؟', null, null, '["مقاومة المصباح تعتمد على طريقة توصيله، فهي في التوازي أكبر دائمًا","الفولتمتر الموصول على التوازي يزيد مقاومة المصباح","فتيل المصباح أسخن عند الجهد الأكبر، ومقاومة الفلز تزداد بارتفاع درجة حرارته","أخطأ الطالب في القراءة؛ لأن مقاومة أي مصباح ثابتة لا تتغير"]'::jsonb, 'تحليل', 'تفسير نتائج', 'صعب', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 5)؛ ص 16–17 مقاومة المصباح تعتمد على درجة حرارته'),
('essay', 1, 'صمّم الجزء الخاص بدائرة التوالي من تجربة تستقصي العلاقة بين التيار وفرق الجهد والمقاومة، مستخدمًا: مصدر قدرة قليل الجهد، ومصباحين صغيرين في قاعدتين، وأميترًا (0–500 mA)، وفولتمترًا (0–30 V)، وأسلاك توصيل. ارسم مخطط الدائرة، واكتب خطوات القياس، والنتائج المتوقعة، واحتياطًا واحدًا للسلامة.', null, null, null, 'إبداع', 'تصميم تجربة', 'متوسط', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (الخطوات 1–6)'),
('essay', 2, 'يبين الجدول الآتي نتائج طالب في دائرة توالٍ فيها مصباحان. (a) احسب المقاومة المكافئة للمصباحين، ومقاومة كل مصباح. (b) ما العلاقة بين المقاومة المكافئة ومقاومتي المصباحين؟ (c) ما العلاقة بين فرق الجهد على كل مصباح وفرق جهد النظام؟ (d) لخّص العلاقة بين التيار وفرق الجهد والمقاومة في دائرة التوالي.', '{"headers":["موضع القياس في دائرة التوالي","التيار الكهربائي (mA)","فرق الجهد (V)"],"rows":[["بين طرفي النظام المكوّن من المصباحين","150","6.0"],["بين طرفي المصباح $\\mathrm{L}_1$","150","2.4"],["بين طرفي المصباح $\\mathrm{L}_2$","150","3.6"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 1–4 والاستنتاج 1)'),
('essay', 3, 'يبين الجدول الآتي نتائج الطالب نفسه بعد توصيل المصباحين على التوازي. (a) احسب مقاومة كل مصباح، والمقاومة المكافئة للمصباحين من قراءتي الأميتر والفولتمتر، ثم تحقق منها بالعلاقة $\frac{1}{\mathrm{R}} = \frac{1}{\mathrm{R}_1} + \frac{1}{\mathrm{R}_2}$. (b) لخّص العلاقة بين التيار وفرق الجهد في دائرة التوازي، وقارنها بدائرة التوالي. (c) تعمل مصابيح المنزل على جهد 120 V مهما كان عددها؛ وضّح كيف تتأثر هذه الخاصية بطريقة التوصيل، ولماذا توصل المصابيح في المنازل على التوازي.', '{"headers":["الحالة في دائرة التوازي","قراءة الأميتر (mA)","قراءة الفولتمتر (V)"],"rows":[["المصباحان موصولان","305","3.0"],["بعد فصل $\\mathrm{L}_2$ (يعمل $\\mathrm{L}_1$ وحده)","170","3.0"],["بعد إعادة $\\mathrm{L}_2$ وفصل $\\mathrm{L}_1$","135","3.0"]]}'::jsonb, null, null, 'تقويم', 'تحليل بيانات ومقارنة', 'صعب', 'الكتاب ص 58–59 — مختبر الفيزياء: دوائر التوالي والتوازي الكهربائية (التحليل 5، الاستنتاج 2، الفيزياء في الحياة 1)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
