select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'للتيار في دائرة التوالي مسار واحد، والشحنة لا تفنى ولا تُستحدث؛ فالتيار هو نفسه في أي جزء منها، وتكون قراءات الأميتر في المواقع المختلفة متساوية: 150 mA في كل موضع.', '["","المصباح لا يستهلك التيار؛ بل يتحول فيه جزء من الطاقة الكهربائية، ويبقى التيار نفسه.","التيار لا يتوزع على المصباحين في التوالي؛ فالتوزيع يحدث في فروع دائرة التوازي.","لا يوجد مصدر بين المصباحين يزيد التيار، والتيار متساوٍ في جميع الأجزاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.394Z"}'::jsonb),
('mcq', 2, 2, '$\mathrm{R} = \frac{\mathrm{V}}{\mathrm{I}} = \frac{6.0\ \text{V}}{0.150\ \text{A}} = 40\ \Omega$، وهي تساوي مجموع مقاومتي المصباحين $\frac{2.4}{0.150} + \frac{3.6}{0.150} = 16 + 24 = 40\ \Omega$.', '["قسم على التيار بوحدة mA (150) دون تحويله إلى أمبير.","هذه مقاومة المصباح $\\mathrm{L}_1$ وحده $\\frac{2.4}{0.150}$.","","ضرب الجهد في التيار ($6.0 \\times 150$) بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-27T21:51:39.394Z"}'::jsonb),
('mcq', 3, 1, 'فرق جهد النظام 6.0 V، و$2.4 + 3.6 = 6.0\ \text{V}$؛ أي أن مجموع فرقي الجهد على المصباحين يساوي فرق جهد النظام. ولأن التيار متساوٍ (150 mA) فالمصباح ذو المقاومة الأكبر ($\mathrm{L}_2$) عليه هبوط أكبر في الجهد.', '["البيانات تبين 2.4 V و3.6 V على المصباحين، وهما غير متساويين ولا يساوي أيٌّ منهما 6.0 V.","","التيار المسجل 150 mA في المواضع كلها؛ فالتيار متساوٍ في دائرة التوالي.","التيار متساوٍ، فالهبوط $\\mathrm{V} = \\mathrm{I}\\mathrm{R}$ يتناسب طرديًّا مع المقاومة لا عكسيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.394Z"}'::jsonb),
('mcq', 4, 2, 'قراءة الأميتر والمصباحان موصولان 305 mA، و$170 + 135 = 305\ \text{mA}$، فالتيار الكلي يساوي مجموع تياري المصباحين؛ وقراءة الفولتمتر 3.0 V في الحالات كلها، ففرق الجهد نفسه على كل منهما.', '["تيارا المصباحين 170 mA و135 mA غير متساويين، والجهد 3.0 V لكل منهما لا يتوزع.","التيار الكلي 305 mA أكبر من تيار أي مصباح وحده، والجهد لم يتوزع.","","قراءة الفولتمتر 3.0 V سواء عمل مصباح واحد أو اثنان؛ فلم يتغير فرق الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.394Z"}'::jsonb),
('mcq', 5, 3, 'في دائرة التوالي للتيار مسار واحد، ففصل مصباح يفتح الدائرة فينطفئ الآخر وتصبح قراءة الأميتر صفرًا. وفي دائرة التوازي فروع مستقلة، فيبقى المصباح الآخر مضيئًا بالسطوع نفسه، وتقل قراءة الأميتر في السلك الرئيس لأن تيار الفرع المفصول لم يعد يُضاف.', '["عكس النتيجتين: فصل مصباح في التوالي يفتح المسار الوحيد فينطفئ الآخر، أما في التوازي فيبقى الآخر مضيئًا.","فروع التوازي مستقلة، ففصل أحدها لا يقطع التيار عن الآخر.","في التوالي ينفتح المسار الوحيد فينعدم التيار، وفي التوازي تقل قراءة الأميتر الرئيس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.395Z"}'::jsonb),
('mcq', 6, 3, 'عندما يعمل $\mathrm{L}_1$ وحده يمر فيه 170 mA وفرق الجهد بين طرفيه 3.0 V، فـ $\mathrm{R} = \frac{3.0\ \text{V}}{0.170\ \text{A}} = 17.6 \approx 18\ \Omega$.', '["قسم على التيار بوحدة mA دون تحويله إلى أمبير.","قسم الجهد على التيار الكلي (305 mA)، فحسب المقاومة المكافئة للمصباحين لا مقاومة $\\mathrm{L}_1$.","هذه مقاومة المصباح $\\mathrm{L}_2$ $\\frac{3.0}{0.135}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.395Z"}'::jsonb),
('mcq', 7, 2, 'في دائرة التوازي فرق الجهد بين طرفي $\mathrm{L}_1$ أكبر (3.0 V بدل 2.4 V) فيمر فيه تيار أكبر ويسخن فتيله أكثر، ومقاومة الفلز تزداد بارتفاع درجة حرارته؛ فمقاومة المصباح تعتمد على درجة حرارته ولا يحقق قانون أوم؛ لذا كانت مقاومته 18 Ω في التوازي بدل 16 Ω في التوالي.', '["طريقة التوصيل وحدها لا تغير المقاومة؛ المؤثر هو درجة حرارة الفتيل التي تعتمد على الجهد والتيار.","الفولتمتر يُصمم بمقاومة كبيرة جدًّا ولا يغير مقاومة المصباح.","","مقاومة فتيل المصباح تتغير بتغير درجة حرارته، فالاختلاف متوقع وليس بالضرورة خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-27T21:51:39.395Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخطط: المصدر والأميتر والمصباحان $\mathrm{L}_1$ و$\mathrm{L}_2$ في مسار واحد (على التوالي)، مع مراعاة توصيل الطرف الموجب للأميتر بجهة الطرف الموجب للمصدر، والفولتمتر يوصل على التوازي. الخطوات: (1) أشغّل المصدر وأضبطه حتى تصبح إضاءة المصباحين خافتة، وأسجل قراءة الأميتر. (2) أصل الفولتمتر بين طرفي النظام المكوّن من المصباحين (موجبه بالطرف الموجب)، ثم بين طرفي كل مصباح، وأسجل القراءات. (3) أنقل الأميتر إلى مواقع مختلفة (بين المصباحين، وبعد $\mathrm{L}_2$) وأسجل قراءاته. (4) أفصل أحد المصباحين وألاحظ الآخر والأميتر. النتائج المتوقعة: قراءات الأميتر متساوية في جميع المواقع؛ ومجموع فرقي الجهد على المصباحين يساوي فرق جهد النظام؛ والمقاومة المكافئة $\frac{\mathrm{V}}{\mathrm{I}}$ تساوي مجموع مقاومتي المصباحين؛ وعند فصل مصباح ينطفئ الآخر وتصبح قراءة الأميتر صفرًا. السلامة: لا تُنفَّذ التجربة باستعمال تيار متناوب (من مقبس المنزل)، وتُمسك أطراف الأسلاك بحذر لأنها قد تكون حادة.', '["مخطط صحيح: أميتر على التوالي وفولتمتر على التوازي","خطوات قياس التيار في مواقع مختلفة","خطوات قياس فرق الجهد للنظام ولكل مصباح","النتائج المتوقعة (تساوي التيار، مجموع الجهود، المقاومة المكافئة)","احتياط سلامة"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط","marks":1},{"element":"خطوات القياس","marks":2},{"element":"النتائج المتوقعة","marks":1},{"element":"احتياط السلامة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم كامل صحيح بالمخطط والخطوات والنتائج والسلامة."},{"level":"3–4 درجات","description":"تصميم صحيح ينقصه عنصر واحد أو فيه خطأ في توصيل جهاز."},{"level":"1–2 درجة","description":"مخطط فقط أو خطوات ناقصة."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["توصيل الفولتمتر على التوالي أو الأميتر على التوازي.","توقع أن تقل قراءة الأميتر بعد كل مصباح.","إهمال قطبية الأميتر والفولتمتر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-27T21:51:39.396Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{R} = \frac{6.0\ \text{V}}{0.150\ \text{A}} = 40\ \Omega$؛ $\mathrm{R}_1 = \frac{2.4}{0.150} = 16\ \Omega$؛ $\mathrm{R}_2 = \frac{3.6}{0.150} = 24\ \Omega$. (b) $16 + 24 = 40\ \Omega$، فالمقاومة المكافئة تساوي مجموع مقاومتي المصباحين $\mathrm{R} = \mathrm{R}_1 + \mathrm{R}_2$. (c) $2.4 + 3.6 = 6.0\ \text{V}$، فمجموع فرقي الجهد على المصباحين يساوي فرق جهد النظام. (d) في دائرة التوالي: التيار نفسه في جميع الأجزاء؛ وفرق جهد المصدر يتوزع على المصابيح بنسبة مقاوماتها ($\mathrm{V} = \mathrm{I}\mathrm{R}$ لكل منها) ومجموعها يساوي جهد المصدر؛ والمقاومة المكافئة مجموع المقاومات، والتيار $\mathrm{I} = \frac{\mathrm{V}_{\text{مصدر}}}{\mathrm{R}}$.', '["المقاومة المكافئة 40 Ω","مقاومتا المصباحين 16 Ω و24 Ω","العلاقة $\\mathrm{R} = \\mathrm{R}_1 + \\mathrm{R}_2$","مجموع فرقي الجهد يساوي جهد النظام","تلخيص العلاقة في التوالي"]'::jsonb, '["$\\mathrm{R} = \\frac{6.0}{0.150} = 40\\ \\Omega$","$\\mathrm{R}_1 = \\frac{2.4}{0.150} = 16\\ \\Omega$، $\\mathrm{R}_2 = \\frac{3.6}{0.150} = 24\\ \\Omega$","$16 + 24 = 40\\ \\Omega$","$2.4 + 3.6 = 6.0\\ \\text{V}$"]'::jsonb, '[{"element":"الحسابات","marks":2},{"element":"علاقة المقاومات","marks":1},{"element":"علاقة الجهود","marks":1},{"element":"التلخيص","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة واستنتاجات صحيحة وتلخيص كامل."},{"level":"3–4 درجات","description":"حسابات صحيحة مع استنتاج ناقص."},{"level":"1–2 درجة","description":"حساب المقاومة المكافئة فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["القسمة على التيار بوحدة mA.","القول إن فرق الجهد متساوٍ على المصباحين.","حساب مقاومة كل مصباح بقسمة جهد النظام على التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-27T21:51:39.396Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $\mathrm{R}_1 = \frac{3.0}{0.170} = 18\ \Omega$ (17.6)، $\mathrm{R}_2 = \frac{3.0}{0.135} = 22\ \Omega$، والمقاومة المكافئة $\mathrm{R} = \frac{3.0}{0.305} = 9.8\ \Omega$؛ وللتحقق $\frac{1}{\mathrm{R}} = \frac{1}{17.6} + \frac{1}{22.2} = 0.102\ \Omega^{-1}$ فـ $\mathrm{R} = 9.8\ \Omega$، وهي أصغر من مقاومة أي مصباح. (b) في التوازي: فرق الجهد نفسه (3.0 V) على كل فرع ويساوي جهد المصدر، والتيار الكلي يساوي مجموع تياري الفرعين ($170 + 135 = 305\ \text{mA}$)، وتيار كل فرع $\frac{\mathrm{V}}{\mathrm{R}}$ لا يتأثر بالفرع الآخر. أما في التوالي فالتيار نفسه في الأجزاء، والجهد يتوزع عليها، والمقاومة المكافئة مجموع المقاومات. (c) في التوازي يبقى جهد كل مصباح 120 V مهما زاد عددها، فيعمل كل مصباح بقدرته المقررة ويمكن تشغيله أو إطفاؤه مستقلًا؛ أما في التوالي فيتوزع 120 V على المصابيح فيقل جهد كل منها وسطوعه بزيادة عددها، وإذا احترق أحدها انطفأت جميعها. لذا توصل المصابيح في المنازل على التوازي.', '["مقاومتا المصباحين نحو 18 Ω و22 Ω","المقاومة المكافئة 9.8 Ω والتحقق بالعلاقة","تلخيص علاقة التوازي ومقارنتها بالتوالي","تفسير ثبات جهد المصابيح في التوازي وسبب استعماله في المنازل"]'::jsonb, '["$\\mathrm{R}_1 = \\frac{3.0}{0.170} = 17.6\\ \\Omega$، $\\mathrm{R}_2 = \\frac{3.0}{0.135} = 22.2\\ \\Omega$","$\\mathrm{R} = \\frac{3.0}{0.305} = 9.8\\ \\Omega$","$\\frac{1}{17.6} + \\frac{1}{22.2} = 0.0568 + 0.0450 = 0.102$، $\\mathrm{R} = 9.8\\ \\Omega$"]'::jsonb, '[{"element":"الحسابات والتحقق","marks":2},{"element":"التلخيص والمقارنة","marks":2},{"element":"تطبيق المنزل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة."},{"level":"3–4 درجات","description":"حسابات صحيحة مع مقارنة ناقصة أو دون تطبيق المنزل."},{"level":"1–2 درجة","description":"حساب مقاومة مصباح واحد أو استنتاج واحد."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["جمع مقاومتي المصباحين للحصول على المقاومة المكافئة في التوازي.","القول إن الجهد يتوزع على المصابيح في التوازي.","حساب المقاومة المكافئة من تيار مصباح واحد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-27T21:51:39.396Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
