insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بدائرة القصر؟', null, null, '["دائرة كهربائية مقاومتها كبيرة جدًّا فيصبح التيار المار فيها صغيرًا جدًّا ولا تسخن أسلاكها","دائرة كهربائية مقاومتها صغيرة جدًّا فيصبح التيار المار فيها كبيرًا جدًّا","دائرة كهربائية مفتوحة لا يمر فيها أي تيار لانقطاع أحد أسلاكها","دائرة كهربائية قصيرة الأسلاك لا تحتوي إلا على جهاز كهربائي واحد"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 52 — أدوات السلامة (دائرة القصر)'),
('mcq', 2, 'ما اسم قطعة الفلز القصيرة التي تنصهر عندما يمرّ فيها تيار كبير فتقطع التيار الكهربائي عن الدائرة؟', null, null, '["قاطع الدائرة الكهربائية","قاطع التفريغ الأرضي الخاطئ","المقاومة المتغيرة","المنصهر الكهربائي"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 52 — أدوات السلامة (المنصهر الكهربائي)'),
('mcq', 3, 'بماذا يختلف تعريف قاطع الدائرة الكهربائية عن تعريف المنصهر الكهربائي؟', null, null, '["القاطع مفتاح آلي يفتح الدائرة عند تجاوز التيار القيمة المسموح بها، والمنصهر قطعة فلز تنصهر بمرور تيار كبير","المنصهر مفتاح آلي يعود إلى وضع الفتح عند ارتفاع التيار، أما القاطع فشريط فلزي ينصهر عند مرور تيار كبير","القاطع يكشف الفروق البسيطة بين تياري سلكي الجهاز، والمنصهر جهاز يقيس التيار الكلي المار في الدائرة","القاطع يوصل على التوازي مع الأجهزة ليحميها، والمنصهر يوصل على التوالي مع مصدر الجهد ليحميها"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 52 — أدوات السلامة (قاطع الدائرة الكهربائية)'),
('mcq', 4, 'أيّ أدوات السلامة الآتية يحتوي على دائرة إلكترونية تكشف الفروق البسيطة في التيار الكهربائي الناتجة عن مسار إضافي للتيار، كأن يمر جزء منه عبر جسم شخص؟', null, null, '["المنصهر الكهربائي","قاطع الدائرة الكهربائية","قاطع التفريغ الأرضي الخاطئ","الشريط الفلزي المزدوج"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'متوسط', 'الكتاب ص 52–53 — قاطع التفريغ الأرضي الخاطئ'),
('mcq', 5, 'ما الدائرة الكهربائية المركّبة؟', null, null, '["دائرة تحتوي على أكثر من بطارية موصولة معًا على التوالي","دائرة جميع مقاوماتها موصولة معًا على التوازي","دائرة تحتوي على نوعي التوصيل التوالي والتوازي معًا","دائرة تحتوي على أكثر من جهاز قياس كهربائي"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة'),
('mcq', 6, 'يبين الشكل الآتي أربع دوائر كهربائية مرقّمة. أيّ الدوائر يُعدّ دائرة كهربائية مركّبة؟', null, '[{"src":"qimg/phys32/c2l2-o01-kinds.svg","alt":"أربع دوائر مرقّمة، في كل منها بطارية على اليسار. الدائرة (1): مقاومتان في السلك العلوي ومقاومة ثالثة في السلك الأيمن، كلها في مسار واحد. الدائرة (2): ثلاث مقاومات رأسية موصولة بين السلك العلوي والسلك السفلي، كل منها في فرع مستقل. الدائرة (3): مقاومة واحدة في السلك العلوي، ثم نقطة تفرّع تخرج منها مقاومتان رأسيتان موصولتان بين السلكين العلوي والسفلي. الدائرة (4): أميتر ومقاومة في السلك العلوي ومقاومة في السلك الأيمن، كلها في مسار واحد."}]'::jsonb, '["الدائرة (1)","الدائرة (2)","الدائرة (4)","الدائرة (3)"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة'),
('mcq', 7, 'في الدائرة الآتية لامس سلكٌ طرفي المصباح مباشرة عند النقطتين X وY. ما الوصف الصحيح لما حدث؟', null, '[{"src":"qimg/phys32/c2l2-o01-short.svg","alt":"دائرة فيها بطارية جهدها 6.0 V على اليسار، يصل سلكها العلوي إلى مصباح موضوع رأسيًّا على اليمين، ويعود السلك السفلي من المصباح إلى البطارية. عند طرفي المصباح نقطتان X (أعلى) وY (أسفل)، وسلك إضافي يخرج من X إلى اليمين وينزل ويعود إلى Y دون أي عنصر فيه."}]'::jsonb, '["تكوّنت دائرة قصر؛ لأن السلك بين X وY مسار مقاومته صغيرة جدًّا، فيمر في الدائرة تيار كبير جدًّا","تكوّنت دائرة مفتوحة؛ لأن السلك قطع مسار التيار عند المصباح، فلا يمر تيار في أي جزء من الدائرة","تكوّنت دائرة قصر، لكن التيار في الدائرة يقل؛ لأن المقاومة الكلية أصبحت صغيرة جدًّا","ازداد سطوع المصباح؛ لأن السلك أضاف مسارًا جديدًا يزيد التيار المار في المصباح"]'::jsonb, 'فهم', 'تفسير موقف', 'صعب', 'الكتاب ص 52 — أدوات السلامة (دائرة القصر)'),
('essay', 1, 'عرّف كلًّا من المصطلحات الآتية: (a) دائرة القصر. (b) المنصهر الكهربائي. (c) قاطع الدائرة الكهربائية. (d) قاطع التفريغ الأرضي الخاطئ. (e) الدائرة الكهربائية المركّبة.', null, null, null, 'تذكر', 'تعريف مصطلحات', 'سهل', 'الكتاب ص 52–54 والمفردات ص 61'),
('essay', 2, 'ما المقصود بدائرة القصر؟ وكيف يمكن أن تتكوّن في سلكي مصباح منزلي؟ ولماذا تكون خطيرة؟ استعن بالحساب: إذا تلامس السلكان الموصولان بمصباح يعمل بجهد 120 V فنتجت مقاومة مقدارها 0.010 Ω تقريبًا، فما مقدار التيار؟', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 52–53 — دائرة القصر، والتقويم ص 62 السؤال 36'),
('essay', 3, 'سمِّ المصطلح الذي يصفه كل موقف مما يأتي، وبيّن السبب باختصار:
(a) قطعة فلزية رفيعة في علبة الكهرباء انصهرت حين شُغّلت أجهزة كثيرة معًا فانقطع التيار.
(b) تآكلت المادة العازلة لسلكين فتلامسا، فمر تيار كبير جدًّا.
(c) مقاومة صغيرة موصولة على التوالي مع مجموعة أجهزة موصولة معًا على التوازي.
(d) مفتاح آلي في علبة التوزيع انتقل إلى وضع الفتح عندما تجاوز التيار القيمة المسموح بها.
(e) أداة في مقبس الحمام فتحت الدائرة حين لمس شخص مبتلّ جهازًا معيبًا، مع أن التيار الكلي كان صغيرًا.', null, null, null, 'فهم', 'تطبيق المفهوم على مواقف', 'صعب', 'الكتاب ص 52–54 — أدوات السلامة والدوائر المركّبة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O01') and x.type = v.type and x.number = v.number);
