from (values
('mcq', 1, 1, 'تحدث دائرة القصر عند تكوّن دائرة كهربائية مقاومتها صغيرة جدًّا؛ مما يجعل التيار المار فيها كبيرًا جدًّا.', '["هذا عكس دائرة القصر؛ فمقاومتها صغيرة جدًّا وتيارها كبير جدًّا.","","الدائرة المفتوحة لا يمر فيها تيار، أما دائرة القصر فيمر فيها تيار كبير جدًّا.","كلمة «القصر» لا تعني قصر الأسلاك أو عدد الأجهزة، بل تكوّن مسار مقاومته صغيرة جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.397Z"}'::jsonb),
('mcq', 2, 3, 'المنصهر الكهربائي قطعة قصيرة من فلز تنصهر عندما يمرّ فيها تيار كبير، فتقطع التيار عن الدائرة وتحميها من التلف.', '["قاطع الدائرة مفتاح آلي يفتح الدائرة، ولا ينصهر.","قاطع التفريغ الأرضي الخاطئ يكشف الفروق البسيطة في التيار بدائرة إلكترونية، ولا ينصهر.","المقاومة المتغيرة تُستخدم للتحكم في التيار، وليست أداة سلامة تنصهر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.397Z"}'::jsonb),
('mcq', 3, 0, 'قاطع الدائرة الكهربائية مفتاح كهربائي آلي يعمل على فتح الدائرة عندما يتجاوز مقدار التيار المار فيها القيمة المسموح بها، أما المنصهر فقطعة قصيرة من فلز تنصهر عندما يمرّ فيها تيار كبير.', '["","هذا تبديل للتعريفين.","كشف الفروق البسيطة في التيار وظيفة قاطع التفريغ الأرضي الخاطئ، والمنصهر لا يقيس التيار.","القاطع مثل المنصهر يوصل بالجهاز على التوالي حتى يمر فيه تيار الجهاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.397Z"}'::jsonb),
('mcq', 4, 2, 'قاطع التفريغ الأرضي الخاطئ يحتوي على دائرة إلكترونية تكشف الفروق البسيطة في التيار الناتجة عن مسار إضافي للتيار، فيفتح الدائرة ويمنع الإصابة.', '["المنصهر لا ينصهر إلا عند مرور تيار كبير، ولا يكشف الفروق البسيطة.","قاطع الدائرة يفتحها عند تجاوز التيار القيمة المسموح بها، لا عند فرق بسيط بين تيارين.","","الشريط الفلزي المزدوج جزء من قاطع الدائرة يتقوّس بالتسخين عند مرور تيار كبير، وليس دائرة إلكترونية تكشف الفروق البسيطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-27T21:51:39.397Z"}'::jsonb),
('mcq', 5, 2, 'تسمى الدائرة التي تحتوي على نوعي التوصيل التوالي والتوازي معًا دائرة كهربائية مركّبة.', '["عدد البطاريات لا يحدد كون الدائرة مركّبة.","هذه دائرة توازٍ، لا تحتوي على توصيل توالٍ.","","عدد أجهزة القياس لا يحدد نوع الدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.398Z"}'::jsonb),
('mcq', 6, 3, 'في الدائرة (3) مقاومة في السلك الرئيس على التوالي مع مقاومتين موصولتين معًا على التوازي، فهي تحتوي على نوعي التوصيل معًا؛ لذا فهي دائرة مركّبة.', '["المقاومات الثلاث في الدائرة (1) في مسار واحد، فهي دائرة توالٍ فقط.","المقاومات الثلاث في الدائرة (2) كلها على التوازي، فهي دائرة توازٍ فقط.","الأميتر والمقاومتان في الدائرة (4) في مسار واحد، فهي دائرة توالٍ فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-27T21:51:39.398Z"}'::jsonb),
('mcq', 7, 0, 'السلك بين X وY مقاومته صغيرة جدًّا، فيتكوّن مسار مقاومته صغيرة جدًّا بين قطبي البطارية؛ وهذا هو تعريف دائرة القصر، ويصبح التيار المار فيها كبيرًا جدًّا.', '["","السلك لم يقطع المسار بل أضاف مسارًا مغلقًا جديدًا مقاومته صغيرة جدًّا، فيمر تيار كبير.","نقصان المقاومة الكلية يزيد التيار ولا يقلله.","يسلك التيار المسار ذا المقاومة الصغيرة جدًّا (السلك)، فلا يزداد تيار المصباح بل يكاد ينعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-27T21:51:39.398Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) دائرة القصر: دائرة كهربائية مقاومتها صغيرة جدًّا؛ مما يجعل التيار المار فيها كبيرًا جدًّا. (b) المنصهر الكهربائي: قطعة قصيرة من فلز تنصهر عندما يمرّ فيها تيار كبير فتقطع التيار عن الدائرة. (c) قاطع الدائرة الكهربائية: مفتاح كهربائي آلي يعمل على فتح الدائرة الكهربائية عندما يتجاوز مقدار التيار المار فيها القيمة المسموح بها. (d) قاطع التفريغ الأرضي الخاطئ: أداة سلامة تحتوي على دائرة إلكترونية تكشف الفروق البسيطة في التيار الكهربائي الناتجة عن مسار إضافي للتيار، فتفتح الدائرة. (e) الدائرة الكهربائية المركّبة: دائرة تحتوي على نوعي التوصيل التوالي والتوازي معًا.', '["دائرة القصر: مقاومة صغيرة جدًّا وتيار كبير جدًّا","المنصهر: قطعة فلز قصيرة تنصهر عند مرور تيار كبير","القاطع: مفتاح آلي يفتح الدائرة عند تجاوز التيار القيمة المسموح بها","قاطع التفريغ الأرضي الخاطئ: دائرة إلكترونية تكشف الفروق البسيطة في التيار الناتجة عن مسار إضافي","الدائرة المركّبة: توالٍ وتوازٍ معًا"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف دائرة القصر","marks":1},{"element":"تعريف المنصهر","marks":1},{"element":"تعريف القاطع","marks":1},{"element":"تعريف قاطع التفريغ الأرضي الخاطئ","marks":1},{"element":"تعريف الدائرة المركّبة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التعريفات الخمسة صحيحة ودقيقة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة تعريفات صحيحة"},{"level":"1–2 درجة","description":"تعريف أو تعريفان صحيحان"},{"level":"صفر","description":"لا تعريف صحيح"}]'::jsonb, '["الخلط بين المنصهر (ينصهر) والقاطع (مفتاح آلي يفتح)","وصف دائرة القصر بأن مقاومتها كبيرة أو تيارها صغير","تعريف الدائرة المركّبة بأنها دائرة فيها أجهزة كثيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.398Z"}'::jsonb),
('essay', 2, null::int, null, null, 'دائرة القصر دائرة كهربائية مقاومتها صغيرة جدًّا؛ مما يجعل التيار المار فيها كبيرًا جدًّا. يمكن أن تتكوّن إذا أصبحت الطبقة العازلة لسلكي المصباح هشة وتالفة فيتلامس السلكان. التيار عندئذ: $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}} = \frac{120\ \text{V}}{0.010\ \Omega} = 12000\ \text{A}$. وهي خطيرة لأن هذا التيار الكبير جدًّا ينتج طاقة حرارية كبيرة ترفع درجة حرارة الأسلاك وقد تصهر مادتها العازلة وتُحدث حريقًا إذا لم يوجد منصهر أو قاطع يفتح الدائرة.', '["تعريف دائرة القصر","سبب تكوّنها: تلف العازل وتلامس السلكين","$\\mathrm{I} = 12000\\ \\text{A}$","خطرها: تسخين الأسلاك وحدوث حريق"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}}$","$\\mathrm{I} = \\frac{120\\ \\text{V}}{0.010\\ \\Omega}$","$\\mathrm{I} = 12000\\ \\text{A}$"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"كيفية التكوّن","marks":1},{"element":"حساب التيار","marks":1},{"element":"سبب الخطورة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريف وطريقة التكوّن والحساب وسبب الخطورة صحيحة"},{"level":"2–3 درجات","description":"التعريف والخطورة صحيحان مع خطأ في الحساب أو إغفال طريقة التكوّن"},{"level":"1 درجة","description":"التعريف وحده أو الحساب وحده صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $\\mathrm{I} = \\mathrm{V} \\times \\mathrm{R} = 1.2\\ \\text{A}$","القول إن دائرة القصر خطيرة لأن التيار ينقطع","إغفال دور الحرارة في إحداث الحريق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.398Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المنصهر الكهربائي: قطعة فلز قصيرة تنصهر عند مرور تيار كبير فتقطع التيار. (b) دائرة القصر: تكوّن دائرة كهربائية مقاومتها صغيرة جدًّا فيمر فيها تيار كبير جدًّا. (c) دائرة كهربائية مركّبة: لأنها تحتوي على نوعي التوصيل التوالي والتوازي معًا. (d) قاطع الدائرة الكهربائية: مفتاح كهربائي آلي يفتح الدائرة عند تجاوز التيار القيمة المسموح بها. (e) قاطع التفريغ الأرضي الخاطئ: يكشف الفروق البسيطة في التيار الناتجة عن مسار إضافي للتيار (عبر جسم الشخص) فيفتح الدائرة.', '["(a) المنصهر الكهربائي","(b) دائرة القصر","(c) الدائرة الكهربائية المركّبة","(d) قاطع الدائرة الكهربائية","(e) قاطع التفريغ الأرضي الخاطئ"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1},{"element":"(e)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المصطلحات الخمسة صحيحة مع السبب"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة مصطلحات صحيحة"},{"level":"1–2 درجة","description":"مصطلح أو مصطلحان صحيحان"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تسمية الموقف (e) قاطع الدائرة الكهربائية مع أن التيار الكلي صغير","تسمية الموقف (d) منصهرًا مع أن الأداة مفتاح لا ينصهر","تسمية الموقف (c) دائرة توالٍ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.399Z"}'::jsonb)
