('mcq', 4, 'يبين الشكل الآتي سلكي جهاز كهربائي يمران خلال محوّل قاطع التفريغ الأرضي الخاطئ، والتيار في كل منهما. ماذا يحدث؟', null, '[{"src":"qimg/phys32/c2l2-o02-gfci.svg","alt":"سلكان أفقيان متوازيان يصلان المصدر (يسارًا) بجهاز (صندوق يمينًا): السلك الحي في الأعلى والسلك المتعادل في الأسفل، ويمر السلكان معًا خلال حلقة واحدة هي المحوّل. فوق السلك الحي سهم نحو الجهاز مكتوب عنده 2.50 A، وتحت السلك المتعادل سهم عائد نحو المصدر مكتوب عنده 2.45 A."}]'::jsonb, '["ينصهر منصهر الدائرة فورًا؛ لأن التيار في السلك الحي تجاوز قدرة تحمل المنصهر","لا يحدث شيء؛ لأن الفرق بين التيارين صغير جدًّا لا يكفي لفتح أي أداة سلامة","يتقوّس الشريط الفلزي المزدوج في القاطع؛ لأن التيار أكبر من المسموح به","تصبح محصلة التيار في المحوّل غير صفرية، فيُنشّط المجسّ الملف القاطع"]'::jsonb, 'تحليل', 'تفسير موقف', 'صعب', 'الكتاب ص 60 — كيف تعمل دائرة قاطع التفريغ الأرضي الخاطئ؟'),
('mcq', 5, 'لماذا لا يكفي منصهر الدائرة وحده لحماية شخص لمس جهازًا معيبًا وهو يقف على أرض مبتلة؟', null, null, '["لأن المنصهر يوصل على التوازي مع الجهاز، فلا يمر فيه التيار المار في جسم الشخص","لأن تيارًا صغيرًا نحو 5 mA يمر في الجسم قد يقتل، وهو أصغر كثيرًا مما يصهر المنصهر","لأن التيار المار في جسم الشخص يكون أكبر كثيرًا من قدرة تحمل المنصهر فلا يستجيب له","لأن المنصهر لا يعمل إلا إذا كانت الأجهزة موصولة على التوالي"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 52–53 — قاطع التفريغ الأرضي الخاطئ'),
('mcq', 6, 'ما وظيفة زر الفحص في دائرة قاطع التفريغ الأرضي الخاطئ؟', null, null, '["يوصل مقاومة صغيرة بالدائرة فينشئ تيارين غير متساويين في المحوّل، فيفتح القاطع الدائرة","يعيد ذراع المفتاح إلى وضع الإغلاق تلقائيًّا بعد أن يبرد الشريط الفلزي المزدوج في القاطع","يقيس التيار الكلي المار في الجهاز ويقارنه بقدرة تحمل المنصهر","يصل السلك الحي بالأرض مباشرة ليُفرّغ الشحنات الزائدة من الجهاز"]'::jsonb, 'فهم', 'شرح آلية', 'متوسط', 'الكتاب ص 60 — زر الفحص'),
('mcq', 7, 'كيف يمنع المنصهر الكهربائي أو قاطع الدائرة اشتعال حريق عند حدوث دائرة قصر في سلكي مصباح منزلي؟', null, null, '["يقلل المنصهر مقاومة الدائرة عند حدوث دائرة القصر، فيقل التيار المار في الأسلاك إلى قيمة آمنة","يحوّل المنصهر التيار الكبير إلى سلك التأريض، فلا يمر هذا التيار في أسلاك المنزل ولا يسخّنها","ينصهر المنصهر أو ينفتح القاطع، فتُفتح الدائرة قبل أن تسخن الأسلاك إلى حد الاشتعال","يرفع القاطع فرق الجهد بين طرفي المصباح عند حدوث دائرة القصر، فيقل التيار المار في السلكين"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 53 — توفّر المنصهرات والقواطع الحماية من التيارات الكبيرة'),
('essay', 1, 'وضّح كيف يعمل كل من المنصهر الكهربائي وقاطع الدائرة الكهربائية على حماية أسلاك التوصيلات الكهربائية في المنزل من الحمل الزائد. اذكر في إجابتك ما الذي يسبب الحمل الزائد، وما الذي يحدث داخل كل أداة عندما يتجاوز التيار القيمة المسموح بها.', null, null, null, 'فهم', 'شرح آلية', 'متوسط', 'الكتاب ص 52 — أدوات السلامة، والتقويم ص 62 السؤال 35'),
('essay', 2, 'يمر سلكا جهاز كهربائي (السلك الحي والسلك المتعادل) خلال محوّل قاطع التفريغ الأرضي الخاطئ كما في الشكل الآتي. وضّح كيف تعمل دائرة القاطع: (a) في الوضع الطبيعي. (b) عند حدوث تفريغ أرضي خاطئ (كأن يمر جزء من التيار في جسم شخص نحو الأرض). (c) عند الضغط على زر الفحص. وما المدة التي تستغرقها عملية فتح الدائرة؟', null, '[{"src":"qimg/phys32/c2l2-o02-gfci.svg","alt":"سلكان أفقيان متوازيان يصلان المصدر (يسارًا) بجهاز (صندوق يمينًا): السلك الحي في الأعلى والسلك المتعادل في الأسفل، ويمر السلكان معًا خلال حلقة واحدة هي المحوّل. فوق السلك الحي سهم نحو الجهاز مكتوب عنده 2.50 A، وتحت السلك المتعادل سهم عائد نحو المصدر مكتوب عنده 2.45 A."}]'::jsonb, null, 'فهم', 'شرح آلية', 'صعب', 'الكتاب ص 60 — كيف تعمل دائرة قاطع التفريغ الأرضي الخاطئ؟'),
('essay', 3, '(a) يحدث التفريغ الأرضي الخاطئ عادة عندما يقف شخص على سطح مبلل بالماء ويلمس جهازًا موصولًا بالكهرباء. كيف يكون الماء عاملًا في تكوّن التفريغ الأرضي الخاطئ؟
(b) هل تعمل دائرة قاطع التفريغ الأرضي الخاطئ على حماية شخص يُمسك أحد السلكين بيد ويُمسك السلك الآخر باليد الأخرى، وهو معزول عن الأرض؟ وضّح إجابتك.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 60 — التفكير الناقد 1 و2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عند توصيل مجموعة من الأجهزة على التوازي تقل المقاومة المكافئة للدائرة أكثر كلما شُغّل جهاز منها، فيزداد التيار المار في الأسلاك، وقد ينتج هذا التيار الإضافي طاقة حرارية تصهر المادة العازلة؛ لذا تعمل المنصهرات والقواطع على منع الحمل الزائد.', '["","إضافة فرع على التوازي تُنقص المقاومة المكافئة ولا تزيدها.","فرق الجهد بين طرفي كل جهاز على التوازي يبقى مساويًا لجهد المصدر.","تيار كل جهاز على التوازي لا يعتمد على الأجهزة الأخرى، والشحنات لا تتجمع في الأسلاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-27T21:51:39.399Z"}'::jsonb),
('mcq', 2, 2, 'عند مرور تيار كبير خلال الشريط الفلزي المزدوج يسخن الشريط ويتقوّس؛ لأنه مصنوع من فلزين مختلفين، فيتحرر المزلاج ويتحرك ذراع المفتاح إلى وضع فتح الدائرة فتنفتح.', '["الشريط في القاطع لا ينصهر بل يتقوّس؛ الانصهار يحدث في المنصهر.","هذه طريقة عمل قاطع التفريغ الأرضي الخاطئ لا قاطع الدائرة.","","التيار الكبير يسخّن الشريط ولا يبرّده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.400Z"}'::jsonb),
('mcq', 3, 1, 'يحدد سُمك قطعة الفلز في المنصهر مقدار التيار اللازم لعمل الدائرة، بحيث يمر فيها التيار بأمان دون أن يؤدي إلى تلفها؛ فإذا مر تيار أكبر انصهرت القطعة.', '["عدد الأجهزة يغيّر التيار المار، لكنه لا يحدد التيار الذي يتحمله المنصهر.","","طول أسلاك التمديدات لا يحدد قدرة تحمل المنصهر.","جهد المصدر لا يحدد التيار الذي يتحمله المنصهر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.400Z"}'::jsonb),
('mcq', 4, 3, 'التياران غير متساويين (الفرق 0.05 A = 50 mA، أي إن جزءًا من التيار يسلك مسارًا خاطئًا نحو الأرض)، فتكون محصلة التيار المار خلال المحوّل غير صفرية، فيتولّد مجال مغناطيسي متغيّر يولّد تيارًا في حلقة المجسّ الإلكتروني، فيكشفه المجسّ ويُنشّط الملف القاطع فتُفتح الدائرة.', '["تيار مقداره 2.50 A أقل كثيرًا مما يصهر منصهرًا منزليًّا؛ المهم هنا عدم تساوي التيارين.","قاطع التفريغ الأرضي الخاطئ مصمم لكشف الفروق البسيطة في التيار؛ والفرق هنا 50 mA، وهو أكبر كثيرًا من 5 mA الذي قد يقتل شخصًا يمر فيه.","التيار ليس كبيرًا، والشريط الفلزي المزدوج جزء من قاطع الدائرة لا من قاطع التفريغ الأرضي الخاطئ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-27T21:51:39.400Z"}'::jsonb),
('mcq', 5, 1, 'قد يؤدي مرور تيار صغير مقداره 5 mA في جسم الشخص إلى موته بالصدمة الكهربائية، وهذا التيار أصغر كثيرًا من التيار الكبير الذي يصهر المنصهر؛ لذا يُستخدم قاطع التفريغ الأرضي الخاطئ الذي يكشف الفروق البسيطة في التيار.', '["المنصهر يوصل على التوالي مع مصدر الجهد، والمشكلة في صغر التيار لا في طريقة التوصيل.","","لو كان التيار أكبر من قدرة تحمل المنصهر لانصهر؛ المشكلة أن التيار الخطِر صغير.","المنصهر يحمي دوائر التوازي المنزلية، فهو يعمل مع الأجهزة الموصولة على التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.400Z"}'::jsonb),
('mcq', 6, 0, 'يوصل زر الفحص في دائرة قاطع التفريغ الأرضي الخاطئ مقاومة صغيرة بالدائرة، فينشئ مرة أخرى تيارات غير متساوية في المحوّل، ويفتح الدائرة الكهربائية؛ وبذلك يُتحقق من أن القاطع يعمل.', '["","الشريط الفلزي المزدوج جزء من قاطع الدائرة الكهربائية، وزر الفحص لا يعيد إغلاق الدائرة.","قاطع التفريغ الأرضي الخاطئ لا يقارن التيار بقدرة تحمل المنصهر بل يكشف عدم تساوي تياري السلكين.","زر الفحص لا يصل السلك الحي بالأرض مباشرة، بل يوصل مقاومة صغيرة تُحدث فرقًا بين التيارين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.401Z"}'::jsonb),
('mcq', 7, 2, 'يؤدي مرور التيار الكبير جدًّا الناتج عن دائرة القصر إلى صهر المنصهر الكهربائي أو فتح القاطع، ومن ثم فتح الدائرة؛ مما يمنع ارتفاع درجة حرارة الأسلاك إلى حد إشعال الحريق.', '["نقصان المقاومة يزيد التيار، والمنصهر لا يحدّ من التيار بل يقطعه.","المنصهر والقاطع يفتحان الدائرة ولا يحوّلان التيار إلى سلك آخر.","","المنصهر لا يغيّر فرق الجهد، بل يفتح الدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.401Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يحدث الحمل الزائد عند تشغيل عدة أجهزة موصولة على التوازي في الوقت نفسه؛ لأن المقاومة المكافئة تقل فيزداد التيار المار في الأسلاك، وقد يُنتج التيار الإضافي طاقة حرارية تصهر المادة العازلة للأسلاك فتتلامس وتحدث دائرة قصر وربما حريق. المنصهر قطعة قصيرة من فلز يحدد سمكها التيار الذي يمر فيها بأمان، ويوصل على التوالي بحيث يمر فيه التيار الكلي؛ فإذا مر تيار أكبر مما تتحمله الدائرة انصهرت القطعة وانقطع التيار. قاطع الدائرة مفتاح آلي فيه شريط فلزي مزدوج من فلزين مختلفين؛ عند مرور تيار كبير يسخن الشريط ويتقوّس فيتحرر المزلاج ويتحرك ذراع المفتاح إلى وضع الفتح فتنفتح الدائرة ويتوقف التيار.', '["سبب الحمل الزائد: نقص المقاومة المكافئة وزيادة التيار","خطر الحمل الزائد: حرارة تصهر العازل","المنصهر: انصهار قطعة الفلز عند تجاوز التيار","القاطع: تسخّن الشريط المزدوج وتقوّسه وتحرر المزلاج وفتح الدائرة"]'::jsonb, '[]'::jsonb, '[{"element":"سبب الحمل الزائد","marks":1},{"element":"خطره","marks":1},{"element":"عمل المنصهر","marks":1},{"element":"عمل القاطع (الشريط الفلزي المزدوج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"عمل الأداتين صحيح مع نقص في تفسير الحمل الزائد"},{"level":"1 درجة","description":"عمل أداة واحدة فقط صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القاطع ينصهر مثل المنصهر","القول إن إضافة الأجهزة تزيد المقاومة المكافئة","إغفال أن الشريط مصنوع من فلزين مختلفين يتمددان بمقدارين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.401Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) في الوضع الطبيعي يمر في السلكين تياران متساويان في المقدار ومتعاكسان في الاتجاه؛ لذا يكون التيار المحصّل المار خلال المحوّل صفرًا، فلا تُفتح الدائرة. (b) عند حدوث التفريغ الأرضي الخاطئ يمر تيار من السلك الحي نحو الأرض عن طريق جسم الشخص، فيكون التياران في السلكين غير متساويين، وتكون هناك قيمة لمحصلة التيار المار خلال المحوّل؛ فيولّد هذا التيار المحصّل مجالًا مغناطيسيًّا متغيرًا في قلب المحوّل، مما يولّد تيارًا في حلقة المجسّ الإلكتروني، فيكشف المجسّ التيار ويُنشّط مغناطيسًا كهربائيًّا يسمى الملف القاطع، فتُفتح الدائرة. وتستغرق العملية 0.025 s. (c) زر الفحص يوصل مقاومة صغيرة بالدائرة، فتنشأ مرة أخرى تيارات غير متساوية في المحوّل وتُفتح الدائرة.', '["(a) تياران متساويان ومتعاكسان، والمحصلة صفر","(b) تياران غير متساويين ومحصلة لا تساوي صفرًا","(b) مجال مغناطيسي متغير يولّد تيارًا في المجسّ فيُنشّط الملف القاطع","0.025 s","(c) مقاومة صغيرة تُحدث عدم تساوٍ"]'::jsonb, '[]'::jsonb, '[{"element":"الوضع الطبيعي","marks":1},{"element":"عدم تساوي التيارين عند التفريغ","marks":1},{"element":"سلسلة الكشف: المحوّل ثم المجسّ ثم الملف القاطع","marks":1},{"element":"زمن العملية","marks":1},{"element":"زر الفحص","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحالات الثلاث وزمن العملية صحيحة"},{"level":"3–4 درجات","description":"الحالتان (a) و(b) صحيحتان مع نقص في (c) أو الزمن"},{"level":"1–2 درجة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القاطع يفتح الدائرة لأن التيار كبير","القول إن التيار في الوضع الطبيعي يمر في سلك واحد فقط","الخلط بين عمل هذا القاطع وعمل الشريط الفلزي المزدوج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-27T21:51:39.401Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الماء يجعل الجلد رطبًا فتقل مقاومته، ويصل جسم الشخص بالأرض؛ فيتكوّن مسار إضافي للتيار من السلك الحي عبر جسم الشخص إلى الأرض، فيمر فيه تيار قد يكون خطِرًا. (b) لا يحمي القاطع الشخص في هذه الحالة؛ لأن التيار يدخل جسمه من أحد السلكين ويعود كله عبر السلك الآخر، فيبقى التياران في السلكين متساويين في المقدار ومتعاكسين في الاتجاه، وتبقى محصلة التيار خلال المحوّل صفرًا، فلا يكشف المجسّ شيئًا. فالشخص في هذه الحالة يكون كأنه جهاز موصول بالدائرة، ولا يوجد مسار خاطئ نحو الأرض.', '["الماء يقلل مقاومة الجلد","الماء يصل الجسم بالأرض فيتكوّن مسار إضافي","لا يحمي القاطع في الحالة (b)","التعليل: التياران يبقيان متساويين ومحصلتهما صفر"]'::jsonb, '[]'::jsonb, '[{"element":"دور الماء في تقليل المقاومة","marks":1},{"element":"تكوّن المسار نحو الأرض","marks":1},{"element":"الحكم في (b)","marks":1},{"element":"تعليل الحكم بتساوي التيارين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجزآن صحيحان مع التعليل"},{"level":"2–3 درجات","description":"أحد الجزأين صحيح كاملًا والآخر ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القاطع يحمي الشخص دائمًا لأن التيار في جسمه كبير","إغفال أن التيار العائد يمر في السلك الآخر داخل المحوّل","القول إن الماء يزيد مقاومة الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.402Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
