from (values
('mcq', 1, 3, 'المنصهر موصول على التوالي بمصدر الجهد في المسار الرئيس قبل نقاط التفرّع، فيمر فيه التيار الكلي للدائرة، وهو في دائرة التوازي يساوي مجموع تيارات الأجهزة؛ فإذا تجاوز هذا المجموع قدرة تحمل المنصهر انصهر وفتح الدائرة.', '["المنصهر في المسار الرئيس يمر فيه تيار الأجهزة كلها لا تيار جهاز واحد.","التيار الكلي يساوي مجموع تيارات الفروع لا متوسطها، وتيارات الأجهزة لا تتساوى بالضرورة.","المنصهر جزء من المسار الرئيس، فيمر فيه التيار الكلي دائمًا في أثناء عمل الأجهزة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-27T21:51:39.402Z"}'::jsonb),
('mcq', 2, 0, 'النقطة P على السلك الرئيس بين المصدر وأول نقطة تفرّع، فيمر فيها التيار الكلي للأجهزة الثلاثة؛ والمنصهر الموصول عندها يكون على التوالي بمصدر الجهد ويحمي الدائرة كلها.', '["","النقطة Q بعد نقطة تفرّع التلفاز، فلا يمر فيها إلا تيارا المكواة والمصباح، ولا يحمي المنصهر عندها فرع التلفاز.","النقطة S في فرع المصباح، فلا يمر فيها إلا تيار المصباح.","النقطة T على السلك السفلي بعد فرع التلفاز، فلا يمر فيها إلا تيارا المكواة والمصباح العائدان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.402Z"}'::jsonb),
('mcq', 3, 1, 'المنصهر الرئيس موصول على التوالي بمصدر الجهد في المسار الذي يمر فيه التيار الكلي قبل نقاط التفرّع؛ فإذا انصهر انقطع هذا المسار وفُتحت الدائرة كلها، فتتوقف الأجهزة جميعها.', '["المنصهر الرئيس قبل نقاط التفرّع، فانقطاعه يقطع التيار عن الفروع كلها لا عن فرع واحد.","","الأجهزة على التوازي فيما بينها، لكنها كلها تتصل بالمصدر عبر المسار الرئيس الذي انقطع.","المنصهر الرئيس لا يميّز الجهاز الذي سبّب الحمل الزائد؛ انصهاره يفتح الدائرة كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-27T21:51:39.403Z"}'::jsonb),
('mcq', 4, 2, 'المنصهر قطعة فلز مقاومتها صغيرة، فإذا وُصل بين السلكين على التوازي مع المصدر تكوّن مسار مقاومته صغيرة جدًّا بين طرفي المصدر (دائرة قصر) فيمر فيه تيار كبير جدًّا وينصهر فورًا، ولا يمر فيه التيار الكلي للأجهزة؛ لذلك يجب وصله على التوالي بمصدر الجهد.', '["تساوي الجهد لا يجعله يحمي الأجهزة؛ المطلوب أن يمر فيه التيار الكلي.","المسار الذي مقاومته صغيرة جدًّا يمر فيه تيار كبير جدًّا لا تيار معدوم.","","المنصهر على التوازي مع المصدر يمر فيه تيار كبير جدًّا دائمًا، ولا يعمل بالطريقة الموصوفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.403Z"}'::jsonb),
('mcq', 5, 0, 'المنصهر الموصول على التوالي مع المكواة في فرعها يمر فيه تيار المكواة وحده؛ فهو يحمي هذا الفرع، أما الحمل الزائد الناتج عن تشغيل الأجهزة الأخرى فلا يمر فيه، ولحماية الدائرة كلها يوصل المنصهر على التوالي بمصدر الجهد.', '["","تيارات التلفاز والمصباح لا تمر في هذا المنصهر فلا يحميها.","المنصهر يوصل على التوالي، وهو هنا يحمي فرع المكواة.","هذا عكس الواقع؛ تيار المكواة وحده هو الذي يمر فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.403Z"}'::jsonb),
('mcq', 6, 1, 'صُممت أسلاك الدائرة لتحمل 15 A؛ فإذا استُعمل منصهر 30 A أمكن أن يمر في الأسلاك تيار أكبر من 15 A (حتى 30 A) دون أن ينصهر، فتسخن الأسلاك وقد تنصهر مادتها العازلة ويحدث حريق.', '["المنصهر 30 A يتحمل تيارًا أكبر لا أصغر.","","المنصهر لا يغيّر جهد الدائرة.","المنصهران كلاهما يوصلان على التوالي بمصدر الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-27T21:51:39.403Z"}'::jsonb),
('mcq', 7, 3, 'المنصهر موصول على التوالي بالمصدر فيمر فيه التيار الكلي الذي يساوي مجموع تيارات الأجهزة؛ فإذا أُطفئ جهاز نقص التيار الكلي بمقدار تياره، وبقيت تيارات الأجهزة الأخرى كما هي.', '["ثبات جهد كل جهاز يُبقي تيارات الأجهزة الأخرى ثابتة، لكن التيار الكلي ينقص بغياب تيار الجهاز المطفأ.","إطفاء جهاز يفتح فرعه فتزداد المقاومة المكافئة ولا تقل.","إطفاء جهاز يفتح فرعه وحده، ويبقى التيار في الفروع الأخرى وفي المنصهر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-27T21:51:39.403Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) وُصل المنصهر على التوالي بمصدر الجهد في السلك الرئيس قبل نقاط التفرّع؛ بحيث يمر فيه التيار الكلي للدائرة، فيحمي جميع الأجهزة والأسلاك. (b) يزداد التيار المار في المنصهر؛ لأن الأجهزة موصولة على التوازي، فكلما شُغّل جهاز إضافي قلّت المقاومة المكافئة وزاد التيار الكلي (الذي يساوي مجموع تيارات الأجهزة). (c) ينصهر عندما يتجاوز التيار الكلي 15 A (قدرة تحمله)، فينقطع مسار التيار الرئيس وتُفتح الدائرة فتتوقف جميع الأجهزة، وتُحمى الأسلاك من السخونة الزائدة.', '["التوصيل على التوالي بالمصدر","ليمر فيه التيار الكلي","زيادة التيار الكلي بتشغيل الأجهزة معًا لنقص المقاومة المكافئة","ينصهر عند تجاوز 15 A فتُفتح الدائرة كلها"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة التوصيل","marks":1},{"element":"سبب التوصيل","marks":1},{"element":"أثر تشغيل الأجهزة معًا مع التعليل","marks":1},{"element":"شرط الانصهار ونتيجته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة مع التعليل"},{"level":"2–3 درجات","description":"طريقة التوصيل وسببها صحيحان مع نقص في (b) أو (c)"},{"level":"1 درجة","description":"طريقة التوصيل وحدها صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المنصهر يوصل على التوازي مع الأجهزة","القول إن التيار الكلي لا يتغير بتشغيل أجهزة أكثر","القول إن انصهار المنصهر يوقف جهازًا واحدًا فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.404Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قول الطالب غير صحيح. (a) هذا هو التوصيل الصحيح: يمر في المنصهر التيار الكلي، فينصهر عند حدوث حمل زائد أو دائرة قصر في أي جزء من الدائرة، فيحمي جميع الأجهزة والأسلاك. (b) يمر في المنصهر تيار ذلك الجهاز وحده، فيحمي فرعه فقط، ولا يكشف الحمل الزائد الناتج عن تشغيل الأجهزة الأخرى، فقد يتجاوز التيار في الأسلاك الرئيسة الحد الآمن دون أن ينصهر. (c) المنصهر قطعة فلز مقاومتها صغيرة، فوصله بين السلكين يكوّن دائرة قصر بين طرفي المصدر، فيمر فيه تيار كبير جدًّا وينصهر فورًا، ولا يمر فيه تيار الأجهزة فلا يحميها. إذن الموضع مهم: يجب أن يوصل على التوالي بمصدر الجهد بحيث يمر فيه التيار الكلي.', '["الحكم: القول غير صحيح","(a) يمر التيار الكلي فيحمي الدائرة كلها","(b) يحمي فرع الجهاز وحده","(c) دائرة قصر ولا يمر فيه تيار الأجهزة","الاستنتاج: على التوالي بالمصدر"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"الحالة (a)","marks":1},{"element":"الحالة (b)","marks":1},{"element":"الحالة (c)","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع مناقشة الحالات الثلاث والاستنتاج"},{"level":"3–4 درجات","description":"حكم صحيح مع مناقشة حالتين صحيحتين"},{"level":"1–2 درجة","description":"حكم صحيح مع مناقشة حالة واحدة أو دون تعليل"},{"level":"صفر","description":"تأييد قول الطالب أو لا إجابة"}]'::jsonb, '["القول إن المنصهر في فرع جهاز يحمي الدائرة كلها","القول إن المنصهر على التوازي لا يمر فيه أي تيار","إغفال أن المطلوب مرور التيار الكلي فيه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.404Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُوصل الأجهزة الثلاثة على التوازي بين السلكين الرئيسين الموصولين بالمصدر 120 V. يوصل المنصهر الرئيس على التوالي في أحد السلكين الرئيسين بين المصدر وأول نقطة تفرّع؛ فيمر فيه التيار الكلي (مجموع تيارات المصباح والمكواة والتلفاز) ويحمي الدائرة كلها. ويوصل المنصهر الثاني على التوالي مع المكواة داخل فرعها (بين نقطة التفرّع والمكواة)؛ فلا يمر فيه إلا تيار المكواة، فيحميها وحدها. ويرسم المنصهر برمزه (منحنى على شكل S على السلك).', '["الأجهزة على التوازي بين السلكين","المنصهر الرئيس على التوالي قبل نقاط التفرّع","يمر فيه التيار الكلي","منصهر المكواة على التوالي في فرعها","يمر فيه تيار المكواة فقط"]'::jsonb, '[]'::jsonb, '[{"element":"توصيل الأجهزة على التوازي","marks":1},{"element":"موضع المنصهر الرئيس","marks":1},{"element":"تيار المنصهر الرئيس","marks":1},{"element":"موضع منصهر المكواة","marks":1},{"element":"تيار منصهر المكواة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التصميم صحيح كاملًا مع التعليل وتحديد التيارين"},{"level":"3–4 درجات","description":"موضعا المنصهرين صحيحان مع نقص في التعليل أو التيارات"},{"level":"1–2 درجة","description":"موضع منصهر واحد صحيح"},{"level":"صفر","description":"تصميم خاطئ أو لا إجابة"}]'::jsonb, '["وضع المنصهر الرئيس بعد إحدى نقاط التفرّع","وصل منصهر المكواة على التوازي معها","القول إن منصهر المكواة يمر فيه التيار الكلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-27T21:51:39.404Z"}'::jsonb)
