('mcq', 1, 'أيّ المقارنات الآتية بين الأميتر والفولتمتر صحيحة؟', null, null, '["الأميتر يوصل على التوالي ومقاومته صغيرة جدًّا، والفولتمتر يوصل على التوازي ومقاومته كبيرة جدًّا","الفولتمتر يوصل على التوالي بمقاومة صغيرة جدًّا، أما الأميتر فعلى التوازي بمقاومة كبيرة جدًّا","كلاهما يوصل على التوالي، لكن مقاومة الأميتر صغيرة جدًّا ومقاومة الفولتمتر كبيرة جدًّا","كلاهما مقاومته صغيرة جدًّا، لكن الأميتر يوصل على التوالي والفولتمتر يوصل على التوازي"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات، والمفاهيم الرئيسة ص 61'),
('mcq', 2, 'ما الكمية التي يقيسها كل من الأميتر والفولتمتر؟', null, null, '["الفولتمتر يقيس التيار المار في فرع من الدائرة، أما الأميتر فيقيس الهبوط في الجهد عبر جزء منها","الأميتر يقيس التيار المار في فرع أو جزء من الدائرة، والفولتمتر يقيس الهبوط في الجهد عبر جزء منها","كلاهما يقيس التيار المار في الدائرة، لكن الفولتمتر يقيس التيارات الكبيرة فقط","الأميتر يقيس المقاومة الكهربائية، والفولتمتر يقيس القدرة المستنفدة في الدائرة"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات'),
('mcq', 3, 'في الدائرة الآتية جهازا قياس X وY موصولان توصيلًا صحيحًا. ما نوع كل منهما؟', null, '[{"src":"qimg/phys32/c2l2-o04-xy.svg","alt":"دائرة فيها بطارية جهدها 12 V على اليسار (قطبها الموجب أعلى). في السلك العلوي جهاز قياس دائري مكتوب فيه X، يليه المقاومة R_A، ثم تنزل الدائرة عبر المقاومة R_B على اليمين وتعود إلى البطارية. جهاز قياس دائري ثانٍ مكتوب فيه Y موصول بسلكين بطرفي R_B مباشرة (من نقطة فوقها إلى نقطة تحتها)."}]'::jsonb, '["X فولتمتر، وY أميتر","كلاهما أميتر","كلاهما فولتمتر","X أميتر، وY فولتمتر"]'::jsonb, 'فهم', 'تصنيف من شكل', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات والشكل 2-12'),
('mcq', 4, 'أيّ العبارات الآتية عن أجهزة القياس صحيحة؟', null, null, '["يسبّب الفولتمتر تغيرًا صغيرًا جدًّا في تيار الدائرة عند توصيله","مقاومة الأميتر المثالي كبيرة جدًّا","مقاومة الفولتمتر المثالي صغيرة جدًّا","يسبّب الأميتر تغيرًا كبيرًا في تيار الدائرة لأنه يوصل على التوالي"]'::jsonb, 'فهم', 'حكم على عبارات', 'متوسط', 'الكتاب ص 69 — اختبار مقنن السؤال 8'),
('mcq', 5, 'وصل طالب فولتمترًا على التوالي مع مصباح في دائرة بسيطة بدلًا من الأميتر. ماذا يحدث للمصباح؟', null, null, '["يضيء بسطوعه المعتاد؛ لأن الفولتمتر يقيس التيار المار فيه دون أن يؤثر فيه","يزداد سطوعه؛ لأن الفولتمتر يرفع فرق الجهد بين طرفي المصباح","لا يضيء تقريبًا؛ لأن مقاومة الفولتمتر الكبيرة جدًّا تجعل التيار صغيرًا جدًّا","يحترق فتيله؛ لأن مقاومة الفولتمتر الصغيرة جدًّا تسبّب دائرة قصر فيه"]'::jsonb, 'تحليل', 'تنبؤ', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات'),
('mcq', 6, 'عند توصيل أميتر وفولتمتر توصيلًا صحيحًا في دائرة كهربائية، أيّ العبارات الآتية تصف التيار المار في كل منهما؟', null, null, '["يمر في الفولتمتر التيار كله المار في الجزء الذي يقيس جهده، ويمر في الأميتر تيار صغير جدًّا","يمر في الأميتر التيار كله المار في الجزء الذي يقيسه، ويمر في الفولتمتر تيار صغير جدًّا","يمر في كل منهما نصف تيار الدائرة؛ لأنهما جهازان موصولان بالدائرة نفسها","لا يمر تيار في أي منهما؛ لأنهما جهازا قياس لا يستهلكان طاقة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات'),
('mcq', 7, 'في أي عمليات القياس الآتية يجب قطع مسار التيار في الدائرة لإدخال جهاز القياس؟', null, null, '["قياس الهبوط في الجهد عبر مقاومة بالفولتمتر","قياس جهد البطارية بالفولتمتر","قياس التيار المار في مقاومة بالأميتر","قياس فرق الجهد بين طرفي مصباح"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات'),
('essay', 1, 'قارن بين الأميتر والفولتمتر من حيث: (a) الكمية التي يقيسها كل منهما. (b) طريقة توصيله في الدائرة. (c) مقدار مقاومته. (d) سبب تصميم مقاومته بهذا المقدار. (e) ما يوصل مع ملفه لتحقيق ذلك.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات، والتقويم ص 62 السؤال 39'),
('essay', 2, 'في الدائرة الآتية: (a) صف كيف توصل أميترًا لقياس التيار المار في المقاومة $\mathrm{R}_2$، محددًا موضعه بالنسبة إلى النقاط المعلّمة. (b) صف كيف توصل فولتمترًا لقياس الهبوط في الجهد عبر المقاومة $\mathrm{R}_1$، محددًا النقطتين اللتين يوصل بهما وأيّهما يتصل بطرفه الموجب. (c) هل يقرأ الأميتر القيمة نفسها لو وُضع عند النقطة a بدلًا من ذلك؟ علّل.', null, '[{"src":"qimg/phys32/c2l2-o04-points.svg","alt":"دائرة توالٍ: بطارية جهدها 9.0 V على اليسار قطبها الموجب أعلى، والسلك العلوي يمر بالنقطة a ثم المقاومة R_1 ثم النقطة b، ثم ينعطف السلك نزولًا إلى اليمين فيمر بالنقطة c ثم المقاومة R_2 ثم النقطة d، ثم يعود السلك السفلي إلى القطب السالب للبطارية."}]'::jsonb, null, 'تطبيق', 'وصف إجراء', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات'),
('essay', 3, 'بدّل طالب موضعي الجهازين كما في الشكل الآتي، فوصل الفولتمتر على التوالي في السلك الرئيس، والأميتر بين طرفي المصباح. حلّل ما يحدث: (a) هل يضيء المصباح؟ (b) ماذا يقرأ الفولتمتر تقريبًا؟ (c) ماذا يقرأ الأميتر تقريبًا؟ علّل كل إجابة بمقاومة الجهاز.', null, '[{"src":"qimg/phys32/c2l2-o04-swap.svg","alt":"دائرة فيها بطارية جهدها 6.0 V على اليسار قطبها الموجب أعلى، وفولتمتر (V) في السلك العلوي على التوالي، ثم مصباح رأسي على اليمين يعود منه السلك إلى البطارية، وأميتر (A) موصول بسلكين بطرفي المصباح مباشرة على التوازي معه."}]'::jsonb, null, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات والشكل 2-12')
