('mcq', 3, 3, 'الجهاز X موصول على التوالي في السلك الرئيس فيمر فيه تيار الدائرة؛ فهو أميتر. والجهاز Y موصول على التوازي بين طرفي المقاومة $\mathrm{R}_\mathrm{B}$؛ فهو فولتمتر يقيس الهبوط في الجهد عبرها.', '["الجهاز الموصول على التوالي هو الأميتر، والموصول على التوازي هو الفولتمتر، لا العكس.","الأميتر لا يوصل على التوازي بين طرفي مقاومة؛ فـ Y ليس أميترًا.","الفولتمتر لا يوصل على التوالي في السلك الرئيس؛ فـ X ليس فولتمترًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.405Z"}'::jsonb),
('mcq', 4, 0, 'يصمَّم الفولتمتر بمقاومة كبيرة جدًّا، فعند توصيله على التوازي لا يمر فيه إلا تيار صغير جدًّا، ويكون التغير في تيارات الدائرة وفروق جهدها صغيرًا جدًّا (مهملًا).', '["","مقاومة الأميتر صغيرة جدًّا لا كبيرة.","مقاومة الفولتمتر كبيرة جدًّا لا صغيرة.","مقاومة الأميتر صغيرة جدًّا، فتغيّر تيار الدائرة بمقدار صغير جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.405Z"}'::jsonb),
('mcq', 5, 2, 'مقاومة الفولتمتر كبيرة جدًّا، فإذا وُصل على التوالي أصبحت مقاومة الدائرة كبيرة جدًّا وصار التيار صغيرًا جدًّا، فلا يضيء المصباح تقريبًا؛ ولهذا يوصل الفولتمتر على التوازي.', '["الفولتمتر لا يقيس التيار، ومقاومته الكبيرة تقلل التيار كثيرًا عند وصله على التوالي.","الفولتمتر لا يرفع الجهد؛ ومقاومته الكبيرة تقلل التيار.","","مقاومة الفولتمتر كبيرة جدًّا لا صغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-27T21:51:39.405Z"}'::jsonb),
('mcq', 6, 1, 'الأميتر موصول على التوالي فيمر فيه التيار كله المار في الجزء الذي يقيسه، والفولتمتر موصول على التوازي ومقاومته كبيرة جدًّا فلا يمر فيه إلا تيار صغير جدًّا.', '["هذا عكس الصحيح؛ الأميتر هو الموصول على التوالي.","","التيار لا ينقسم بالتساوي؛ فالأميتر على التوالي يمر فيه التيار كله والفولتمتر يمر فيه تيار صغير جدًّا.","لا بد أن يمر تيار في الأميتر كي يقيسه، ويمر في الفولتمتر تيار صغير جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.406Z"}'::jsonb),
('mcq', 7, 2, 'لقياس التيار المار في مقاومة يجب أن يوصل الأميتر على التوالي بها، وهذا يتطلب قطع مسار التيار وإدخال الأميتر. أما الفولتمتر فيوصل بين طرفي الجزء دون قطع المسار.', '["الفولتمتر يوصل على التوازي بين طرفي المقاومة دون قطع المسار.","الفولتمتر يوصل بقطبي البطارية مباشرة دون قطع المسار.","","فرق الجهد يقاس بفولتمتر على التوازي دون قطع المسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.406Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الأميتر يقيس التيار الكهربائي في أي فرع أو جزء من الدائرة، والفولتمتر يقيس الهبوط في الجهد (فرق الجهد) عبر جزء أو مجموعة أجزاء من الدائرة. (b) الأميتر يوصل دائمًا على التوالي، والفولتمتر يوصل دائمًا على التوازي بين طرفي الجزء المراد قياس جهده. (c) مقاومة الأميتر صغيرة جدًّا، ومقاومة الفولتمتر كبيرة جدًّا. (d) الأميتر: لأن التيار سيقل إذا زاد الأميتر مقاومة الدائرة؛ والفولتمتر: حتى يكون التغير في التيارات وفروق الجهد في الدائرة أقل ما يمكن. (e) يوصل مع ملف الأميتر مقاومة صغيرة على التوازي، ومع ملف الفولتمتر مقاومة كبيرة على التوالي.', '["(a) التيار / الهبوط في الجهد","(b) توالٍ / توازٍ","(c) صغيرة جدًّا / كبيرة جدًّا","(d) السبب لكل منهما","(e) مقاومة صغيرة على التوازي / كبيرة على التوالي"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1},{"element":"(e)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"أوجه المقارنة الخمسة صحيحة للجهازين"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة أوجه صحيحة"},{"level":"1–2 درجة","description":"وجه أو وجهان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل طريقتي التوصيل","القول إن مقاومة الفولتمتر صغيرة كي يمر فيه تيار كبير","تبديل ما يوصل مع ملف كل جهاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-27T21:51:39.406Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يُقطع السلك بين النقطتين b وc (أو بين d والبطارية) ويُدخل الأميتر في الفجوة، فيصبح على التوالي مع $\mathrm{R}_2$ ويمر فيه تيارها، ويكون طرفه الموجب نحو القطب الموجب للبطارية (جهة b). (b) يوصل الفولتمتر على التوازي بين النقطتين a وb دون قطع أي سلك، ويوصل طرفه الموجب بالنقطة a لأنها الأقرب إلى القطب الموجب للبطارية. (c) نعم؛ لأن الدائرة دائرة توالٍ ذات مسار واحد، فالتيار متساوٍ في جميع أجزائها، فيقرأ الأميتر القيمة نفسها عند a.', '["الأميتر على التوالي بقطع السلك","موضع صحيح للأميتر","الفولتمتر بين a وb","الطرف الموجب عند a","التيار متساوٍ في دائرة التوالي"]'::jsonb, '[]'::jsonb, '[{"element":"توصيل الأميتر على التوالي","marks":1},{"element":"موضعه","marks":1},{"element":"توصيل الفولتمتر بين a وb","marks":1},{"element":"القطبية","marks":1},{"element":"(c) مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة مع القطبية والتعليل"},{"level":"3–4 درجات","description":"توصيل الجهازين صحيح مع خطأ في القطبية أو (c)"},{"level":"1–2 درجة","description":"توصيل جهاز واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصل الأميتر بين c وd على التوازي مع $\\mathrm{R}_2$","وصل الفولتمتر بين b وc","القول إن قراءة الأميتر عند a أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.406Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لا يضيء المصباح تقريبًا: الفولتمتر على التوالي مقاومته كبيرة جدًّا، فيصبح تيار الدائرة صغيرًا جدًّا، وهذا التيار الصغير يمر معظمه في الأميتر لا في المصباح؛ لأن مقاومة الأميتر الصغيرة جدًّا الموصولة على التوازي مع المصباح تجعل الجزء الموصول بينهما مقاومته صغيرة جدًّا. (b) يقرأ الفولتمتر قيمة تقارب جهد البطارية 6.0 V؛ لأن مقاومته أكبر كثيرًا من بقية الدائرة، فيقع عبره معظم الهبوط في الجهد. (c) يقرأ الأميتر تيارًا صغيرًا جدًّا (قريبًا من الصفر)؛ لأن مقاومة الفولتمتر الكبيرة على التوالي تجعل تيار الدائرة كله صغيرًا جدًّا. فالتوصيل خاطئ: يوصل الأميتر على التوالي والفولتمتر على التوازي.', '["(a) لا يضيء المصباح تقريبًا","تعليل (a) بمقاومة الفولتمتر الكبيرة على التوالي","(b) قراءة الفولتمتر قريبة من 6.0 V مع التعليل","(c) قراءة الأميتر قريبة من الصفر مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"تعليل (a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التحليل كامل ومعلل"},{"level":"2–3 درجات","description":"جزآن صحيحان مع التعليل"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأميتر يحترق لمرور تيار كبير فيه مع أن الفولتمتر على التوالي يحدّ من التيار","القول إن الفولتمتر يقرأ صفرًا","القول إن المصباح يضيء بسطوع أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-27T21:51:39.406Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L2-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما مقدار المقاومة المكافئة للدائرة المركّبة الآتية؟', null, '[{"src":"qimg/phys32/c2l2-o05-a.svg","alt":"دائرة مركّبة: بطارية جهدها 24.0 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_A وقيمتها 4.0 Ω، ثم نقطة تفرّع يخرج منها فرعان رأسيان بين السلك العلوي والسلك السفلي: الأول فيه المقاومة R_B وقيمتها 6.0 Ω، والثاني (أقصى اليمين) فيه المقاومة R_C وقيمتها 12.0 Ω، ويعود السلك السفلي إلى البطارية."}]'::jsonb, '["22.0 Ω","2.0 Ω","8.0 Ω","4.0 Ω"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة'),
('mcq', 2, 'في الدائرة المركّبة الآتية، ما مقدار التيار المار في المقاومة $\mathrm{R}_\mathrm{C}$؟', null, '[{"src":"qimg/phys32/c2l2-o05-a.svg","alt":"دائرة مركّبة: بطارية جهدها 24.0 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_A وقيمتها 4.0 Ω، ثم نقطة تفرّع يخرج منها فرعان رأسيان بين السلك العلوي والسلك السفلي: الأول فيه المقاومة R_B وقيمتها 6.0 Ω، والثاني (أقصى اليمين) فيه المقاومة R_C وقيمتها 12.0 Ω، ويعود السلك السفلي إلى البطارية."}]'::jsonb, '["1.0 A","1.5 A","3.0 A","2.0 A"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة'),
('mcq', 3, 'في الدائرة المركّبة الآتية، ما مقدار الهبوط في الجهد عبر المقاومة 16.0 Ω؟', null, '[{"src":"qimg/phys32/c2l2-o05-b.svg","alt":"دائرة مركّبة: بطارية جهدها 36.0 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_1 وقيمتها 12.0 Ω، ثم نقطة تفرّع يخرج منها فرعان رأسيان بين السلك العلوي والسلك السفلي: الفرع الأيسر فيه مقاومتان على التوالي 8.0 Ω (أعلى) و16.0 Ω (أسفل)، والفرع الأيمن فيه مقاومتان على التوالي 12.0 Ω و12.0 Ω."}]'::jsonb, '["18.0 V","24.0 V","9.0 V","12.0 V"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 65 — السؤال 70 والشكل 2-19'),
('mcq', 4, 'وُصلت مقاومتان 30.0 Ω و60.0 Ω معًا على التوازي، ثم وُصلت المجموعة على التوالي مع مقاومة 10.0 Ω ومصدر جهد 60.0 V. ما مقدار التيار الكلي في الدائرة؟', null, null, '["0.600 A","2.00 A","6.00 A","3.00 A"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 55–56 — مثال 4'),
('mcq', 5, 'تحتوي دائرة كهربائية مركّبة على ثلاث مقاومات: تستنفد الأولى قدرة مقدارها 4.0 W، والثانية 6.0 W، والثالثة 2.0 W. ما مقدار التيار الذي تسحبه الدائرة من بطارية جهدها 12.0 V؟', null, null, '["0.17 A","0.33 A","0.50 A","1.0 A"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 56 — مسائل تدريبية 19'),
('mcq', 6, 'في الدائرة المركّبة الآتية، ما مقدار القدرة المستنفدة في المقاومة $\mathrm{R}_\mathrm{4}$؟', null, '[{"src":"qimg/phys32/c2l2-o05-c.svg","alt":"دائرة مركّبة: بطارية جهدها 18 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_1 وقيمتها 6.0 Ω، ثم نقطة تفرّع يخرج منها فرعان رأسيان: الأيسر فيه المقاومة R_2 وقيمتها 12 Ω، والأيمن فيه مقاومتان على التوالي R_3 وقيمتها 4.0 Ω (أعلى) وR_4 وقيمتها 8.0 Ω (أسفل)، ويعود السلك السفلي إلى البطارية."}]'::jsonb, '["18 W","10 W","4.5 W","6.8 W"]'::jsonb, 'تحليل', 'حساب متعدد الخطوات', 'صعب', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة'),
('mcq', 7, 'يتصل 11 مصباحًا كهربائيًّا معًا على التوالي، وتتصل المجموعة على التوالي بمصباحين كهربائيين يتصلان معًا على التوازي. إذا كانت المصابيح جميعها متماثلة، فأيّها يكون سطوعه أكبر؟', null, null, '["كل مصباح من المصباحين؛ لأن فرق الجهد بين طرفي كل منهما يساوي جهد المصدر","كل من المصابيح الأحد عشر؛ لأن التيار الكلي يمر فيه وينقسم بين المصباحين","جميع المصابيح متساوية السطوع؛ لأنها متماثلة وموصولة جميعها بمصدر الجهد نفسه","كل مصباح من المصباحين؛ لأن المقاومة المكافئة لجزء التوازي أصغر فيمر فيه تيار أكبر"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 56 — مسائل تدريبية 20'),
('essay', 1, 'في الدائرة المركّبة الآتية، احسب: (a) المقاومة المكافئة للدائرة. (b) التيار الكلي. (c) الهبوط في الجهد عبر $\mathrm{R}_\mathrm{A}$ وعبر جزء التوازي. (d) التيار المار في كل من $\mathrm{R}_\mathrm{B}$ و$\mathrm{R}_\mathrm{C}$ و$\mathrm{R}_\mathrm{D}$، وتحقق من أن مجموعها يساوي التيار الكلي.', null, '[{"src":"qimg/phys32/c2l2-o05-e1.svg","alt":"دائرة مركّبة: بطارية جهدها 60.0 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_A وقيمتها 10.0 Ω، ثم ثلاثة فروع رأسية موصولة على التوازي بين السلك العلوي والسلك السفلي: R_B وقيمتها 20.0 Ω، ثم R_C وقيمتها 30.0 Ω، ثم R_D وقيمتها 60.0 Ω."}]'::jsonb, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة، ومثال 4 ص 55–56'),
('essay', 2, 'في دائرة مركّبة، وُصلت مقاومة $\mathrm{R}_1 = 5.0\ \Omega$ على التوالي مع مجموعة توازٍ مكوّنة من مقاومة مجهولة $\mathrm{R}_2$ ومقاومة $\mathrm{R}_3 = 15\ \Omega$، ووُصلت الدائرة بمصدر جهد 30 V، فقرأ أميتر في السلك الرئيس تيارًا مقداره 2.0 A. احسب: (a) المقاومة المكافئة للدائرة. (b) المقاومة المكافئة لجزء التوازي. (c) مقدار $\mathrm{R}_2$. (d) التيار المار في $\mathrm{R}_2$.', null, null, null, 'تحليل', 'مسألة عكسية', 'صعب', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة'),
('essay', 3, 'في الدائرة المركّبة الآتية، انفصل السلك عن المقاومة $\mathrm{R}_\mathrm{C}$ فانقطع فرعها. (a) احسب التيار الكلي وتيار $\mathrm{R}_\mathrm{B}$ والهبوط في الجهد عبر $\mathrm{R}_\mathrm{A}$ قبل الانفصال وبعده. (b) فسّر لماذا ازداد تيار $\mathrm{R}_\mathrm{B}$ مع أن التيار الكلي نقص.', null, '[{"src":"qimg/phys32/c2l2-o05-a.svg","alt":"دائرة مركّبة: بطارية جهدها 24.0 V على اليسار قطبها الموجب أعلى. في السلك العلوي المقاومة R_A وقيمتها 4.0 Ω، ثم نقطة تفرّع يخرج منها فرعان رأسيان بين السلك العلوي والسلك السفلي: الأول فيه المقاومة R_B وقيمتها 6.0 Ω، والثاني (أقصى اليمين) فيه المقاومة R_C وقيمتها 12.0 Ω، ويعود السلك السفلي إلى البطارية."}]'::jsonb, null, 'تحليل', 'تحليل تغيّر', 'صعب', 'الكتاب ص 55 — استراتيجيات حل المسألة: الدوائر الكهربائية المركّبة، ومسائل تدريبية 21 ص 56')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المقاومتان $\mathrm{R}_\mathrm{B}$ و$\mathrm{R}_\mathrm{C}$ على التوازي: $\frac{1}{\mathrm{R}_\mathrm{p}} = \frac{1}{6.0\ \Omega} + \frac{1}{12.0\ \Omega}$ ومنها $\mathrm{R}_\mathrm{p} = 4.0\ \Omega$. وهذه المجموعة على التوالي مع $\mathrm{R}_\mathrm{A}$: $\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{p} = 4.0\ \Omega + 4.0\ \Omega = 8.0\ \Omega$.', '["جمع المقاومات الثلاث كأنها كلها على التوالي ($4.0 + 6.0 + 12.0$).","عامل المقاومات الثلاث كأنها كلها على التوازي.","","اكتفى بالمقاومة المكافئة لجزء التوازي ونسي إضافة $\\mathrm{R}_\\mathrm{A}$ الموصولة على التوالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-27T21:51:39.407Z"}'::jsonb),
('mcq', 2, 0, 'المقاومة المكافئة $\mathrm{R} = 4.0\ \Omega + \frac{(6.0)(12.0)}{6.0 + 12.0}\ \Omega = 8.0\ \Omega$، والتيار الكلي $\mathrm{I} = \frac{24.0\ \text{V}}{8.0\ \Omega} = 3.0\ \text{A}$. فرق الجهد عبر جزء التوازي $\mathrm{V}_\mathrm{p} = (3.0\ \text{A})(4.0\ \Omega) = 12\ \text{V}$، إذن $\mathrm{I}_\mathrm{C} = \frac{12\ \text{V}}{12.0\ \Omega} = 1.0\ \text{A}$.', '["","افترض أن التيار الكلي ينقسم بالتساوي بين الفرعين، مع أن مقاومتيهما مختلفتان.","هذا التيار الكلي المار في $\\mathrm{R}_\\mathrm{A}$، لا تيار الفرع.","استعمل جهد البطارية كاملًا ($24.0 / 12.0$) بدل فرق الجهد عبر جزء التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-27T21:51:39.408Z"}'::jsonb),
('mcq', 3, 3, 'كل فرع مقاومته $24.0\ \Omega$، فالمقاومة المكافئة للفرعين $12.0\ \Omega$، والمقاومة الكلية $\mathrm{R} = 12.0 + 12.0 = 24.0\ \Omega$، والتيار الكلي $\mathrm{I} = \frac{36.0\ \text{V}}{24.0\ \Omega} = 1.50\ \text{A}$. ينقسم التيار بالتساوي بين الفرعين المتماثلين فيمر في الفرع الأيسر $0.750\ \text{A}$، والهبوط في الجهد عبر المقاومة 16.0 Ω: $\mathrm{V} = (0.750\ \text{A})(16.0\ \Omega) = 12.0\ \text{V}$.', '["هذا فرق الجهد عبر الفرع كله (8.0 Ω و16.0 Ω معًا)، لا عبر المقاومة 16.0 Ω وحدها.","ضرب التيار الكلي $1.50\\ \\text{A}$ في 16.0 Ω، ناسيًا أن التيار ينقسم بين الفرعين.","هذا الهبوط في الجهد عبر مقاومة 12.0 Ω في الفرع الأيمن ($0.750 \\times 12.0$)، لا عبر المقاومة المطلوبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-27T21:51:39.408Z"}'::jsonb),
('mcq', 4, 1, 'المقاومة المكافئة لجزء التوازي: $\frac{1}{\mathrm{R}_\mathrm{p}} = \frac{1}{30.0\ \Omega} + \frac{1}{60.0\ \Omega}$ فـ $\mathrm{R}_\mathrm{p} = 20.0\ \Omega$، والمقاومة الكلية $\mathrm{R} = 10.0 + 20.0 = 30.0\ \Omega$، والتيار $\mathrm{I} = \frac{60.0\ \text{V}}{30.0\ \Omega} = 2.00\ \text{A}$.', '["جمع المقاومات الثلاث على التوالي ($100.0\\ \\Omega$).","","قسم الجهد على المقاومة 10.0 Ω وحدها.","قسم الجهد على المقاومة المكافئة لجزء التوازي وحدها ونسي المقاومة 10.0 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.408Z"}'::jsonb),
('mcq', 5, 3, 'القدرة الكلية التي تزودها البطارية تساوي مجموع القدرات المستنفدة مهما كانت طريقة التوصيل: $\mathrm{P} = 4.0 + 6.0 + 2.0 = 12.0\ \text{W}$، والتيار $\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}} = \frac{12.0\ \text{W}}{12.0\ \text{V}} = 1.0\ \text{A}$.', '["استعمل قدرة المقاومة الثالثة وحدها (2.0 W).","استعمل متوسط القدرات (4.0 W) بدل مجموعها.","استعمل أكبر القدرات (6.0 W) وحدها بدل مجموع القدرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-27T21:51:39.408Z"}'::jsonb),
('mcq', 6, 2, 'الفرع الأيمن مقاومته $4.0 + 8.0 = 12\ \Omega$، وهو على التوازي مع $\mathrm{R}_2 = 12\ \Omega$ فمقاومتهما المكافئة $6.0\ \Omega$، والمقاومة الكلية $6.0 + 6.0 = 12\ \Omega$، والتيار الكلي $\mathrm{I} = \frac{18\ \text{V}}{12\ \Omega} = 1.5\ \text{A}$. ينقسم بالتساوي فيمر في $\mathrm{R}_\mathrm{4}$ تيار $0.75\ \text{A}$، والقدرة $\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.75\ \text{A})^2(8.0\ \Omega) = 4.5\ \text{W}$.', '["استعمل التيار الكلي $1.5\\ \\text{A}$ بدل تيار الفرع.","طبّق فرق جهد جزء التوازي كله (9.0 V) على $\\mathrm{R}_\\mathrm{4}$ وحدها: $\\frac{9.0^2}{8.0}$.","","ضرب فرق جهد جزء التوازي (9.0 V) في تيار الفرع (0.75 A)، وهذه قدرة الفرع كله لا قدرة $\\mathrm{R}_\\mathrm{4}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-27T21:51:39.408Z"}'::jsonb),
('mcq', 7, 1, 'يمر التيار الكلي $\mathrm{I}$ في كل مصباح من المصابيح الأحد عشر الموصولة على التوالي، أما المصباحان المتماثلان على التوازي فينقسم بينهما التيار، فيمر في كل منهما $\frac{\mathrm{I}}{2}$. وبما أن المصابيح متماثلة فالقدرة $\mathrm{P} = \mathrm{I}^2\mathrm{R}$ أكبر في كل مصباح من الأحد عشر؛ فسطوعه أكبر.', '["جزء التوازي على التوالي مع 11 مصباحًا، فلا يكون جهده مساويًا لجهد المصدر.","","التيار المار في المصباحين نصف التيار المار في كل من المصابيح الأحد عشر، فلا تتساوى القدرات.","صغر المقاومة المكافئة لجزء التوازي يعني جهدًا أصغر عبره، فيكون كل من المصباحين أخفت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-27T21:51:39.409Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\frac{1}{\mathrm{R}_\mathrm{p}} = \frac{1}{20.0} + \frac{1}{30.0} + \frac{1}{60.0} = \frac{6}{60.0}$ فـ $\mathrm{R}_\mathrm{p} = 10.0\ \Omega$، و$\mathrm{R} = \mathrm{R}_\mathrm{A} + \mathrm{R}_\mathrm{p} = 10.0 + 10.0 = 20.0\ \Omega$. (b) $\mathrm{I} = \frac{60.0\ \text{V}}{20.0\ \Omega} = 3.00\ \text{A}$. (c) $\mathrm{V}_\mathrm{A} = (3.00\ \text{A})(10.0\ \Omega) = 30.0\ \text{V}$، و$\mathrm{V}_\mathrm{p} = 60.0 - 30.0 = 30.0\ \text{V}$. (d) $\mathrm{I}_\mathrm{B} = \frac{30.0}{20.0} = 1.50\ \text{A}$، $\mathrm{I}_\mathrm{C} = \frac{30.0}{30.0} = 1.00\ \text{A}$، $\mathrm{I}_\mathrm{D} = \frac{30.0}{60.0} = 0.500\ \text{A}$، ومجموعها $3.00\ \text{A}$ يساوي التيار الكلي.', '["$\\mathrm{R}_\\mathrm{p} = 10.0\\ \\Omega$","$\\mathrm{R} = 20.0\\ \\Omega$","$\\mathrm{I} = 3.00\\ \\text{A}$","$\\mathrm{V}_\\mathrm{A} = 30.0\\ \\text{V}$ و$\\mathrm{V}_\\mathrm{p} = 30.0\\ \\text{V}$","تيارات الفروع 1.50 A و1.00 A و0.500 A","التحقق: المجموع 3.00 A"]'::jsonb, '["$\\frac{1}{\\mathrm{R}_\\mathrm{p}} = \\frac{1}{\\mathrm{R}_\\mathrm{B}} + \\frac{1}{\\mathrm{R}_\\mathrm{C}} + \\frac{1}{\\mathrm{R}_\\mathrm{D}}$ ← $\\mathrm{R}_\\mathrm{p} = 10.0\\ \\Omega$","$\\mathrm{R} = \\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{p} = 20.0\\ \\Omega$","$\\mathrm{I} = \\frac{\\mathrm{V}_{\\text{مصدر}}}{\\mathrm{R}} = 3.00\\ \\text{A}$","$\\mathrm{V}_\\mathrm{A} = \\mathrm{I}\\mathrm{R}_\\mathrm{A} = 30.0\\ \\text{V}$، $\\mathrm{V}_\\mathrm{p} = \\mathrm{V}_{\\text{مصدر}} - \\mathrm{V}_\\mathrm{A} = 30.0\\ \\text{V}$","$\\mathrm{I}_\\mathrm{B} = \\frac{\\mathrm{V}_\\mathrm{p}}{\\mathrm{R}_\\mathrm{B}} = 1.50\\ \\text{A}$، $\\mathrm{I}_\\mathrm{C} = 1.00\\ \\text{A}$، $\\mathrm{I}_\\mathrm{D} = 0.500\\ \\text{A}$","$1.50 + 1.00 + 0.500 = 3.00\\ \\text{A}$"]'::jsonb, '[{"element":"المقاومة المكافئة لجزء التوازي","marks":1},{"element":"المقاومة الكلية","marks":1},{"element":"التيار الكلي","marks":1},{"element":"الهبوطان في الجهد","marks":1},{"element":