select (select id from public.objectives where code = 'P32-C2-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يُصمَّم الأميتر بحيث تكون مقاومته أقل ما يمكن؟', null, null, '["لأنه يوصل على التوازي، فلو زادت مقاومته لمرّ فيه تيار كبير يتلفه","لأنه يوصل على التوالي، فلو زاد مقاومة الدائرة لقلّ التيار المقيس","ليمر فيه أقل تيار ممكن من تيار الدائرة فلا ترتفع درجة حرارته","لأن المقاومة الصغيرة تزيد فرق الجهد بين طرفيه فتسهل قراءته"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)'),
('mcq', 2, 'في الدائرة الآتية استُعمل أميتر رديء مقاومته 9.00 Ω. ما قراءة هذا الأميتر؟', null, '[{"src":"qimg/phys32/c2l2-o06-amm.svg","alt":"دائرة توالٍ: بطارية جهدها 9.00 V على اليسار قطبها الموجب أعلى، يليها في السلك العلوي أميتر (A) ثم المقاومة R_A وقيمتها 3.00 Ω، ثم تنزل الدائرة على اليمين عبر المقاومة R_B وقيمتها 6.00 Ω وتعود إلى البطارية."}]'::jsonb, '["1.00 A","1.50 A","4.50 A","0.500 A"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)'),
('mcq', 3, 'أيّ الأميترات الآتية أنسب لقياس التيار في دائرة توالٍ مقاومتها الكلية 10 Ω تقريبًا؟', null, null, '["أميتر مقاومته 0.01 Ω","أميتر مقاومته 10 Ω","أميتر مقاومته 1 kΩ","أميتر مقاومته 10 kΩ"]'::jsonb, 'تطبيق', 'اختيار جهاز', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر) والشكل 2-12a'),
('mcq', 4, 'كيف تُجعل مقاومة الأميتر صغيرة جدًّا في تركيبه؟', null, null, '["يوصل مع ملفه مقاومة كبيرة على التوالي","يوصل مع ملفه مقاومة كبيرة على التوازي","يوصل مع ملفه مقاومة صغيرة على التوازي","يوصل مع ملفه مقاومة صغيرة على التوالي"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)'),
('mcq', 5, 'استعمل طالب أميترًا تالفًا أصبحت مقاومته كبيرة. كيف تكون قراءته مقارنة بالتيار الحقيقي الذي يمر في الدائرة دون الأميتر؟', null, null, '["أقل منه؛ لأن الأميتر زاد المقاومة الكلية للدائرة فقلّ التيار","أكبر منه؛ لأن الأميتر زاد المقاومة الكلية للدائرة فزاد التيار","مساوية له؛ لأن التيار متساوٍ في جميع أجزاء دائرة التوالي","صفر؛ لأن الأميتر ذا المقاومة الكبيرة لا يمر فيه أي تيار"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)'),
('mcq', 6, 'ما الحالة المثالية لاستخدام الأميتر في قياس التيار المار في مقاومة؟', null, null, '["أن يمر فيه جزء صغير جدًّا من تيار المقاومة","أن يكون فرق الجهد بين طرفيه مساويًا لجهد المصدر","أن يوصل بين طرفي المقاومة دون قطع مسار التيار","ألّا يؤثر استخدامه في قيمة التيار المار في المقاومة"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)'),
('mcq', 7, 'دائرة توالٍ فيها مصدر جهد 20 V ومقاومتان 10.00 Ω و10.00 Ω، أُدخل فيها أميتر مقاومته 0.01 Ω. أيّ العبارات الآتية تصف أثر الأميتر؟', null, null, '["تصبح المقاومة الكلية 0.01 Ω فيزداد التيار كثيرًا","تصبح المقاومة الكلية 20.01 Ω فيقل التيار إلى النصف تقريبًا","تصبح المقاومة الكلية 20.01 Ω فيتغير التيار تغيرًا مهملًا","لا تتغير المقاومة الكلية لأن الأميتر يوصل على التوازي"]'::jsonb, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر) والشكل 2-12a'),
('essay', 1, 'لماذا يُصمَّم الأميتر بحيث تكون مقاومته صغيرة جدًّا؟ وكيف تُجعل مقاومته صغيرة في تركيبه؟', null, null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)، والتقويم ص 62 السؤال 37'),
('essay', 2, 'دائرة توالٍ فيها بطارية جهدها 12.0 V ومقاومتان 6.00 Ω و6.00 Ω. (a) احسب التيار المار في الدائرة دون أميتر. (b) احسب قراءة أميتر مقاومته 0.02 Ω يُدخل فيها، ونسبة النقص في التيار. (c) احسب قراءة أميتر مقاومته 6.00 Ω، ونسبة النقص في التيار. (d) ماذا تستنتج عن تصميم الأميتر؟', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر) والشكل 2-12a'),
('essay', 3, 'وصل طالب أميترًا على التوازي بين طرفي مصباح يعمل في دائرة بسيطة بدلًا من وصله على التوالي، ولا يوجد في الدائرة جهاز قياس آخر. حلّل ما يحدث للمصباح وللأميتر، مبيّنًا علاقة ذلك بصغر مقاومة الأميتر، ولماذا يُعدّ هذا التوصيل خطرًا على الأميتر.', null, null, null, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الأميتر)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يوصل الأميتر على التوالي، ويجب ألّا يؤثر في قيمة التيار المار في المقاومة؛ لذا يُصمَّم بحيث تكون مقاومته أقل ما يمكن، لأن التيار سيقل إذا عمل الأميتر على زيادة مقاومة الدائرة الكهربائية.', '["الأميتر يوصل على التوالي لا على التوازي.","","الأميتر يجب أن يمر فيه التيار كله الذي يقيسه، لا أقل تيار.","المقاومة الصغيرة تجعل الهبوط في الجهد عبر الأميتر صغيرًا جدًّا لا كبيرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-27T21:51:39.410Z"}'::jsonb),
('mcq', 2, 3, 'الأميتر على التوالي، فالمقاومة الكلية $\mathrm{R} = 3.00 + 6.00 + 9.00 = 18.0\ \Omega$، والتيار $\mathrm{I} = \frac{9.00\ \text{V}}{18.0\ \Omega} = 0.500\ \text{A}$، أي نصف التيار الذي كان يمر دون الأميتر (1.00 A)؛ ولهذا تُصمَّم مقاومة الأميتر صغيرة جدًّا.', '["أهمل مقاومة الأميتر ($\\frac{9.00}{9.00}$)، وهذا هو التيار الذي يمر دون الأميتر لا قراءته.","قسم الجهد على $\\mathrm{R}_\\mathrm{B}$ وحدها.","عامل المقاومتين كأنهما على التوازي ($2.00\\ \\Omega$) وأهمل الأميتر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.410Z"}'::jsonb),
('mcq', 3, 0, 'الأميتر يوصل على التوالي فتُضاف مقاومته إلى مقاومة الدائرة؛ والأميتر الذي مقاومته 0.01 Ω يزيد المقاومة الكلية بمقدار مهمل (من 10 Ω إلى 10.01 Ω)، فلا يكاد يغيّر التيار المقيس.', '["","يضاعف المقاومة الكلية تقريبًا فيقل التيار إلى النصف.","يزيد المقاومة الكلية نحو مئة مرة فيصبح التيار صغيرًا جدًّا.","مقاومة كبيرة جدًّا تناسب الفولتمتر لا الأميتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.410Z"}'::jsonb),
('mcq', 4, 2, 'يوصل مع ملف الأميتر مقاومة صغيرة على التوازي، فتصبح المقاومة المكافئة للأميتر أصغر من أصغرهما، أي صغيرة جدًّا.', '["هذا تركيب الفولتمتر، وهو يجعل المقاومة كبيرة جدًّا.","المقاومة الكبيرة على التوازي لا تجعل المكافئة صغيرة جدًّا.","","المقاومة على التوالي تزيد مقاومة الأميتر ولا تنقصها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-27T21:51:39.410Z"}'::jsonb),
('mcq', 5, 0, 'القراءة أقل من التيار الحقيقي؛ لأن الأميتر الموصول على التوالي زاد المقاومة الكلية للدائرة بمقاومته الكبيرة فقلّ التيار، فيقرأ تيارًا أقل من الذي كان يمر دونه.', '["","زيادة المقاومة تُنقص التيار ولا تزيده.","التيار متساوٍ في أجزاء الدائرة فعلًا، لكن قيمته نفسها نقصت بسبب مقاومة الأميتر.","يمر تيار في الأميتر لكنه أصغر؛ ولا يصبح صفرًا إلا إذا انقطع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.411Z"}'::jsonb),
('mcq', 6, 3, 'في الحالات المثالية يجب ألّا يؤثر استخدام الأميتر في قيمة التيار المار في المقاومة؛ ولذلك تُصمَّم مقاومته أقل ما يمكن.', '["الأميتر على التوالي يمر فيه تيار المقاومة كله.","الهبوط في الجهد عبر الأميتر المثالي صغير جدًّا لا يساوي جهد المصدر.","هذا توصيل على التوازي يناسب الفولتمتر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.411Z"}'::jsonb),
('mcq', 7, 2, 'الأميتر على التوالي: $\mathrm{R} = 0.01 + 10.00 + 10.00 = 20.01\ \Omega$، فيتغير التيار من $\frac{20}{20.00} = 1.000\ \text{A}$ إلى $\frac{20}{20.01} \approx 0.9995\ \text{A}$؛ أي إن مقاومة الأميتر الصغيرة غيّرت التيار بمقدار صغير جدًّا.', '["جمع المقاومات على التوالي لا يعطي مقاومة أصغر من أي منها.","زيادة المقاومة بمقدار 0.01 Ω فقط لا تنصّف التيار.","","الأميتر يوصل على التوالي فتُضاف مقاومته إلى مقاومة الدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.411Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُستخدم الأميتر لقياس التيار، ويوصل على التوالي مع المقاومة بقطع مسار التيار وإدخاله فيه؛ فتُضاف مقاومته إلى مقاومة الدائرة. وفي الحالة المثالية يجب ألّا يؤثر في قيمة التيار المقيس؛ لذا يُصمَّم بحيث تكون مقاومته أقل ما يمكن، لأن التيار سيقل إذا زاد الأميتر مقاومة الدائرة. ولتحقيق ذلك يوصل مع ملفه مقاومة صغيرة على التوازي.', '["يوصل على التوالي فتضاف مقاومته","يجب ألّا يغيّر التيار المقيس (زيادة المقاومة تُنقص التيار)","مقاومة صغيرة على التوازي مع ملفه"]'::jsonb, '[]'::jsonb, '[{"element":"التوصيل على التوالي وإضافة مقاومته","marks":1},{"element":"التعليل بعدم تغيير التيار","marks":1},{"element":"طريقة التركيب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعليل وطريقة التركيب صحيحان"},{"level":"2 درجتان","description":"التعليل صحيح دون طريقة التركيب"},{"level":"1 درجة","description":"ذكر التوصيل على التوالي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مقاومته صغيرة كي لا يمر فيه تيار","القول إن المقاومة الصغيرة توصل على التوالي مع ملفه","الخلط بين تعليل الأميتر وتعليل الفولتمتر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-27T21:51:39.411Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{I} = \frac{12.0\ \text{V}}{12.00\ \Omega} = 1.00\ \text{A}$. (b) $\mathrm{R} = 12.02\ \Omega$، $\mathrm{I} = \frac{12.0}{12.02} = 0.998\ \text{A}$، والنقص نحو 0.2% وهو مهمل. (c) $\mathrm{R} = 18.0\ \Omega$، $\mathrm{I} = \frac{12.0}{18.0} = 0.667\ \text{A}$، والنقص نحو 33% (الثلث)، فالقراءة بعيدة عن التيار الحقيقي. (d) يجب أن تكون مقاومة الأميتر صغيرة جدًّا مقارنة بمقاومة الدائرة؛ لأنه يوصل على التوالي، فإذا زاد مقاومة الدائرة قلّ التيار الذي يقيسه.', '["$\\mathrm{I} = 1.00\\ \\text{A}$","$0.998\\ \\text{A}$ ونقص نحو 0.2%","$0.667\\ \\text{A}$ ونقص نحو 33%","الاستنتاج: مقاومة الأميتر صغيرة جدًّا"]'::jsonb, '["$\\mathrm{I}_0 = \\frac{12.0}{6.00 + 6.00} = 1.00\\ \\text{A}$","$\\mathrm{I}_1 = \\frac{12.0}{12.02} = 0.998\\ \\text{A}$","$\\mathrm{I}_2 = \\frac{12.0}{18.0} = 0.667\\ \\text{A}$"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والاستنتاج صحيحة"},{"level":"2–3 درجات","description":"حسابان صحيحان مع استنتاج ناقص"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع مقاومة الأميتر على التوازي مع المقاومتين","إهمال مقاومة الأميتر في (c)","استنتاج أن الأميتر يجب أن تكون مقاومته كبيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.411Z"}'::jsonb),
('essay', 3, null::int, null, null, 'مقاومة الأميتر صغيرة جدًّا، فإذا وُصل على التوازي مع المصباح أصبح الجزء المكوَّن منهما مقاومته المكافئة صغيرة جدًّا (أصغر من مقاومة الأميتر)، فيسلك معظم التيار مسار الأميتر، ويكاد المصباح ينطفئ لأن التيار المار فيه صغير جدًّا. وتقل المقاومة الكلية للدائرة كثيرًا، فيصبح الأميتر كأنه دائرة قصر بين طرفي المصباح؛ فيمر فيه تيار كبير جدًّا قد يتلفه. فصغر مقاومة الأميتر الذي يفيد عند وصله على التوالي (لأنه لا يغيّر التيار) يصبح خطرًا عند وصله على التوازي؛ لذا يوصل الأميتر دائمًا على التوالي.', '["المقاومة المكافئة للمصباح والأميتر صغيرة جدًّا","معظم التيار يمر في الأميتر ويكاد المصباح ينطفئ","تيار كبير جدًّا في الأميتر كدائرة قصر","الربط: صغر المقاومة مفيد على التوالي وخطر على التوازي"]'::jsonb, '[]'::jsonb, '[{"element":"المقاومة المكافئة الصغيرة","marks":1},{"element":"أثره في المصباح","marks":1},{"element":"خطره على الأميتر","marks":1},{"element":"الربط بتعليل التصميم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التحليل كامل ومعلّل"},{"level":"2–3 درجات","description":"أثر واحد معلل مع الربط أو أثران دون ربط"},{"level":"1 درجة","description":"ذكر أن التوصيل خاطئ دون تحليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأميتر لا يمر فيه تيار لأنه على التوازي","القول إن المصباح يزداد سطوعه","إغفال أن التيار الكلي يزداد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-27T21:51:39.412Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
